import type { BankQuestion } from "@/lib/bank";

/** Ratio, Proportion and Mixtures (Quantitative Aptitude): 208 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"quant-ratio-1","question":"₹700 is divided in the ratio 3 : 4. The larger share is:","options":["₹300","₹350","₹400","₹450"],"answer":2,"explanation":"One part = 700 ÷ 7 = 100, so the larger share is 4 × 100 = ₹400.","difficulty":"easy","questionHi":"₹700 को 3 : 4 के अनुपात में बाँटा गया है। बड़ा हिस्सा क्या है?","optionsHi":["₹300","₹350","₹400","₹450"],"explanationHi":"एक भाग = 700 ÷ 7 = 100, इसलिए बड़ा हिस्सा = 4 × 100 = ₹400।","subtopic":"dividing-amounts"},
  {"id":"quant-ratio-2","question":"If A : B = 2 : 3 and B : C = 4 : 5, then A : C is:","options":["8 : 15","2 : 5","5 : 6","3 : 10"],"answer":0,"explanation":"Make B common: A : B = 8 : 12 and B : C = 12 : 15, so A : C = 8 : 15. 2 : 5 just takes the outer terms of the two ratios without equalising B.","difficulty":"moderate","questionHi":"यदि A : B = 2 : 3 और B : C = 4 : 5 है, तो A : C क्या है?","optionsHi":["8 : 15","2 : 5","5 : 6","3 : 10"],"explanationHi":"B को समान करने पर A : B = 8 : 12 और B : C = 12 : 15, इसलिए A : C = 8 : 15। 2 : 5 में दोनों अनुपातों के बाहरी पद ले लिए गए हैं, B को बराबर किए बिना।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-3","question":"The ages of A and B are in the ratio 4 : 5. After 5 years the ratio will be 5 : 6. What is A’s present age?","options":["15 years","20 years","25 years","30 years"],"answer":1,"explanation":"(4k + 5)/(5k + 5) = 5/6 gives 24k + 30 = 25k + 25, so k = 5 and A is 20.","difficulty":"hard","questionHi":"A और B की आयु का अनुपात 4 : 5 है। 5 वर्ष बाद यह अनुपात 5 : 6 हो जाएगा। A की वर्तमान आयु क्या है?","optionsHi":["15 वर्ष","20 वर्ष","25 वर्ष","30 वर्ष"],"explanationHi":"(4k + 5)/(5k + 5) = 5/6 से 24k + 30 = 25k + 25, अतः k = 5 और A की आयु 20 वर्ष है।","subtopic":"ages"},
  {"id":"quant-ratio-4","question":"A 30-litre mixture has milk and water in the ratio 7 : 3. How much water must be added to make it 3 : 2?","options":["3 litres","5 litres","7 litres","9 litres"],"answer":1,"explanation":"Milk = 21 L, water = 9 L. For 3 : 2, water must be 21 × 2/3 = 14 L, so add 5 L.","difficulty":"very-hard","questionHi":"30 लीटर के एक मिश्रण में दूध और पानी का अनुपात 7 : 3 है। इसे 3 : 2 बनाने के लिए कितना पानी मिलाना होगा?","optionsHi":["3 लीटर","5 लीटर","7 लीटर","9 लीटर"],"explanationHi":"दूध = 21 L, पानी = 9 L। 3 : 2 के लिए पानी 21 × 2/3 = 14 L होना चाहिए, इसलिए 5 L मिलाना होगा।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-5","question":"If a : b = 3 : 5, then (2a + b) : (a + 2b) is:","options":["6 : 10","1 : 1","13 : 11","11 : 13"],"answer":3,"explanation":"Put a = 3, b = 5: (6 + 5) : (3 + 10) = 11 : 13. 13 : 11 reverses the order, and 6 : 10 doubles only a in the first term.","difficulty":"easy","source":"SSC CGL · SSC CHSL","questionHi":"यदि a : b = 3 : 5 है, तो (2a + b) : (a + 2b) क्या है?","optionsHi":["6 : 10","1 : 1","13 : 11","11 : 13"],"explanationHi":"a = 3, b = 5 रखने पर (6 + 5) : (3 + 10) = 11 : 13। 13 : 11 में क्रम उलट गया है, और 6 : 10 में पहले पद में केवल a को दोगुना किया गया है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-6","question":"The fourth proportional to 6, 9 and 14 is:","options":["21","16","18","12"],"answer":0,"explanation":"For a fourth proportional, 6 : 9 = 14 : x, so x = 9 × 14/6 = 21. 16 adds a fixed gap instead of scaling, and 12 or 18 are multiples of the given terms that do not keep 6 : 9 = 14 : x.","difficulty":"easy","source":"SSC CGL · RRB NTPC","questionHi":"6, 9 और 14 का चतुर्थानुपाती क्या है?","optionsHi":["21","16","18","12"],"explanationHi":"चतुर्थानुपाती के लिए 6 : 9 = 14 : x, अतः x = 9 × 14/6 = 21। 16 में अनुपात की जगह एक निश्चित अंतर जोड़ा गया है, और 12 या 18 दिए गए पदों के गुणज हैं जो 6 : 9 = 14 : x को संतुष्ट नहीं करते।","subtopic":"proportion-variation"},
  {"id":"quant-ratio-7","question":"If A : B = 3 : 4, B : C = 5 : 6 and C : D = 7 : 8, then A : D is:","options":["3 : 8","15 : 32","35 : 64","21 : 32"],"answer":2,"explanation":"Chain the ratios: A/D = (3/4)(5/6)(7/8) = 105/192 = 35/64. 3 : 8 takes only the outer numbers, and 15 : 32 skips a link in the chain.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"यदि A : B = 3 : 4, B : C = 5 : 6 और C : D = 7 : 8 है, तो A : D क्या है?","optionsHi":["3 : 8","15 : 32","35 : 64","21 : 32"],"explanationHi":"अनुपातों को जोड़ने पर: A/D = (3/4)(5/6)(7/8) = 105/192 = 35/64। 3 : 8 में केवल बाहरी संख्याएँ ली गई हैं, और 15 : 32 में श्रृंखला की एक कड़ी छूट गई है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-8","question":"₹1,890 is divided among A, B and C so that A : B = 2 : 3 and B : C = 4 : 5. A's share is:","options":["₹810","₹540","₹648","₹432"],"answer":3,"explanation":"A : B : C = 8 : 12 : 15 (35 parts). One part = 1,890/35 = 54, so A = 8 × 54 = ₹432.","difficulty":"moderate","source":"SSC CGL · IBPS PO","questionHi":"₹1,890 को A, B और C में इस प्रकार बाँटा गया कि A : B = 2 : 3 और B : C = 4 : 5 है। A का हिस्सा क्या है?","optionsHi":["₹810","₹540","₹648","₹432"],"explanationHi":"A : B : C = 8 : 12 : 15 (कुल 35 भाग)। एक भाग = 1,890/35 = 54, अतः A = 8 × 54 = ₹432।","subtopic":"dividing-amounts"},
  {"id":"quant-ratio-9","question":"A 60-litre mixture contains milk and water in the ratio 2 : 1. How much water must be added to make the ratio 1 : 2?","options":["40 litres","80 litres","60 litres","20 litres"],"answer":2,"explanation":"Milk = 40 L, water = 20 L. For 1 : 2 the water must be 80 L, so add 60 L.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"60 लीटर के एक मिश्रण में दूध और पानी का अनुपात 2 : 1 है। अनुपात को 1 : 2 बनाने के लिए कितना पानी मिलाना होगा?","optionsHi":["40 लीटर","80 लीटर","60 लीटर","20 लीटर"],"explanationHi":"दूध = 40 L, पानी = 20 L। 1 : 2 के लिए पानी 80 L होना चाहिए, इसलिए 60 L मिलाना होगा।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-10","question":"In what ratio must tea at ₹60 per kg be mixed with tea at ₹80 per kg so that the mixture costs ₹65 per kg?","options":["3 : 1","2 : 1","4 : 1","1 : 3"],"answer":0,"explanation":"Alligation: (80 − 65) : (65 − 60) = 15 : 5 = 3 : 1 (cheaper : dearer).","difficulty":"moderate","source":"SSC CGL · RRB NTPC","questionHi":"₹60 प्रति किग्रा वाली चाय को ₹80 प्रति किग्रा वाली चाय के साथ किस अनुपात में मिलाया जाए कि मिश्रण की कीमत ₹65 प्रति किग्रा हो?","optionsHi":["3 : 1","2 : 1","4 : 1","1 : 3"],"explanationHi":"एलिगेशन विधि से: (80 − 65) : (65 − 60) = 15 : 5 = 3 : 1 (सस्ती : महँगी)।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-11","question":"The present ages of A and B are in the ratio 5 : 7. Eight years ago the ratio was 3 : 5. The sum of their present ages is:","options":["48 years","60 years","40 years","36 years"],"answer":0,"explanation":"(5x − 8)/(7x − 8) = 3/5 → 25x − 40 = 21x − 24 → x = 4. Ages 20 and 28, sum 48.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"A और B की वर्तमान आयु का अनुपात 5 : 7 है। आठ वर्ष पहले यह अनुपात 3 : 5 था। उनकी वर्तमान आयु का योग क्या है?","optionsHi":["48 वर्ष","60 वर्ष","40 वर्ष","36 वर्ष"],"explanationHi":"(5x − 8)/(7x − 8) = 3/5 → 25x − 40 = 21x − 24 → x = 4। आयु 20 और 28 वर्ष है, योग 48।","subtopic":"ages"},
  {"id":"quant-ratio-12","question":"A bag has 1-rupee, 50-paise and 25-paise coins in the ratio 3 : 4 : 5, totalling ₹250. The number of 50-paise coins is:","options":["100","160","120","200"],"answer":1,"explanation":"Value = 3x × 1 + 4x × 0.5 + 5x × 0.25 = 6.25x = 250 → x = 40. 50-paise coins = 4 × 40 = 160.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक थैले में 1 रुपये, 50 पैसे और 25 पैसे के सिक्के 3 : 4 : 5 के अनुपात में हैं, और कुल राशि ₹250 है। 50 पैसे के सिक्कों की संख्या क्या है?","optionsHi":["100","160","120","200"],"explanationHi":"मूल्य = 3x × 1 + 4x × 0.5 + 5x × 0.25 = 6.25x = 250 → x = 40। 50 पैसे के सिक्के = 4 × 40 = 160।","subtopic":"coins"},
  {"id":"quant-ratio-13","question":"An 80-litre mixture has milk and water in the ratio 3 : 1. 20 litres of the mixture are taken out and replaced by water. The new ratio of milk to water is:","options":["2 : 1","3 : 2","9 : 7","7 : 9"],"answer":2,"explanation":"Removing 20 L keeps the ratio: 60 L left with 45 L milk and 15 L water. Adding 20 L water: 45 : 35 = 9 : 7.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"80 लीटर के एक मिश्रण में दूध और पानी का अनुपात 3 : 1 है। इसमें से 20 लीटर मिश्रण निकालकर उसकी जगह पानी डाल दिया जाता है। दूध और पानी का नया अनुपात क्या है?","optionsHi":["2 : 1","3 : 2","9 : 7","7 : 9"],"explanationHi":"20 L निकालने पर अनुपात वही रहता है: 60 L बचा, जिसमें 45 L दूध और 15 L पानी है। 20 L पानी मिलाने पर: 45 : 35 = 9 : 7।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-14","question":"The incomes of A and B are in the ratio 4 : 5 and their expenditures in the ratio 7 : 9. If each saves ₹3,000, A's income is:","options":["₹20,000","₹21,000","₹30,000","₹24,000"],"answer":3,"explanation":"4x − 7y = 3,000 and 5x − 9y = 3,000. Subtracting gives x = 2y, so 8y − 7y = 3,000, y = 3,000 and x = 6,000. A's income = 4x = ₹24,000.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"A और B की आय का अनुपात 4 : 5 है और उनके व्यय का अनुपात 7 : 9 है। यदि प्रत्येक ₹3,000 बचाता है, तो A की आय क्या है?","optionsHi":["₹20,000","₹21,000","₹30,000","₹24,000"],"explanationHi":"4x − 7y = 3,000 और 5x − 9y = 3,000। घटाने पर x = 2y, इसलिए 8y − 7y = 3,000, y = 3,000 और x = 6,000। A की आय = 4x = ₹24,000।","subtopic":"income-expenses"},
  {"id":"quant-ratio-15","question":"A invests ₹20,000 for 12 months and B invests ₹30,000 for 8 months in a business. Out of a profit of ₹36,000, B's share is:","options":["₹14,400","₹18,000","₹24,000","₹21,600"],"answer":1,"explanation":"Capital × time: 20,000 × 12 = 2,40,000 and 30,000 × 8 = 2,40,000, ratio 1 : 1. B gets ₹18,000. Dividing in the ratio of capital alone (2 : 3) gives the wrong ₹21,600.","difficulty":"hard","source":"SSC CGL · SBI PO","questionHi":"एक व्यापार में A ₹20,000 को 12 महीने के लिए और B ₹30,000 को 8 महीने के लिए लगाता है। ₹36,000 के लाभ में से B का हिस्सा क्या है?","optionsHi":["₹14,400","₹18,000","₹24,000","₹21,600"],"explanationHi":"पूँजी × समय: 20,000 × 12 = 2,40,000 और 30,000 × 8 = 2,40,000, अनुपात 1 : 1। B को ₹18,000 मिलेंगे। केवल पूँजी के अनुपात (2 : 3) में बाँटने पर गलत उत्तर ₹21,600 आता है।","subtopic":"partnership"},
  {"id":"quant-ratio-16","question":"Alloy P has copper and zinc in the ratio 2 : 3 and alloy Q in the ratio 3 : 2. If P and Q are mixed in the ratio 2 : 3 by weight, the ratio of copper to zinc in the new alloy is:","options":["1 : 1","5 : 6","12 : 13","13 : 12"],"answer":3,"explanation":"2 kg of P has 0.8 copper and 1.2 zinc; 3 kg of Q has 1.8 copper and 1.2 zinc. Totals: copper 2.6, zinc 2.4, ratio 13 : 12.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"मिश्रधातु P में ताँबा और जस्ता 2 : 3 के अनुपात में हैं और मिश्रधातु Q में 3 : 2 के अनुपात में। यदि P और Q को भार के अनुसार 2 : 3 के अनुपात में मिलाया जाए, तो नई मिश्रधातु में ताँबे और जस्ते का अनुपात क्या होगा?","optionsHi":["1 : 1","5 : 6","12 : 13","13 : 12"],"explanationHi":"P के 2 kg में 0.8 ताँबा और 1.2 जस्ता है; Q के 3 kg में 1.8 ताँबा और 1.2 जस्ता है। कुल: ताँबा 2.6, जस्ता 2.4, अनुपात 13 : 12।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-17","question":"A grocer mixes rice costing ₹30 per kg with rice costing ₹45 per kg and sells the mixture at ₹44 per kg, gaining 10%. The ratio of the cheaper to the dearer rice is:","options":["1 : 2","1 : 4","4 : 1","2 : 1"],"answer":0,"explanation":"Cost price of the mixture = 44/1.1 = ₹40 per kg. Alligation: (45 − 40) : (40 − 30) = 5 : 10 = 1 : 2.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"एक दुकानदार ₹30 प्रति किग्रा वाले चावल को ₹45 प्रति किग्रा वाले चावल के साथ मिलाता है और मिश्रण को ₹44 प्रति किग्रा पर बेचकर 10% लाभ कमाता है। सस्ते और महँगे चावल का अनुपात क्या है?","optionsHi":["1 : 2","1 : 4","4 : 1","2 : 1"],"explanationHi":"मिश्रण का क्रय मूल्य = 44/1.1 = ₹40 प्रति किग्रा। एलिगेशन विधि से: (45 − 40) : (40 − 30) = 5 : 10 = 1 : 2।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-18","question":"A container has 40 litres of pure milk. 8 litres are drawn out and replaced with water, and this is done once more. The quantity of milk now left is:","options":["25.6 litres","26 litres","24 litres","32 litres"],"answer":0,"explanation":"Milk left = 40 × (1 − 8/40)² = 40 × 0.8² = 40 × 0.64 = 25.6 L. 24 L assumes 8 L of milk is removed each time.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक बर्तन में 40 लीटर शुद्ध दूध है। उसमें से 8 लीटर निकालकर पानी मिला दिया जाता है, और यह क्रिया एक बार और दोहराई जाती है। अब बर्तन में कितना दूध बचा है?","optionsHi":["25.6 लीटर","26 लीटर","24 लीटर","32 लीटर"],"explanationHi":"बचा दूध = 40 × (1 − 8/40)² = 40 × 0.8² = 40 × 0.64 = 25.6 L। 24 L तब आता है जब हर बार 8 L दूध ही निकाला जाए।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-19","question":"A milkman has 20 litres of milk costing ₹40 per litre. He adds water and sells the mixture at ₹40 per litre, making a profit of 25%. The quantity of water added is:","options":["4 litres","8 litres","10 litres","5 litres"],"answer":3,"explanation":"Cost = ₹800; for 25% profit he must collect ₹1,000 at ₹40 per litre, i.e. sell 25 litres. Water added = 25 − 20 = 5 L.","difficulty":"very-hard","source":"SSC CGL · RRB NTPC","questionHi":"एक दूधवाले के पास ₹40 प्रति लीटर वाला 20 लीटर दूध है। वह उसमें पानी मिलाकर मिश्रण को ₹40 प्रति लीटर पर बेचता है और 25% लाभ कमाता है। मिलाए गए पानी की मात्रा क्या है?","optionsHi":["4 लीटर","8 लीटर","10 लीटर","5 लीटर"],"explanationHi":"लागत = ₹800; 25% लाभ के लिए उसे ₹1,000 मिलने चाहिए, यानी ₹40 प्रति लीटर पर 25 लीटर बेचना होगा। मिलाया गया पानी = 25 − 20 = 5 L।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-20","question":"If x : y = 3 : 4 and x² + y² = 400, then x + y is:","options":["24","28","20","32"],"answer":1,"explanation":"x = 3k, y = 4k: 9k² + 16k² = 25k² = 400, k = 4. x = 12, y = 16, x + y = 28.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"यदि x : y = 3 : 4 और x² + y² = 400 है, तो x + y क्या है?","optionsHi":["24","28","20","32"],"explanationHi":"x = 3k, y = 4k: 9k² + 16k² = 25k² = 400, k = 4। x = 12, y = 16, x + y = 28।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-21","question":"Three vessels contain milk and water in the ratios 1 : 2, 2 : 3 and 3 : 4. Equal volumes from all three are mixed. The ratio of milk to water in the mixture is:","options":["193 : 122","122 : 193","2 : 3","6 : 24"],"answer":1,"explanation":"Milk fractions 1/3, 2/5, 3/7; with LCM 105 per vessel: milk 35 + 42 + 45 = 122, water 70 + 63 + 60 = 193. Ratio 122 : 193. Adding the ratio terms directly (6 : 9) is wrong because the vessels' totals differ.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"तीन बर्तनों में दूध और पानी क्रमशः 1 : 2, 2 : 3 और 3 : 4 के अनुपात में हैं। तीनों से बराबर आयतन लेकर मिलाया जाता है। मिश्रण में दूध और पानी का अनुपात क्या है?","optionsHi":["193 : 122","122 : 193","2 : 3","6 : 24"],"explanationHi":"दूध के भिन्न 1/3, 2/5, 3/7; प्रति बर्तन LCM 105 लेने पर: दूध 35 + 42 + 45 = 122, पानी 70 + 63 + 60 = 193। अनुपात 122 : 193। अनुपात के पदों को सीधे जोड़ना (6 : 9) गलत है क्योंकि बर्तनों के कुल भाग अलग-अलग हैं।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-22","question":"How many of the following statements are correct?\n1. If a : b = 2 : 3 and b : c = 2 : 3, then a : c = 4 : 9.\n2. The mean proportional between 4 and 25 is 10.\n3. If a/b = c/d, then (a + b)/(a − b) = (c + d)/(c − d).\n4. Doubling the quantity of every component of a mixture leaves its ratio unchanged.","options":["Only one","Only two","Only three","All four"],"answer":3,"explanation":"All four are true: 2/3 × 2/3 = 4/9; √(4 × 25) = 10; componendo and dividendo gives (a + b)/(a − b) = (c + d)/(c − d); and scaling every part by 2 keeps the ratio the same.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"निम्नलिखित में से कितने कथन सही हैं?\n1. यदि a : b = 2 : 3 और b : c = 2 : 3 है, तो a : c = 4 : 9।\n2. 4 और 25 का मध्यानुपाती 10 है।\n3. यदि a/b = c/d है, तो (a + b)/(a − b) = (c + d)/(c − d)।\n4. किसी मिश्रण के प्रत्येक घटक की मात्रा को दोगुना करने पर उसका अनुपात अपरिवर्तित रहता है।","optionsHi":["केवल एक","केवल दो","केवल तीन","चारों"],"explanationHi":"चारों कथन सही हैं: 2/3 × 2/3 = 4/9; √(4 × 25) = 10; योगांतरानुपात (componendo-dividendo) से (a + b)/(a − b) = (c + d)/(c − d); और प्रत्येक भाग को 2 से गुणा करने पर अनुपात वही रहता है।","subtopic":"proportion-variation"},
  {"id":"quant-ratio-23","question":"A starts a business with ₹50,000. After 3 months B joins with ₹40,000, and 3 months after that A withdraws ₹20,000. At the end of the year the profit is shared between A and B in the ratio:","options":["3 : 4","5 : 4","4 : 3","1 : 1"],"answer":2,"explanation":"A: 50,000 × 6 + 30,000 × 6 = 4,80,000. B: 40,000 × 9 = 3,60,000. Ratio 480 : 360 = 4 : 3.","difficulty":"very-hard","source":"SSC CGL · SBI PO","questionHi":"A ₹50,000 से व्यापार शुरू करता है। 3 महीने बाद B ₹40,000 लेकर जुड़ता है, और उसके 3 महीने बाद A ₹20,000 निकाल लेता है। वर्ष के अंत में लाभ A और B में किस अनुपात में बँटेगा?","optionsHi":["3 : 4","5 : 4","4 : 3","1 : 1"],"explanationHi":"A: 50,000 × 6 + 30,000 × 6 = 4,80,000। B: 40,000 × 9 = 3,60,000। अनुपात 480 : 360 = 4 : 3।","subtopic":"partnership"},
  {"id":"quant-ratio-24","question":"Alloy A contains gold and copper in the ratio 7 : 2 and alloy B in the ratio 7 : 11. Equal weights of the two alloys are melted together. The ratio of gold to copper in the new alloy is:","options":["5 : 7","7 : 5","14 : 13","1 : 1"],"answer":1,"explanation":"Per unit weight: gold = 7/9 + 7/18 = 21/18, copper = 2/9 + 11/18 = 15/18. Ratio 21 : 15 = 7 : 5.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"मिश्रधातु A में सोना और ताँबा 7 : 2 के अनुपात में हैं और मिश्रधातु B में 7 : 11 के अनुपात में। दोनों मिश्रधातुओं का बराबर भार लेकर पिघलाया जाता है। नई मिश्रधातु में सोने और ताँबे का अनुपात क्या है?","optionsHi":["5 : 7","7 : 5","14 : 13","1 : 1"],"explanationHi":"प्रति इकाई भार: सोना = 7/9 + 7/18 = 21/18, ताँबा = 2/9 + 11/18 = 15/18। अनुपात 21 : 15 = 7 : 5।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-25","question":"What is the mean proportional between 9 and 16?","options":["12.5","12","25","144"],"answer":1,"explanation":"Mean proportional = √(9 × 16) = √144 = 12. 12.5 is the arithmetic mean.","difficulty":"easy","source":"RRB NTPC · SSC CHSL","questionHi":"9 और 16 के बीच मध्यानुपाती क्या है?","optionsHi":["12.5","12","25","144"],"explanationHi":"मध्यानुपाती = √(9 × 16) = √144 = 12। 12.5 समांतर माध्य है।","subtopic":"proportion-variation"},
  {"id":"quant-ratio-26","question":"₹5,400 is divided among A, B and C in the ratio 1/2 : 1/3 : 1/6. What is B's share?","options":["₹1,800","₹2,700","₹900","₹1,200"],"answer":0,"explanation":"Multiply by 6: 1/2 : 1/3 : 1/6 = 3 : 2 : 1. B = 2/6 × 5,400 = ₹1,800. ₹2,700 is A's share.","difficulty":"moderate","source":"SSC CGL","questionHi":"₹5,400 को A, B और C में 1/2 : 1/3 : 1/6 के अनुपात में बाँटा जाता है। B का हिस्सा क्या है?","optionsHi":["₹1,800","₹2,700","₹900","₹1,200"],"explanationHi":"6 से गुणा करने पर: 1/2 : 1/3 : 1/6 = 3 : 2 : 1। B = 2/6 × 5,400 = ₹1,800। ₹2,700 A का हिस्सा है।","subtopic":"dividing-amounts"},
  {"id":"quant-ratio-27","question":"Two numbers are in the ratio 3 : 5. If 9 is added to each, the ratio becomes 3 : 4. What is the larger number?","options":["9","25","20","15"],"answer":3,"explanation":"(3x + 9)/(5x + 9) = 3/4 → 12x + 36 = 15x + 27 → x = 3. The numbers are 9 and 15.","difficulty":"moderate","source":"SSC CGL","questionHi":"दो संख्याओं का अनुपात 3 : 5 है। यदि प्रत्येक में 9 जोड़ दिया जाए, तो अनुपात 3 : 4 हो जाता है। बड़ी संख्या क्या है?","optionsHi":["9","25","20","15"],"explanationHi":"(3x + 9)/(5x + 9) = 3/4 → 12x + 36 = 15x + 27 → x = 3। संख्याएँ 9 और 15 हैं।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-28","question":"The salaries of A and B are in the ratio 2 : 3. If each gets a raise of ₹5,000, the ratio becomes 3 : 4. What is B's present salary?","options":["₹10,000","₹20,000","₹15,000","₹12,000"],"answer":2,"explanation":"(2x + 5,000)/(3x + 5,000) = 3/4 → 8x + 20,000 = 9x + 15,000 → x = 5,000. B = 3x = ₹15,000.","difficulty":"hard","source":"SSC CGL","questionHi":"A और B के वेतन का अनुपात 2 : 3 है। यदि प्रत्येक के वेतन में ₹5,000 की वृद्धि हो जाए, तो अनुपात 3 : 4 हो जाता है। B का वर्तमान वेतन क्या है?","optionsHi":["₹10,000","₹20,000","₹15,000","₹12,000"],"explanationHi":"(2x + 5,000)/(3x + 5,000) = 3/4 → 8x + 20,000 = 9x + 15,000 → x = 5,000। B = 3x = ₹15,000।","subtopic":"income-expenses"},
  {"id":"quant-ratio-29","question":"A 40-litre mixture contains milk and water in the ratio 3 : 1. How many litres of the mixture must be taken out and replaced with pure milk to make the ratio 4 : 1?","options":["10 litres","8 litres","5 litres","12 litres"],"answer":1,"explanation":"Milk 30, water 10. Removing x litres removes 0.25x water; water left = 10 − 0.25x must be 1/5 of 40 = 8 → x = 8 litres. 10 litres is the milk to add without removing anything.","difficulty":"hard","source":"SSC CGL Tier-2","questionHi":"40 लीटर के एक मिश्रण में दूध और पानी का अनुपात 3 : 1 है। अनुपात को 4 : 1 बनाने के लिए मिश्रण का कितने लीटर निकालकर उसकी जगह शुद्ध दूध डालना होगा?","optionsHi":["10 लीटर","8 लीटर","5 लीटर","12 लीटर"],"explanationHi":"दूध 30, पानी 10। x लीटर निकालने पर 0.25x पानी निकलता है; बचा पानी = 10 − 0.25x, जो 40 का 1/5 = 8 होना चाहिए → x = 8 लीटर। 10 लीटर वह दूध है जो बिना कुछ निकाले मिलाना पड़ता।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-30","question":"A, B and C invest capitals in the ratio 3 : 4 : 5 for 4, 3 and 2 months respectively. Out of a profit of ₹34,000, what is C's share?","options":["₹10,000","₹14,167","₹12,000","₹11,333"],"answer":0,"explanation":"Profit ratio = 3×4 : 4×3 : 5×2 = 12 : 12 : 10 (34 parts). C = 10/34 × 34,000 = ₹10,000. ₹14,167 ignores the time.","difficulty":"hard","source":"SSC CGL","questionHi":"A, B और C क्रमशः 4, 3 और 2 महीने के लिए 3 : 4 : 5 के अनुपात में पूँजी लगाते हैं। ₹34,000 के लाभ में से C का हिस्सा क्या है?","optionsHi":["₹10,000","₹14,167","₹12,000","₹11,333"],"explanationHi":"लाभ अनुपात = 3×4 : 4×3 : 5×2 = 12 : 12 : 10 (कुल 34 भाग)। C = 10/34 × 34,000 = ₹10,000। ₹14,167 में समय को नहीं गिना गया है।","subtopic":"partnership"},
  {"id":"quant-ratio-31","question":"A milkman buys milk at ₹48 per litre, mixes water with it and sells the mixture at ₹54 per litre, gaining 35%. What is the ratio of water to milk in the mixture?","options":["1 : 8","1 : 4","5 : 1","1 : 5"],"answer":3,"explanation":"Cost price of the mixture = 54 ÷ 1.35 = ₹40 per litre. By alligation (milk 48, water 0): milk : water = (40 − 0) : (48 − 40) = 40 : 8 = 5 : 1, so water : milk = 1 : 5.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"एक दूधवाला ₹48 प्रति लीटर पर दूध खरीदता है, उसमें पानी मिलाता है और मिश्रण को ₹54 प्रति लीटर पर बेचकर 35% लाभ कमाता है। मिश्रण में पानी और दूध का अनुपात क्या है?","optionsHi":["1 : 8","1 : 4","5 : 1","1 : 5"],"explanationHi":"मिश्रण का क्रय मूल्य = 54 ÷ 1.35 = ₹40 प्रति लीटर। एलिगेशन विधि से (दूध 48, पानी 0): दूध : पानी = (40 − 0) : (48 − 40) = 40 : 8 = 5 : 1, इसलिए पानी : दूध = 1 : 5।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-32","question":"Three numbers are in the ratio 2 : 3 : 5 and the sum of their squares is 1,368. What is the sum of the numbers?","options":["36","50","60","72"],"answer":2,"explanation":"(4 + 9 + 25)x² = 38x² = 1,368 → x² = 36 → x = 6. The numbers are 12, 18 and 30, total 60.","difficulty":"very-hard","source":"SSC CGL","questionHi":"तीन संख्याएँ 2 : 3 : 5 के अनुपात में हैं और उनके वर्गों का योग 1,368 है। संख्याओं का योग क्या है?","optionsHi":["36","50","60","72"],"explanationHi":"(4 + 9 + 25)x² = 38x² = 1,368 → x² = 36 → x = 6। संख्याएँ 12, 18 और 30 हैं, योग 60।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-33","question":"A vessel contains 60 litres of pure milk. 6 litres are drawn out and replaced with water, and this is done three times in all. How much milk is left?","options":["42 litres","43.74 litres","48.6 litres","45 litres"],"answer":1,"explanation":"Milk left = 60 × (1 − 6/60)³ = 60 × 0.9³ = 60 × 0.729 = 43.74 litres. 42 litres simply subtracts 18 litres.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"एक बर्तन में 60 लीटर शुद्ध दूध है। उसमें से 6 लीटर निकालकर पानी मिला दिया जाता है, और यह क्रिया कुल तीन बार की जाती है। कितना दूध बचा है?","optionsHi":["42 लीटर","43.74 लीटर","48.6 लीटर","45 लीटर"],"explanationHi":"बचा दूध = 60 × (1 − 6/60)³ = 60 × 0.9³ = 60 × 0.729 = 43.74 लीटर। 42 लीटर में केवल 18 लीटर घटा दिया गया है।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-34","question":"The incomes of A, B and C are in the ratio 5 : 7 : 9 and their expenditures in the ratio 3 : 5 : 6. If A saves one-fifth of his income, what is the ratio of their savings?","options":["3 : 1 : 3","1 : 1 : 1","2 : 2 : 3","3 : 2 : 3"],"answer":0,"explanation":"Incomes 5x, 7x, 9x. A spends 4x = 3y → y = 4x/3. B spends 20x/3, saving 7x − 20x/3 = x/3. C spends 8x, saving x. A saves x. Ratio x : x/3 : x = 3 : 1 : 3.","difficulty":"very-hard","source":"SSC CGL Tier-2","questionHi":"A, B और C की आय का अनुपात 5 : 7 : 9 है और उनके व्यय का अनुपात 3 : 5 : 6 है। यदि A अपनी आय का एक-पाँचवाँ भाग बचाता है, तो उनकी बचत का अनुपात क्या है?","optionsHi":["3 : 1 : 3","1 : 1 : 1","2 : 2 : 3","3 : 2 : 3"],"explanationHi":"आय 5x, 7x, 9x। A का व्यय 4x = 3y → y = 4x/3। B का व्यय 20x/3, बचत 7x − 20x/3 = x/3। C का व्यय 8x, बचत x। A की बचत x। अनुपात x : x/3 : x = 3 : 1 : 3।","subtopic":"income-expenses"},
  {"id":"quant-ratio-35","question":"What is the third proportional to 9 and 12?","options":["15","10.5","16","18"],"answer":2,"explanation":"For a third proportional, 9 : 12 = 12 : x, so x = 12²/9 = 16. 15 continues the gap of 3 (an arithmetic, not a proportional, sequence).","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"9 और 12 का तृतीयानुपाती क्या है?","optionsHi":["15","10.5","16","18"],"explanationHi":"तृतीयानुपाती के लिए 9 : 12 = 12 : x, अतः x = 12²/9 = 16। 15 में 3 का अंतर आगे बढ़ाया गया है (यह समांतर श्रेणी है, समानुपाती नहीं)।","subtopic":"proportion-variation"},
  {"id":"quant-ratio-36","question":"What is the duplicate ratio of 3 : 4?","options":["√3 : 2","27 : 64","6 : 8","9 : 16"],"answer":3,"explanation":"The duplicate ratio is the ratio of the squares: 3² : 4² = 9 : 16. 27 : 64 is the triplicate ratio.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"3 : 4 का द्विकृत अनुपात (duplicate ratio) क्या है?","optionsHi":["√3 : 2","27 : 64","6 : 8","9 : 16"],"explanationHi":"द्विकृत अनुपात वर्गों का अनुपात होता है: 3² : 4² = 9 : 16। 27 : 64 त्रिकृत अनुपात है।","subtopic":"proportion-variation"},
  {"id":"quant-ratio-37","question":"What is the compound ratio of 2 : 3, 6 : 5 and 5 : 8?","options":["13 : 16","1 : 2","2 : 1","3 : 4"],"answer":1,"explanation":"Multiply the antecedents and consequents: (2 × 6 × 5) : (3 × 5 × 8) = 60 : 120 = 1 : 2.","difficulty":"easy","source":"RRB NTPC · SSC CGL","questionHi":"2 : 3, 6 : 5 और 5 : 8 का संयुक्त अनुपात क्या है?","optionsHi":["13 : 16","1 : 2","2 : 1","3 : 4"],"explanationHi":"पूर्व पदों और उत्तर पदों को अलग-अलग गुणा करें: (2 × 6 × 5) : (3 × 5 × 8) = 60 : 120 = 1 : 2।","subtopic":"proportion-variation"},
  {"id":"quant-ratio-38","question":"If (x + y) : (x − y) = 7 : 3, then x : y is:","options":["5 : 2","10 : 3","7 : 3","2 : 5"],"answer":0,"explanation":"By componendo–dividendo, x : y = (7 + 3) : (7 − 3) = 10 : 4 = 5 : 2.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"यदि (x + y) : (x − y) = 7 : 3 है, तो x : y क्या है?","optionsHi":["5 : 2","10 : 3","7 : 3","2 : 5"],"explanationHi":"योगांतरानुपात (componendo-dividendo) से, x : y = (7 + 3) : (7 − 3) = 10 : 4 = 5 : 2।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-39","question":"₹3,000 is divided among A, B and C so that A gets half of what B and C get together, and B gets one-fourth of what A and C get together. What is C's share?","options":["₹1,000","₹1,400","₹1,200","₹600"],"answer":1,"explanation":"A = (B + C)/2 means A is 1/3 of the total = ₹1,000; B = (A + C)/4 means B is 1/5 of the total = ₹600. C = 3,000 − 1,600 = ₹1,400.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"₹3,000 को A, B और C में इस प्रकार बाँटा गया कि A को B और C के कुल का आधा मिलता है, और B को A और C के कुल का एक-चौथाई मिलता है। C का हिस्सा क्या है?","optionsHi":["₹1,000","₹1,400","₹1,200","₹600"],"explanationHi":"A = (B + C)/2 का अर्थ है कि A कुल का 1/3 = ₹1,000 है; B = (A + C)/4 का अर्थ है कि B कुल का 1/5 = ₹600 है। C = 3,000 − 1,600 = ₹1,400।","subtopic":"dividing-amounts"},
  {"id":"quant-ratio-40","question":"The salaries of A, B and C are in the ratio 5 : 7 : 9. If C earns ₹8,000 more than A, what is B's salary?","options":["₹14,000","₹10,000","₹28,000","₹18,000"],"answer":0,"explanation":"C − A = 9 − 5 = 4 parts = ₹8,000, so 1 part = ₹2,000 and B = 7 × 2,000 = ₹14,000. ₹28,000 takes ₹8,000 as 2 parts.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"A, B और C के वेतन का अनुपात 5 : 7 : 9 है। यदि C का वेतन A से ₹8,000 अधिक है, तो B का वेतन क्या है?","optionsHi":["₹14,000","₹10,000","₹28,000","₹18,000"],"explanationHi":"C − A = 9 − 5 = 4 भाग = ₹8,000, अतः 1 भाग = ₹2,000 और B = 7 × 2,000 = ₹14,000। ₹28,000 में ₹8,000 को 2 भाग मान लिया गया है।","subtopic":"income-expenses"},
  {"id":"quant-ratio-41","question":"In a class the ratio of boys to girls is 7 : 5. If 8 boys leave and 4 girls join, the ratio becomes 1 : 1. How many students are there now?","options":["64","76","72","68"],"answer":3,"explanation":"7k − 8 = 5k + 4 gives k = 6: originally 42 boys and 30 girls. Now 34 + 34 = 68. 72 is the original strength.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक कक्षा में लड़कों और लड़कियों का अनुपात 7 : 5 है। यदि 8 लड़के चले जाएँ और 4 लड़कियाँ आ जाएँ, तो अनुपात 1 : 1 हो जाता है। अब कक्षा में कुल कितने विद्यार्थी हैं?","optionsHi":["64","76","72","68"],"explanationHi":"7k − 8 = 5k + 4 से k = 6: मूल रूप से 42 लड़के और 30 लड़कियाँ थीं। अब 34 + 34 = 68। 72 मूल कुल संख्या है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-42","question":"x varies directly as the square of y, and x = 12 when y = 2. What is x when y = 5?","options":["50","75","60","30"],"answer":1,"explanation":"x = ky²: 12 = 4k, so k = 3 and x = 3 × 25 = 75. Treating it as simple direct variation gives 30.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"x, y के वर्ग के सीधे समानुपाती है, और y = 2 होने पर x = 12 है। y = 5 होने पर x क्या होगा?","optionsHi":["50","75","60","30"],"explanationHi":"x = ky²: 12 = 4k, अतः k = 3 और x = 3 × 25 = 75। इसे साधारण सीधा समानुपात मान लेने पर 30 आता है।","subtopic":"proportion-variation"},
  {"id":"quant-ratio-43","question":"₹2,600 is divided among A, B and C such that 2A = 3B = 4C. What is A's share?","options":["₹1,040","₹800","₹1,200","₹600"],"answer":2,"explanation":"2A = 3B = 4C = k gives A : B : C = 1/2 : 1/3 : 1/4 = 6 : 4 : 3, so A = 6/13 × 2,600 = ₹1,200. Reading the ratio as 2 : 3 : 4 is the trap.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"₹2,600 को A, B और C में इस प्रकार बाँटा गया कि 2A = 3B = 4C है। A का हिस्सा क्या है?","optionsHi":["₹1,040","₹800","₹1,200","₹600"],"explanationHi":"2A = 3B = 4C = k से A : B : C = 1/2 : 1/3 : 1/4 = 6 : 4 : 3, अतः A = 6/13 × 2,600 = ₹1,200। अनुपात को 2 : 3 : 4 पढ़ लेना ही जाल है।","subtopic":"dividing-amounts"},
  {"id":"quant-ratio-44","question":"The price of a diamond varies as the square of its weight. A diamond worth ₹36,000 breaks into three pieces whose weights are in the ratio 1 : 2 : 3. What is the loss?","options":["₹22,000","₹24,000","₹14,000","₹18,000"],"answer":0,"explanation":"Take weight 6 units, so value ∝ 36. The pieces are worth 1 + 4 + 9 = 14 units, i.e. 14/36 × 36,000 = ₹14,000. Loss = ₹22,000; ₹14,000 is what remains.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"हीरे का मूल्य उसके भार के वर्ग के समानुपाती होता है। ₹36,000 मूल्य का एक हीरा टूटकर तीन टुकड़ों में बँट जाता है जिनके भार का अनुपात 1 : 2 : 3 है। हानि कितनी हुई?","optionsHi":["₹22,000","₹24,000","₹14,000","₹18,000"],"explanationHi":"भार 6 इकाई लें, तो मूल्य ∝ 36। टुकड़ों का मूल्य 1 + 4 + 9 = 14 इकाई, यानी 14/36 × 36,000 = ₹14,000। हानि = ₹22,000; ₹14,000 तो बचा हुआ मूल्य है।","subtopic":"proportion-variation"},
  {"id":"quant-ratio-45","question":"Vessel P contains milk and water in the ratio 5 : 3 and vessel Q in the ratio 3 : 1. In what ratio should the contents of P and Q be mixed to get milk and water in the ratio 2 : 1?","options":["2 : 1","1 : 2","1 : 1","3 : 2"],"answer":0,"explanation":"Milk fractions: P = 5/8, Q = 3/4, target = 2/3. Alligation: P : Q = (3/4 − 2/3) : (2/3 − 5/8) = 1/12 : 1/24 = 2 : 1.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"बर्तन P में दूध और पानी का अनुपात 5 : 3 है और बर्तन Q में 3 : 1। P और Q की सामग्री को किस अनुपात में मिलाया जाए कि दूध और पानी का अनुपात 2 : 1 हो जाए?","optionsHi":["2 : 1","1 : 2","1 : 1","3 : 2"],"explanationHi":"दूध के भिन्न: P = 5/8, Q = 3/4, अभीष्ट = 2/3। एलिगेशन विधि से: P : Q = (3/4 − 2/3) : (2/3 − 5/8) = 1/12 : 1/24 = 2 : 1।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-46","question":"A and B invest in a business in the ratio 2 : 3. A is the working partner and gets 10% of the profit as salary; the rest is shared in the ratio of capital. Out of a profit of ₹50,000, how much does A get in all?","options":["₹25,000","₹18,000","₹23,000","₹20,000"],"answer":2,"explanation":"Salary = ₹5,000; the remaining ₹45,000 is shared 2 : 3, giving A ₹18,000. A's total = ₹23,000. ₹18,000 forgets the salary.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"A और B एक व्यापार में 2 : 3 के अनुपात में पूँजी लगाते हैं। A कार्यकारी साझेदार है और उसे लाभ का 10% वेतन के रूप में मिलता है; शेष लाभ पूँजी के अनुपात में बाँटा जाता है। ₹50,000 के लाभ में से A को कुल कितना मिलेगा?","optionsHi":["₹25,000","₹18,000","₹23,000","₹20,000"],"explanationHi":"वेतन = ₹5,000; शेष ₹45,000 को 2 : 3 में बाँटने पर A को ₹18,000 मिलते हैं। A का कुल = ₹23,000। ₹18,000 में वेतन को भूल गए हैं।","subtopic":"partnership"},
  {"id":"quant-ratio-47","question":"The ages of a father and his son are in the ratio 7 : 2. After 10 years the ratio will be 9 : 4. How old was the father when the son was born?","options":["30 years","25 years","20 years","35 years"],"answer":1,"explanation":"(7k + 10)/(2k + 10) = 9/4 gives 28k + 40 = 18k + 90, so k = 5: father 35, son 10. The father was 35 − 10 = 25 when the son was born.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक पिता और उसके पुत्र की आयु का अनुपात 7 : 2 है। 10 वर्ष बाद यह अनुपात 9 : 4 हो जाएगा। पुत्र के जन्म के समय पिता की आयु कितनी थी?","optionsHi":["30 वर्ष","25 वर्ष","20 वर्ष","35 वर्ष"],"explanationHi":"(7k + 10)/(2k + 10) = 9/4 से 28k + 40 = 18k + 90, अतः k = 5: पिता 35 वर्ष, पुत्र 10 वर्ष। पुत्र के जन्म के समय पिता की आयु 35 − 10 = 25 वर्ष थी।","subtopic":"ages"},
  {"id":"quant-ratio-48","question":"A bag contains ₹5, ₹2 and ₹1 coins whose total values are in the ratio 4 : 3 : 2. If the bag holds ₹450 in all, how many ₹2 coins are there?","options":["150","75","50","100"],"answer":1,"explanation":"The values are 4/9, 3/9 and 2/9 of ₹450 = ₹200, ₹150 and ₹100, so there are 150 ÷ 2 = 75 two-rupee coins. 150 confuses value with number.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक थैले में ₹5, ₹2 और ₹1 के सिक्के हैं जिनके कुल मूल्य का अनुपात 4 : 3 : 2 है। यदि थैले में कुल ₹450 हैं, तो ₹2 के कितने सिक्के हैं?","optionsHi":["150","75","50","100"],"explanationHi":"मूल्य ₹450 के 4/9, 3/9 और 2/9 हैं, यानी ₹200, ₹150 और ₹100, इसलिए दो रुपये के सिक्के 150 ÷ 2 = 75 हैं। 150 में मूल्य और संख्या को मिला दिया गया है।","subtopic":"coins"},
  {"id":"quant-ratio-49","question":"A can contains milk and water in the ratio 4 : 1. When 10 litres of the mixture are drawn off and replaced with water, the ratio becomes 2 : 3. How many litres did the can hold?","options":["25 litres","20 litres","30 litres","40 litres"],"answer":1,"explanation":"Milk falls from 4/5 to 2/5 of the can, i.e. it is halved, so (1 − 10/V) = 1/2 and V = 20 litres.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"एक कैन में दूध और पानी का अनुपात 4 : 1 है। जब उसमें से 10 लीटर मिश्रण निकालकर उसकी जगह पानी डाल दिया जाता है, तो अनुपात 2 : 3 हो जाता है। कैन में कितने लीटर मिश्रण था?","optionsHi":["25 लीटर","20 लीटर","30 लीटर","40 लीटर"],"explanationHi":"दूध कैन के 4/5 से घटकर 2/5 रह जाता है, यानी आधा हो जाता है, इसलिए (1 − 10/V) = 1/2 और V = 20 लीटर।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-50","question":"If a/b = c/d = e/f = 3, what is (2a² + 3c² + 4e²)/(2b² + 3d² + 4f²)?","options":["9","3","√3","27"],"answer":0,"explanation":"a = 3b, c = 3d, e = 3f, so every term in the numerator is 9 times the matching term in the denominator; the ratio is 9.","difficulty":"hard","source":"SSC CGL Tier 2 · CDS","questionHi":"यदि a/b = c/d = e/f = 3 है, तो (2a² + 3c² + 4e²)/(2b² + 3d² + 4f²) क्या है?","optionsHi":["9","3","√3","27"],"explanationHi":"a = 3b, c = 3d, e = 3f, इसलिए अंश का प्रत्येक पद हर के संगत पद का 9 गुना है; अनुपात 9 है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-51","question":"If (√(x + 3) + √(x − 3))/(√(x + 3) − √(x − 3)) = 2, what is x?","options":["3","15/4","9/4","5"],"answer":1,"explanation":"Componendo–dividendo gives √(x + 3)/√(x − 3) = 3/1, so (x + 3)/(x − 3) = 9, i.e. 8x = 30 and x = 15/4.","difficulty":"hard","source":"SSC CGL Tier 2 · CDS","questionHi":"यदि (√(x + 3) + √(x − 3))/(√(x + 3) − √(x − 3)) = 2 है, तो x क्या है?","optionsHi":["3","15/4","9/4","5"],"explanationHi":"योगांतरानुपात (componendo-dividendo) से √(x + 3)/√(x − 3) = 3/1, अतः (x + 3)/(x − 3) = 9, यानी 8x = 30 और x = 15/4।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-52","question":"The numbers of students in three classes are in the ratio 2 : 3 : 5. If 20 students are added to each class, the ratio becomes 4 : 5 : 7. How many students were there in all originally?","options":["80","120","160","100"],"answer":3,"explanation":"(2k + 20)/(3k + 20) = 4/5 gives k = 10, so the classes had 20, 30 and 50 students (100 in all). Check: 40 : 50 : 70 = 4 : 5 : 7.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"तीन कक्षाओं में विद्यार्थियों की संख्या का अनुपात 2 : 3 : 5 है। यदि प्रत्येक कक्षा में 20 विद्यार्थी और जोड़ दिए जाएँ, तो अनुपात 4 : 5 : 7 हो जाता है। मूल रूप से कुल कितने विद्यार्थी थे?","optionsHi":["80","120","160","100"],"explanationHi":"(2k + 20)/(3k + 20) = 4/5 से k = 10, इसलिए कक्षाओं में 20, 30 और 50 विद्यार्थी थे (कुल 100)। जाँच: 40 : 50 : 70 = 4 : 5 : 7।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-53","question":"How many of the following statements are correct?\n1. The mean proportional between 0.32 and 0.02 is 0.08.\n2. If a : b = c : d, then (a + b) : (a − b) = (c + d) : (c − d).\n3. The sub-duplicate ratio of 16 : 25 is 4 : 5.\n4. If x : y = 2 : 3, then (x + 5) : (y + 5) = 7 : 8.","options":["Only one","Only three","Only two","All four"],"answer":1,"explanation":"1: √(0.0064) = 0.08, true. 2: componendo–dividendo, true. 3: √16 : √25 = 4 : 5, true. 4 is false: adding 5 to both changes the ratio by an amount depending on the actual values (x = 4, y = 6 gives 9 : 11).","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"निम्नलिखित में से कितने कथन सही हैं?\n1. 0.32 और 0.02 का मध्यानुपाती 0.08 है।\n2. यदि a : b = c : d है, तो (a + b) : (a − b) = (c + d) : (c − d)।\n3. 16 : 25 का उपद्विकृत अनुपात (sub-duplicate ratio) 4 : 5 है।\n4. यदि x : y = 2 : 3 है, तो (x + 5) : (y + 5) = 7 : 8।","optionsHi":["केवल एक","केवल तीन","केवल दो","चारों"],"explanationHi":"1: √(0.0064) = 0.08, सही। 2: योगांतरानुपात, सही। 3: √16 : √25 = 4 : 5, सही। 4 गलत है: दोनों में 5 जोड़ने पर अनुपात का बदलाव वास्तविक मानों पर निर्भर करता है (x = 4, y = 6 लेने पर 9 : 11 आता है)।","subtopic":"proportion-variation"},
  {"id":"quant-ratio-54","question":"Three containers with capacities in the ratio 4 : 8 : 2 are full of milk–water mixtures in the ratios 3 : 1, 5 : 3 and 1 : 1 respectively. All three are emptied into one large vessel. What is the ratio of milk to water in it?","options":["9 : 5","2 : 1","3 : 2","5 : 3"],"answer":0,"explanation":"Milk = 4 × 3/4 + 8 × 5/8 + 2 × 1/2 = 3 + 5 + 1 = 9; water = 1 + 3 + 1 = 5. So 9 : 5. Averaging the three ratios as if the volumes were equal is the trap.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"तीन पात्रों की धारिता का अनुपात 4 : 8 : 2 है और वे क्रमशः 3 : 1, 5 : 3 तथा 1 : 1 के अनुपात वाले दूध-पानी के मिश्रण से भरे हैं। तीनों को एक बड़े बर्तन में उँडेल दिया जाता है। उसमें दूध और पानी का अनुपात क्या है?","optionsHi":["9 : 5","2 : 1","3 : 2","5 : 3"],"explanationHi":"दूध = 4 × 3/4 + 8 × 5/8 + 2 × 1/2 = 3 + 5 + 1 = 9; पानी = 1 + 3 + 1 = 5। अतः 9 : 5। तीनों अनुपातों का औसत ऐसे लेना जैसे आयतन बराबर हों, यही जाल है।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-55","question":"A starts a business with ₹60,000. B joins after 4 months with ₹80,000, and C joins 8 months after the start with ₹1,20,000. Out of a year-end profit of ₹1,15,000, what is B's share?","options":["₹40,000","₹30,000","₹35,000","₹45,000"],"answer":0,"explanation":"Capital × months: A = 60,000 × 12, B = 80,000 × 8, C = 1,20,000 × 4, i.e. 18 : 16 : 12 = 9 : 8 : 6. B's share = 8/23 × 1,15,000 = ₹40,000.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"A ₹60,000 से व्यापार शुरू करता है। B 4 महीने बाद ₹80,000 लेकर जुड़ता है, और C शुरुआत के 8 महीने बाद ₹1,20,000 लेकर जुड़ता है। वर्ष के अंत में ₹1,15,000 के लाभ में से B का हिस्सा क्या है?","optionsHi":["₹40,000","₹30,000","₹35,000","₹45,000"],"explanationHi":"पूँजी × महीने: A = 60,000 × 12, B = 80,000 × 8, C = 1,20,000 × 4, यानी 18 : 16 : 12 = 9 : 8 : 6। B का हिस्सा = 8/23 × 1,15,000 = ₹40,000।","subtopic":"partnership"},
  {"id":"quant-ratio-56","question":"Alloy X contains gold and copper in the ratio 2 : 3 and alloy Y in the ratio 4 : 1. How many kg of X must be used to make 30 kg of an alloy containing gold and copper in equal amounts?","options":["20 kg","15 kg","22.5 kg","7.5 kg"],"answer":2,"explanation":"Gold: X = 40%, Y = 80%, target = 50%. Alligation: X : Y = (80 − 50) : (50 − 40) = 3 : 1, so X = 3/4 × 30 = 22.5 kg.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"मिश्रधातु X में सोना और ताँबा 2 : 3 के अनुपात में हैं और मिश्रधातु Y में 4 : 1 के अनुपात में। 30 kg की ऐसी मिश्रधातु बनाने के लिए, जिसमें सोना और ताँबा बराबर मात्रा में हों, X के कितने kg लेने होंगे?","optionsHi":["20 kg","15 kg","22.5 kg","7.5 kg"],"explanationHi":"सोना: X = 40%, Y = 80%, अभीष्ट = 50%। एलिगेशन विधि से: X : Y = (80 − 50) : (50 − 40) = 3 : 1, अतः X = 3/4 × 30 = 22.5 kg।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-57","question":"The present ages of A and B are in the ratio 4 : 5, and those of B and C in the ratio 6 : 7. Ten years from now, the sum of A's and C's ages will be 79 years. What is B's present age?","options":["25 years","24 years","30 years","35 years"],"answer":2,"explanation":"A : B : C = 24 : 30 : 35. A + C now = 79 − 20 = 59 = 59k, so k = 1 and B = 30. Subtracting only 10 years (not 10 for each person) gives the wrong total.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"A और B की वर्तमान आयु का अनुपात 4 : 5 है, तथा B और C की आयु का अनुपात 6 : 7 है। अब से दस वर्ष बाद A और C की आयु का योग 79 वर्ष होगा। B की वर्तमान आयु क्या है?","optionsHi":["25 वर्ष","24 वर्ष","30 वर्ष","35 वर्ष"],"explanationHi":"A : B : C = 24 : 30 : 35। अभी A + C = 79 − 20 = 59 = 59k, अतः k = 1 और B = 30। केवल 10 वर्ष घटाने (प्रत्येक व्यक्ति के लिए 10 नहीं) से कुल गलत आता है।","subtopic":"ages"},
  {"id":"quant-ratio-58","question":"When a man married, the ratio of his age to his wife's was 5 : 3. Now the ratio is 9 : 7. If the man is 45 years old now, how many years ago did they marry?","options":["18 years","15 years","25 years","20 years"],"answer":3,"explanation":"Ages at marriage 5k and 3k; after t years (5k + t)/(3k + t) = 9/7 gives 8k = 2t, so t = 4k. Now 5k + 4k = 45 gives k = 5 and t = 20 years. Check: 25, 15 then; 45, 35 now.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"जब एक पुरुष का विवाह हुआ, तब उसकी आयु और उसकी पत्नी की आयु का अनुपात 5 : 3 था। अब यह अनुपात 9 : 7 है। यदि पुरुष की आयु अब 45 वर्ष है, तो विवाह को कितने वर्ष हो गए?","optionsHi":["18 वर्ष","15 वर्ष","25 वर्ष","20 वर्ष"],"explanationHi":"विवाह के समय आयु 5k और 3k; t वर्ष बाद (5k + t)/(3k + t) = 9/7 से 8k = 2t, अतः t = 4k। अब 5k + 4k = 45 से k = 5 और t = 20 वर्ष। जाँच: तब 25, 15; अब 45, 35।","subtopic":"ages"},
  {"id":"quant-ratio-59","question":"Assertion (A): If 2A = 3B = 4C, then A : B : C = 2 : 3 : 4.\nReason (R): If 2A = 3B, then A : B = 3 : 2.","options":["A is true but R is false","Both A and R are true, and R is the correct explanation of A","Both A and R are false","A is false but R is true"],"answer":3,"explanation":"R is true (A/B = 3/2). Applying it to all three gives A : B : C = 1/2 : 1/3 : 1/4 = 6 : 4 : 3, so A is false.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"अभिकथन (A): यदि 2A = 3B = 4C है, तो A : B : C = 2 : 3 : 4।\nकारण (R): यदि 2A = 3B है, तो A : B = 3 : 2।","optionsHi":["A सही है लेकिन R गलत है","A और R दोनों सही हैं, और R, A की सही व्याख्या है","A और R दोनों गलत हैं","A गलत है लेकिन R सही है"],"explanationHi":"R सही है (A/B = 3/2)। इसे तीनों पर लगाने से A : B : C = 1/2 : 1/3 : 1/4 = 6 : 4 : 3 आता है, इसलिए A गलत है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-60","question":"A vessel contains 80 litres of milk and water in the ratio 7 : 1. 16 litres of the mixture are drawn off and replaced with water, and the process is repeated once more. What is the ratio of milk to water now?","options":["3 : 2","7 : 3","14 : 11","28 : 17"],"answer":2,"explanation":"Milk starts at 70 L and each step keeps 64/80 = 4/5 of it: 70 × (4/5)² = 44.8 L. Water = 80 − 44.8 = 35.2 L, so the ratio is 44.8 : 35.2 = 14 : 11.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक बर्तन में 80 लीटर दूध और पानी का मिश्रण 7 : 1 के अनुपात में है। इसमें से 16 लीटर मिश्रण निकालकर उसकी जगह पानी डाल दिया जाता है, और यह क्रिया एक बार और दोहराई जाती है। अब दूध और पानी का अनुपात क्या है?","optionsHi":["3 : 2","7 : 3","14 : 11","28 : 17"],"explanationHi":"दूध शुरू में 70 L है और हर चरण में उसका 64/80 = 4/5 भाग बचता है: 70 × (4/5)² = 44.8 L। पानी = 80 − 44.8 = 35.2 L, अतः अनुपात 44.8 : 35.2 = 14 : 11।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-61","question":"If a : b = 2 : 3, b : c = 4 : 5 and c : d = 6 : 7, what is (a + b) : (c + d)?","options":["5 : 13","16 : 35","40 : 63","8 : 13"],"answer":3,"explanation":"Make the links match: a : b : c : d = 16 : 24 : 30 : 35. So (a + b) : (c + d) = 40 : 65 = 8 : 13.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"यदि a : b = 2 : 3, b : c = 4 : 5 और c : d = 6 : 7 है, तो (a + b) : (c + d) क्या है?","optionsHi":["5 : 13","16 : 35","40 : 63","8 : 13"],"explanationHi":"कड़ियों को मिलाने पर a : b : c : d = 16 : 24 : 30 : 35। अतः (a + b) : (c + d) = 40 : 65 = 8 : 13।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-62","question":"If (3x + 4y) : (5x − 2y) = 2 : 1, what is (x² + y²) : (x² − y²)?","options":["113 : 15","65 : 33","15 : 113","8 : 7"],"answer":0,"explanation":"3x + 4y = 10x − 4y gives 8y = 7x, so x : y = 8 : 7. Then (64 + 49) : (64 − 49) = 113 : 15.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"यदि (3x + 4y) : (5x − 2y) = 2 : 1 है, तो (x² + y²) : (x² − y²) क्या है?","optionsHi":["113 : 15","65 : 33","15 : 113","8 : 7"],"explanationHi":"3x + 4y = 10x − 4y से 8y = 7x, अतः x : y = 8 : 7। तब (64 + 49) : (64 − 49) = 113 : 15।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-63","question":"A invests twice as much as B, and B invests three-fourths as much as C. A's money is in the business for 6 months, B's for 8 months and C's for 12 months. Out of a profit of ₹27,000, what is C's share?","options":["₹13,500","₹9,000","₹12,000","₹10,800"],"answer":2,"explanation":"With C = 4: B = 3 and A = 6. Capital × months: A = 36, B = 24, C = 48, i.e. 3 : 2 : 4. C's share = 4/9 × 27,000 = ₹12,000.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"A, B से दोगुनी पूँजी लगाता है, और B, C की पूँजी का तीन-चौथाई लगाता है। A का धन व्यापार में 6 महीने, B का 8 महीने और C का 12 महीने रहता है। ₹27,000 के लाभ में से C का हिस्सा क्या है?","optionsHi":["₹13,500","₹9,000","₹12,000","₹10,800"],"explanationHi":"C = 4 लेने पर B = 3 और A = 6। पूँजी × महीने: A = 36, B = 24, C = 48, यानी 3 : 2 : 4। C का हिस्सा = 4/9 × 27,000 = ₹12,000।","subtopic":"partnership"},
  {"id":"quant-ratio-64","question":"At a show, adult and child tickets cost in the ratio 3 : 2, and the numbers of adults and children are in the ratio 5 : 8. If ₹6,200 was collected in all, how much came from children's tickets?","options":["₹2,480","₹3,815","₹3,000","₹3,200"],"answer":3,"explanation":"Money ∝ price × number: adults 3 × 5 = 15, children 2 × 8 = 16. Children's share = 16/31 × 6,200 = ₹3,200.","difficulty":"very-hard","source":"IBPS PO Mains · SBI PO Mains","questionHi":"एक शो में वयस्क और बच्चे के टिकटों की कीमत का अनुपात 3 : 2 है, और वयस्कों तथा बच्चों की संख्या का अनुपात 5 : 8 है। यदि कुल ₹6,200 एकत्र हुए, तो बच्चों के टिकटों से कितनी राशि आई?","optionsHi":["₹2,480","₹3,815","₹3,000","₹3,200"],"explanationHi":"राशि ∝ कीमत × संख्या: वयस्क 3 × 5 = 15, बच्चे 2 × 8 = 16। बच्चों का हिस्सा = 16/31 × 6,200 = ₹3,200।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-65","question":"If 3A = 5B, what is A : B?","options":["3 : 5","5 : 3","15 : 1","8 : 3"],"answer":1,"explanation":"3A = 5B means A/B = 5/3. The number multiplying A goes with B in the ratio.","difficulty":"easy","source":"SSC CHSL · RRB Group D","questionHi":"यदि 3A = 5B है, तो A : B क्या है?","optionsHi":["3 : 5","5 : 3","15 : 1","8 : 3"],"explanationHi":"3A = 5B का अर्थ है A/B = 5/3। A के साथ गुणा होने वाली संख्या अनुपात में B के साथ जाती है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-66","question":"₹1,560 is divided in the ratio 5 : 8. What is the smaller share?","options":["₹600","₹960","₹520","₹650"],"answer":0,"explanation":"Total parts = 13, one part = 120. Smaller share = 5 × 120 = ₹600.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"₹1,560 को 5 : 8 के अनुपात में बाँटा गया है। छोटा हिस्सा क्या है?","optionsHi":["₹600","₹960","₹520","₹650"],"explanationHi":"कुल भाग = 13, एक भाग = 120। छोटा हिस्सा = 5 × 120 = ₹600।","subtopic":"dividing-amounts"},
  {"id":"quant-ratio-67","question":"What is the fourth proportional to 4, 10 and 18?","options":["7.2","24","40","45"],"answer":3,"explanation":"4 : 10 = 18 : x gives x = 10 × 18/4 = 45. 7.2 inverts the proportion (4 × 18/10), and 24 adds the gap of 6.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"4, 10 और 18 का चतुर्थानुपाती क्या है?","optionsHi":["7.2","24","40","45"],"explanationHi":"4 : 10 = 18 : x से x = 10 × 18/4 = 45। 7.2 में अनुपात उलट दिया गया है (4 × 18/10), और 24 में 6 का अंतर जोड़ा गया है।","subtopic":"proportion-variation"},
  {"id":"quant-ratio-68","question":"What is the ratio of 45 minutes to 2 hours?","options":["45 : 2","9 : 4","3 : 8","3 : 4"],"answer":2,"explanation":"Use the same unit: 2 hours = 120 minutes, so 45 : 120 = 3 : 8. 45 : 2 mixes minutes with hours, and 3 : 4 compares 45 minutes with 1 hour.","difficulty":"easy","source":"RRB Group D · SSC CHSL","questionHi":"45 मिनट और 2 घंटे का अनुपात क्या है?","optionsHi":["45 : 2","9 : 4","3 : 8","3 : 4"],"explanationHi":"एक ही इकाई में लें: 2 घंटे = 120 मिनट, अतः 45 : 120 = 3 : 8। 45 : 2 में मिनट और घंटे को मिला दिया गया है, और 3 : 4 में 45 मिनट की तुलना 1 घंटे से की गई है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-69","question":"A : B = 5 : 7. If B is 63, what is A?","options":["88.2","35","45","49"],"answer":2,"explanation":"One part = 63/7 = 9, so A = 5 × 9 = 45. 88.2 inverts the ratio (63 × 7/5), and 35 is 5 × 7.","difficulty":"easy","source":"RRB Group D · SSC CHSL","questionHi":"A : B = 5 : 7 है। यदि B = 63 है, तो A क्या है?","optionsHi":["88.2","35","45","49"],"explanationHi":"एक भाग = 63/7 = 9, अतः A = 5 × 9 = 45। 88.2 में अनुपात उलट दिया गया है (63 × 7/5), और 35 = 5 × 7 है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-70","question":"What is the sub-duplicate ratio of 49 : 81?","options":["49² : 81²","7 : 9","9 : 7","2401 : 6561"],"answer":1,"explanation":"Sub-duplicate ratio means the ratio of square roots: √49 : √81 = 7 : 9.","difficulty":"easy","source":"SSC CHSL · SSC CGL","questionHi":"49 : 81 का उपद्विकृत अनुपात (sub-duplicate ratio) क्या है?","optionsHi":["49² : 81²","7 : 9","9 : 7","2401 : 6561"],"explanationHi":"उपद्विकृत अनुपात का अर्थ है वर्गमूलों का अनुपात: √49 : √81 = 7 : 9।","subtopic":"proportion-variation"},
  {"id":"quant-ratio-71","question":"What is the triplicate ratio of 2 : 3?","options":["8 : 27","6 : 9","4 : 9","√2 : √3"],"answer":0,"explanation":"The triplicate ratio is the ratio of cubes: 2³ : 3³ = 8 : 27. 4 : 9 is the duplicate ratio (squares), and √2 : √3 is the sub-duplicate ratio.","difficulty":"easy","source":"SSC CHSL · RRB NTPC","questionHi":"2 : 3 का त्रिकृत अनुपात (triplicate ratio) क्या है?","optionsHi":["8 : 27","6 : 9","4 : 9","√2 : √3"],"explanationHi":"त्रिकृत अनुपात घनों का अनुपात होता है: 2³ : 3³ = 8 : 27। 4 : 9 द्विकृत अनुपात (वर्ग) है, और √2 : √3 उपद्विकृत अनुपात है।","subtopic":"proportion-variation"},
  {"id":"quant-ratio-72","question":"If 40% of A equals 3/5 of B, what is A : B?","options":["2 : 3","6 : 5","5 : 6","3 : 2"],"answer":3,"explanation":"0.4A = 0.6B gives A/B = 0.6/0.4 = 3/2. 2 : 3 is the inverted ratio, the trap of writing A : B = 40 : 60 directly.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"यदि A का 40%, B के 3/5 के बराबर है, तो A : B क्या है?","optionsHi":["2 : 3","6 : 5","5 : 6","3 : 2"],"explanationHi":"0.4A = 0.6B से A/B = 0.6/0.4 = 3/2। 2 : 3 उलटा अनुपात है, जो A : B = 40 : 60 सीधे लिख देने की भूल से आता है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-73","question":"If A : B : C = 2 : 3 : 4, what is A/B : B/C : C/A?","options":["2 : 3 : 4","4 : 3 : 2","9 : 8 : 24","8 : 9 : 24"],"answer":3,"explanation":"A/B = 2/3, B/C = 3/4 and C/A = 2; multiplying by 12 gives 8 : 9 : 24. 9 : 8 : 24 swaps the first two after a slip in the LCM step.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"यदि A : B : C = 2 : 3 : 4 है, तो A/B : B/C : C/A क्या है?","optionsHi":["2 : 3 : 4","4 : 3 : 2","9 : 8 : 24","8 : 9 : 24"],"explanationHi":"A/B = 2/3, B/C = 3/4 और C/A = 2; 12 से गुणा करने पर 8 : 9 : 24। 9 : 8 : 24 में LCM वाले चरण की चूक से पहले दो पद आपस में बदल गए हैं।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-74","question":"The present ages of Priya and Neha are in the ratio 6 : 5 and add up to 66 years. What will be the ratio of their ages after 6 years?","options":["6 : 5","12 : 11","7 : 6","8 : 7"],"answer":2,"explanation":"Ages are 36 and 30 (66 split 6 : 5). After 6 years: 42 : 36 = 7 : 6.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"प्रिया और नेहा की वर्तमान आयु का अनुपात 6 : 5 है और उनका योग 66 वर्ष है। 6 वर्ष बाद उनकी आयु का अनुपात क्या होगा?","optionsHi":["6 : 5","12 : 11","7 : 6","8 : 7"],"explanationHi":"आयु 36 और 30 वर्ष है (66 को 6 : 5 में बाँटने पर)। 6 वर्ष बाद: 42 : 36 = 7 : 6।","subtopic":"ages"},
  {"id":"quant-ratio-75","question":"Two numbers are in the ratio 7 : 9 and their LCM is 1,764. What is their sum?","options":["432","448","504","392"],"answer":1,"explanation":"Numbers are 7h and 9h with LCM 63h = 1,764, so h = 28. Sum = 16 × 28 = 448.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"दो संख्याओं का अनुपात 7 : 9 है और उनका LCM 1,764 है। उनका योग क्या है?","optionsHi":["432","448","504","392"],"explanationHi":"संख्याएँ 7h और 9h हैं, जिनका LCM 63h = 1,764, अतः h = 28। योग = 16 × 28 = 448।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-76","question":"In a class, boys and girls are in the ratio 7 : 8. On a rainy day 25% of the boys and 30% of the girls are absent. What is the ratio of boys to girls present?","options":["15 : 16","7 : 8","21 : 28","16 : 15"],"answer":0,"explanation":"Present: boys 7 × 0.75 = 5.25 and girls 8 × 0.7 = 5.6. Ratio 5.25 : 5.6 = 15 : 16.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"एक कक्षा में लड़कों और लड़कियों का अनुपात 7 : 8 है। एक बरसात के दिन 25% लड़के और 30% लड़कियाँ अनुपस्थित हैं। उपस्थित लड़कों और लड़कियों का अनुपात क्या है?","optionsHi":["15 : 16","7 : 8","21 : 28","16 : 15"],"explanationHi":"उपस्थित: लड़के 7 × 0.75 = 5.25 और लड़कियाँ 8 × 0.7 = 5.6। अनुपात 5.25 : 5.6 = 15 : 16।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-77","question":"If x : y = 5 : 3, what is (x² − y²) : (x² + y²)?","options":["8 : 17","2 : 8","16 : 9","17 : 8"],"answer":0,"explanation":"Put x = 5, y = 3: (25 − 9) : (25 + 9) = 16 : 34 = 8 : 17. 17 : 8 reverses the order, and 16 : 9 compares x² − y² with y².","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"यदि x : y = 5 : 3 है, तो (x² − y²) : (x² + y²) क्या है?","optionsHi":["8 : 17","2 : 8","16 : 9","17 : 8"],"explanationHi":"x = 5, y = 3 रखने पर: (25 − 9) : (25 + 9) = 16 : 34 = 8 : 17। 17 : 8 में क्रम उलट गया है, और 16 : 9 में x² − y² की तुलना y² से की गई है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-78","question":"A 45-litre mixture has milk and water in the ratio 4 : 1. How much milk must be added to make the ratio 5 : 1?","options":["5 litres","4.5 litres","11.25 litres","9 litres"],"answer":3,"explanation":"Milk = 36 L, water = 9 L. Water stays fixed, so milk must become 5 × 9 = 45 L: add 9 L.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"45 लीटर के एक मिश्रण में दूध और पानी का अनुपात 4 : 1 है। अनुपात को 5 : 1 बनाने के लिए कितना दूध मिलाना होगा?","optionsHi":["5 लीटर","4.5 लीटर","11.25 लीटर","9 लीटर"],"explanationHi":"दूध = 36 L, पानी = 9 L। पानी स्थिर रहता है, इसलिए दूध 5 × 9 = 45 L होना चाहिए: 9 L मिलाना होगा।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-79","question":"The prices of petrol and diesel are in the ratio 5 : 4. If petrol becomes 20% dearer and diesel 25% dearer, what is the new ratio of their prices?","options":["5 : 4","24 : 25","6 : 5","4 : 5"],"answer":2,"explanation":"New prices: 5 × 1.2 = 6 and 4 × 1.25 = 5, so the ratio is 6 : 5. 5 : 4 assumes the ratio is unchanged, and 24 : 25 compares the two multipliers 1.2 : 1.25 instead of the prices.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"पेट्रोल और डीजल की कीमतों का अनुपात 5 : 4 है। यदि पेट्रोल 20% महँगा और डीजल 25% महँगा हो जाए, तो उनकी कीमतों का नया अनुपात क्या होगा?","optionsHi":["5 : 4","24 : 25","6 : 5","4 : 5"],"explanationHi":"नई कीमतें: 5 × 1.2 = 6 और 4 × 1.25 = 5, इसलिए अनुपात 6 : 5। 5 : 4 में मान लिया गया है कि अनुपात नहीं बदला, और 24 : 25 में कीमतों की जगह दोनों गुणकों 1.2 : 1.25 की तुलना कर ली गई है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-80","question":"A hostel has rooms for first-, second- and third-year students in the ratio 4 : 5 : 6. If these are increased by 25%, 20% and 50% respectively, what is the new ratio?","options":["4 : 5 : 6","5 : 6 : 9","6 : 5 : 9","5 : 7 : 9"],"answer":1,"explanation":"4 × 1.25 = 5, 5 × 1.2 = 6, 6 × 1.5 = 9. New ratio 5 : 6 : 9.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक छात्रावास में प्रथम, द्वितीय और तृतीय वर्ष के विद्यार्थियों के लिए कमरे 4 : 5 : 6 के अनुपात में हैं। यदि इन्हें क्रमशः 25%, 20% और 50% बढ़ा दिया जाए, तो नया अनुपात क्या होगा?","optionsHi":["4 : 5 : 6","5 : 6 : 9","6 : 5 : 9","5 : 7 : 9"],"explanationHi":"4 × 1.25 = 5, 5 × 1.2 = 6, 6 × 1.5 = 9। नया अनुपात 5 : 6 : 9।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-81","question":"Two numbers are in the ratio 3 : 4 and the difference of their squares is 252. What is the larger number?","options":["18","24","28","32"],"answer":1,"explanation":"(4k)² − (3k)² = 7k² = 252, so k = 6 and the larger number is 24.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"दो संख्याओं का अनुपात 3 : 4 है और उनके वर्गों का अंतर 252 है। बड़ी संख्या क्या है?","optionsHi":["18","24","28","32"],"explanationHi":"(4k)² − (3k)² = 7k² = 252, अतः k = 6 और बड़ी संख्या 24 है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-82","question":"If 15% of x = 25% of y = 40% of z, what is x : y : z?","options":["40 : 24 : 15","15 : 25 : 40","8 : 5 : 3","24 : 40 : 15"],"answer":0,"explanation":"x : y : z = 1/15 : 1/25 : 1/40. Multiply by 600 (LCM): 40 : 24 : 15.","difficulty":"moderate","source":"SSC CGL · SSC CPO","questionHi":"यदि x का 15% = y का 25% = z का 40% है, तो x : y : z क्या है?","optionsHi":["40 : 24 : 15","15 : 25 : 40","8 : 5 : 3","24 : 40 : 15"],"explanationHi":"x : y : z = 1/15 : 1/25 : 1/40। 600 (LCM) से गुणा करने पर: 40 : 24 : 15।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-83","question":"A 21-litre mixture has milk and water in the ratio 5 : 2. 7 litres of the mixture are taken out and replaced with milk. What is the new ratio of milk to water?","options":["5 : 2","15 : 4","22 : 7","17 : 4"],"answer":3,"explanation":"14 L remain with milk 10 L and water 4 L. Adding 7 L milk: 17 : 4.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"21 लीटर के एक मिश्रण में दूध और पानी का अनुपात 5 : 2 है। इसमें से 7 लीटर मिश्रण निकालकर उसकी जगह दूध डाल दिया जाता है। दूध और पानी का नया अनुपात क्या है?","optionsHi":["5 : 2","15 : 4","22 : 7","17 : 4"],"explanationHi":"14 L बचता है जिसमें दूध 10 L और पानी 4 L है। 7 L दूध मिलाने पर: 17 : 4।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-84","question":"Three varieties of rice costing ₹40, ₹48 and ₹60 per kg are mixed in the ratio 3 : 2 : 5. What is the cost of the mixture per kg?","options":["₹49.33","₹52","₹51.60","₹50.40"],"answer":2,"explanation":"(3 × 40 + 2 × 48 + 5 × 60)/10 = (120 + 96 + 300)/10 = ₹51.60. The simple average ₹49.33 ignores the quantities.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"₹40, ₹48 और ₹60 प्रति किग्रा वाली चावल की तीन किस्मों को 3 : 2 : 5 के अनुपात में मिलाया जाता है। मिश्रण की प्रति किग्रा लागत क्या है?","optionsHi":["₹49.33","₹52","₹51.60","₹50.40"],"explanationHi":"(3 × 40 + 2 × 48 + 5 × 60)/10 = (120 + 96 + 300)/10 = ₹51.60। साधारण औसत ₹49.33 में मात्राओं को नहीं गिना गया है।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-85","question":"The daily wages of A and B are in the ratio 5 : 4. A works for 20 days and B for 25 days, and together they earn ₹18,000. How much does A earn?","options":["₹10,000","₹8,000","₹9,000","₹7,200"],"answer":2,"explanation":"Earnings ∝ wage × days: 5 × 20 = 100 and 4 × 25 = 100, so they earn equally. A gets ₹9,000.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"A और B की दैनिक मजदूरी का अनुपात 5 : 4 है। A 20 दिन और B 25 दिन काम करता है, और दोनों मिलकर ₹18,000 कमाते हैं। A कितना कमाता है?","optionsHi":["₹10,000","₹8,000","₹9,000","₹7,200"],"explanationHi":"कमाई ∝ मजदूरी × दिन: 5 × 20 = 100 और 4 × 25 = 100, इसलिए दोनों की कमाई बराबर है। A को ₹9,000 मिलेंगे।","subtopic":"income-expenses"},
  {"id":"quant-ratio-86","question":"A invests 3 times as much as B, and B invests 2/3 of what C invests. Out of a profit of ₹6,600, what is B's share?","options":["₹1,800","₹1,200","₹3,600","₹2,200"],"answer":1,"explanation":"Take C = 3: B = 2 and A = 6. Ratio 6 : 2 : 3 (11 parts). B = 2/11 × 6,600 = ₹1,200.","difficulty":"moderate","source":"SSC CGL · IBPS Clerk","questionHi":"A, B से 3 गुना पूँजी लगाता है, और B, C की पूँजी का 2/3 लगाता है। ₹6,600 के लाभ में से B का हिस्सा क्या है?","optionsHi":["₹1,800","₹1,200","₹3,600","₹2,200"],"explanationHi":"C = 3 लेने पर B = 2 और A = 6। अनुपात 6 : 2 : 3 (कुल 11 भाग)। B = 2/11 × 6,600 = ₹1,200।","subtopic":"partnership"},
  {"id":"quant-ratio-87","question":"x varies inversely as the square of y, and x = 9 when y = 4. What is y when x = 16?","options":["3","2.25","5.33","12"],"answer":0,"explanation":"x × y² is constant = 9 × 16 = 144. For x = 16, y² = 9, so y = 3.","difficulty":"moderate","source":"SSC CGL · CDS","questionHi":"x, y के वर्ग के व्युत्क्रमानुपाती है, और y = 4 होने पर x = 9 है। x = 16 होने पर y क्या होगा?","optionsHi":["3","2.25","5.33","12"],"explanationHi":"x × y² अचर है = 9 × 16 = 144। x = 16 के लिए y² = 9, अतः y = 3।","subtopic":"proportion-variation"},
  {"id":"quant-ratio-88","question":"If a : b = 3 : 4, what is (5a − 3b) : (7a + 2b)?","options":["1 : 1","29 : 3","15 : 29","3 : 29"],"answer":3,"explanation":"Put a = 3, b = 4: (15 − 12) : (21 + 8) = 3 : 29. 29 : 3 reverses the order, and 15 : 29 forgets to subtract 3b.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"यदि a : b = 3 : 4 है, तो (5a − 3b) : (7a + 2b) क्या है?","optionsHi":["1 : 1","29 : 3","15 : 29","3 : 29"],"explanationHi":"a = 3, b = 4 रखने पर: (15 − 12) : (21 + 8) = 3 : 29। 29 : 3 में क्रम उलट गया है, और 15 : 29 में 3b घटाना भूल गए हैं।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-89","question":"Three friends share a cab hire of ₹7,200 in proportion to the distances they travel: 120 km, 150 km and 210 km. How much does the third friend pay?","options":["₹2,400","₹2,250","₹3,000","₹3,150"],"answer":3,"explanation":"120 : 150 : 210 = 4 : 5 : 7 (16 parts). Third friend = 7/16 × 7,200 = ₹3,150.","difficulty":"moderate","source":"SSC CHSL · RRB NTPC","questionHi":"तीन मित्र ₹7,200 के कैब किराए को अपनी तय की गई दूरियों 120 km, 150 km और 210 km के अनुपात में बाँटते हैं। तीसरा मित्र कितना देगा?","optionsHi":["₹2,400","₹2,250","₹3,000","₹3,150"],"explanationHi":"120 : 150 : 210 = 4 : 5 : 7 (कुल 16 भाग)। तीसरा मित्र = 7/16 × 7,200 = ₹3,150।","subtopic":"dividing-amounts"},
  {"id":"quant-ratio-90","question":"The sides of a triangle are in the ratio 1/2 : 1/3 : 1/4 and its perimeter is 104 cm. What is the longest side?","options":["52 cm","32 cm","48 cm","24 cm"],"answer":2,"explanation":"Multiply by 12: 6 : 4 : 3 (13 parts). Longest side = 6/13 × 104 = 48 cm.","difficulty":"moderate","source":"SSC CGL · SSC CHSL","questionHi":"एक त्रिभुज की भुजाएँ 1/2 : 1/3 : 1/4 के अनुपात में हैं और उसका परिमाप 104 cm है। सबसे लंबी भुजा कितनी है?","optionsHi":["52 cm","32 cm","48 cm","24 cm"],"explanationHi":"12 से गुणा करने पर: 6 : 4 : 3 (कुल 13 भाग)। सबसे लंबी भुजा = 6/13 × 104 = 48 cm।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-91","question":"If 2A = 3B and 4B = 5C, what is A : C?","options":["8 : 15","15 : 8","5 : 2","3 : 5"],"answer":1,"explanation":"From 2A = 3B, A = 1.5B; from 4B = 5C, C = 0.8B; so A : C = 1.5 : 0.8 = 15 : 8. 8 : 15 inverts it, the trap of reading 2A = 3B as A : B = 2 : 3.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"यदि 2A = 3B और 4B = 5C है, तो A : C क्या है?","optionsHi":["8 : 15","15 : 8","5 : 2","3 : 5"],"explanationHi":"2A = 3B से A = 1.5B; 4B = 5C से C = 0.8B; अतः A : C = 1.5 : 0.8 = 15 : 8। 8 : 15 उलटा है, जो 2A = 3B को A : B = 2 : 3 पढ़ लेने की भूल से आता है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-92","question":"A and B start a business with ₹40,000 and ₹60,000. After 4 months A adds ₹20,000 and B withdraws ₹20,000. Out of a year-end profit of ₹45,000, what is A's share?","options":["₹24,000","₹18,000","₹22,500","₹21,000"],"answer":0,"explanation":"A: 40 × 4 + 60 × 8 = 640; B: 60 × 4 + 40 × 8 = 560 (in thousand-months). Ratio 8 : 7, so A = 8/15 × 45,000 = ₹24,000.","difficulty":"hard","source":"SSC CGL · IBPS PO","questionHi":"A और B क्रमशः ₹40,000 और ₹60,000 से व्यापार शुरू करते हैं। 4 महीने बाद A ₹20,000 और जोड़ता है तथा B ₹20,000 निकाल लेता है। वर्ष के अंत में ₹45,000 के लाभ में से A का हिस्सा क्या है?","optionsHi":["₹24,000","₹18,000","₹22,500","₹21,000"],"explanationHi":"A: 40 × 4 + 60 × 8 = 640; B: 60 × 4 + 40 × 8 = 560 (हज़ार-महीनों में)। अनुपात 8 : 7, अतः A = 8/15 × 45,000 = ₹24,000।","subtopic":"partnership"},
  {"id":"quant-ratio-93","question":"Four years ago the ages of A and B were in the ratio 3 : 4. Four years from now they will be in the ratio 5 : 6. What is the sum of their present ages?","options":["36 years","28 years","44 years","40 years"],"answer":0,"explanation":"Four years ago: 3x and 4x. Eight years later: (3x + 8)/(4x + 8) = 5/6, so 18x + 48 = 20x + 40 and x = 4. Present ages 16 and 20; sum 36.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"चार वर्ष पहले A और B की आयु का अनुपात 3 : 4 था। चार वर्ष बाद यह 5 : 6 हो जाएगा। उनकी वर्तमान आयु का योग क्या है?","optionsHi":["36 वर्ष","28 वर्ष","44 वर्ष","40 वर्ष"],"explanationHi":"चार वर्ष पहले: 3x और 4x। आठ वर्ष बाद: (3x + 8)/(4x + 8) = 5/6, अतः 18x + 48 = 20x + 40 और x = 4। वर्तमान आयु 16 और 20 वर्ष; योग 36।","subtopic":"ages"},
  {"id":"quant-ratio-94","question":"Vessel A holds 16 litres of milk and water in the ratio 3 : 1, and vessel B holds 24 litres in the ratio 5 : 3. Both are emptied into a third vessel. What is the ratio of milk to water in it?","options":["8 : 4","4 : 1","13 : 27","27 : 13"],"answer":3,"explanation":"A: 12 milk, 4 water. B: 15 milk, 9 water. Together 27 : 13. Adding the ratios (8 : 4) ignores the different volumes.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"बर्तन A में 16 लीटर दूध और पानी 3 : 1 के अनुपात में हैं, और बर्तन B में 24 लीटर 5 : 3 के अनुपात में हैं। दोनों को तीसरे बर्तन में उँडेल दिया जाता है। उसमें दूध और पानी का अनुपात क्या है?","optionsHi":["8 : 4","4 : 1","13 : 27","27 : 13"],"explanationHi":"A: 12 दूध, 4 पानी। B: 15 दूध, 9 पानी। कुल मिलाकर 27 : 13। अनुपातों को सीधे जोड़ना (8 : 4) अलग-अलग आयतन को नज़रअंदाज़ करता है।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-95","question":"Pulses costing ₹90 per kg and ₹120 per kg are mixed. How many kg of the dearer variety must be mixed with 24 kg of the cheaper one to get a mixture worth ₹102 per kg?","options":["36 kg","12 kg","16 kg","18 kg"],"answer":2,"explanation":"Alligation: cheaper : dearer = (120 − 102) : (102 − 90) = 18 : 12 = 3 : 2. With 24 kg cheaper, dearer = 16 kg.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"₹90 प्रति किग्रा और ₹120 प्रति किग्रा वाली दालों को मिलाया जाता है। ₹102 प्रति किग्रा मूल्य का मिश्रण पाने के लिए 24 किग्रा सस्ती दाल में महँगी किस्म की कितने किग्रा दाल मिलानी होगी?","optionsHi":["36 किग्रा","12 किग्रा","16 किग्रा","18 किग्रा"],"explanationHi":"एलिगेशन विधि से: सस्ती : महँगी = (120 − 102) : (102 − 90) = 18 : 12 = 3 : 2। 24 किग्रा सस्ती के साथ महँगी = 16 किग्रा।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-96","question":"₹1,300 is shared among A, B and C so that if ₹20, ₹30 and ₹50 are taken away from their shares, the remainders are in the ratio 3 : 4 : 5. What is B's share?","options":["₹400","₹430","₹450","₹433"],"answer":1,"explanation":"Remainders total 1,300 − 100 = 1,200 in 12 parts, so one part = 100. B = 400 + 30 = ₹430.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"₹1,300 को A, B और C में इस प्रकार बाँटा गया कि उनके हिस्सों में से क्रमशः ₹20, ₹30 और ₹50 घटाने पर शेष राशियाँ 3 : 4 : 5 के अनुपात में हैं। B का हिस्सा क्या है?","optionsHi":["₹400","₹430","₹450","₹433"],"explanationHi":"शेष राशियों का योग 1,300 − 100 = 1,200 है, जो 12 भाग हैं, अतः एक भाग = 100। B = 400 + 30 = ₹430।","subtopic":"dividing-amounts"},
  {"id":"quant-ratio-97","question":"Three numbers are in the ratio 3 : 4 : 5. The sum of the largest and the smallest equals the middle number plus 52. What is the largest number?","options":["52","65","39","60"],"answer":1,"explanation":"3k + 5k = 4k + 52 gives 4k = 52, so k = 13 and the largest is 65.","difficulty":"hard","source":"SSC CHSL · SSC CGL","questionHi":"तीन संख्याएँ 3 : 4 : 5 के अनुपात में हैं। सबसे बड़ी और सबसे छोटी संख्या का योग, मध्य संख्या में 52 जोड़ने के बराबर है। सबसे बड़ी संख्या क्या है?","optionsHi":["52","65","39","60"],"explanationHi":"3k + 5k = 4k + 52 से 4k = 52, अतः k = 13 और सबसे बड़ी संख्या 65 है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-98","question":"A and B invest ₹3 lakh and ₹2 lakh. Each first receives 10% interest on capital from the profit, and the rest is shared equally. If the profit is ₹1,10,000, what does A get in all?","options":["₹60,000","₹66,000","₹55,000","₹50,000"],"answer":0,"explanation":"Interest: A ₹30,000, B ₹20,000. The remaining ₹60,000 is split equally. A gets 30,000 + 30,000 = ₹60,000.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"A और B क्रमशः ₹3 लाख और ₹2 लाख लगाते हैं। लाभ में से पहले प्रत्येक को पूँजी पर 10% ब्याज मिलता है, और शेष बराबर बाँटा जाता है। यदि लाभ ₹1,10,000 है, तो A को कुल कितना मिलेगा?","optionsHi":["₹60,000","₹66,000","₹55,000","₹50,000"],"explanationHi":"ब्याज: A को ₹30,000, B को ₹20,000। शेष ₹60,000 बराबर बँटेगा। A को 30,000 + 30,000 = ₹60,000 मिलेंगे।","subtopic":"partnership"},
  {"id":"quant-ratio-99","question":"A's salary is 20% more than B's, and C's salary is 25% less than A's. What is A : B : C?","options":["6 : 5 : 4","12 : 10 : 8","5 : 4 : 3","12 : 10 : 9"],"answer":3,"explanation":"Take B = 10: A = 12 and C = 12 × 0.75 = 9, so 12 : 10 : 9. 12 : 10 : 8 (and its reduced form 6 : 5 : 4) makes C one-third less than A instead of one-quarter less.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"A का वेतन B से 20% अधिक है, और C का वेतन A से 25% कम है। A : B : C क्या है?","optionsHi":["6 : 5 : 4","12 : 10 : 8","5 : 4 : 3","12 : 10 : 9"],"explanationHi":"B = 10 लेने पर A = 12 और C = 12 × 0.75 = 9, अतः 12 : 10 : 9। 12 : 10 : 8 (और उसका सरलतम रूप 6 : 5 : 4) में C को A से एक-चौथाई की जगह एक-तिहाई कम मान लिया गया है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-100","question":"If a : b = c : d, then (a² + c²) : (b² + d²) equals:","options":["a : b","ac : bd","a² : b²","(a + c) : (b + d)²"],"answer":2,"explanation":"Let a/b = c/d = k, so a = bk and c = dk. Then (a² + c²)/(b² + d²) = k²(b² + d²)/(b² + d²) = k² = a²/b².","difficulty":"hard","source":"SSC CGL · CDS","questionHi":"यदि a : b = c : d है, तो (a² + c²) : (b² + d²) बराबर है:","optionsHi":["a : b","ac : bd","a² : b²","(a + c) : (b + d)²"],"explanationHi":"मान लें a/b = c/d = k, अतः a = bk और c = dk। तब (a² + c²)/(b² + d²) = k²(b² + d²)/(b² + d²) = k² = a²/b²।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-101","question":"A invests for 8 months and B for 6 months, and their profits are in the ratio 4 : 5. What is the ratio of their capitals?","options":["4 : 5","3 : 5","16 : 15","5 : 3"],"answer":1,"explanation":"Profit ∝ capital × time, so capital ∝ profit ÷ time: 4/8 : 5/6 = 1/2 : 5/6 = 3 : 5. 4 : 5 ignores time, and 16 : 15 multiplies by time instead of dividing.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"A 8 महीने और B 6 महीने के लिए पूँजी लगाता है, और उनके लाभ का अनुपात 4 : 5 है। उनकी पूँजी का अनुपात क्या है?","optionsHi":["4 : 5","3 : 5","16 : 15","5 : 3"],"explanationHi":"लाभ ∝ पूँजी × समय, इसलिए पूँजी ∝ लाभ ÷ समय: 4/8 : 5/6 = 1/2 : 5/6 = 3 : 5। 4 : 5 में समय को नहीं गिना गया है, और 16 : 15 में समय से भाग देने की जगह गुणा कर दिया गया है।","subtopic":"partnership"},
  {"id":"quant-ratio-102","question":"A 50-litre car tank is half full of E10 fuel (petrol and ethanol in the ratio 90 : 10). It is then filled up with E20 fuel (80 : 20). What is the ratio of petrol to ethanol in the tank now?","options":["17 : 3","85 : 10","3 : 17","9 : 1"],"answer":0,"explanation":"Ethanol = 10% of 25 + 20% of 25 = 2.5 + 5 = 7.5 L out of 50 L, i.e. 15%. Petrol : ethanol = 85 : 15 = 17 : 3.","difficulty":"hard","source":"SSC CGL · RRB NTPC","questionHi":"एक 50 लीटर की कार टंकी आधी E10 ईंधन (पेट्रोल और एथेनॉल 90 : 10 के अनुपात में) से भरी है। फिर उसे E20 ईंधन (80 : 20) से पूरा भर दिया जाता है। अब टंकी में पेट्रोल और एथेनॉल का अनुपात क्या है?","optionsHi":["17 : 3","85 : 10","3 : 17","9 : 1"],"explanationHi":"एथेनॉल = 25 का 10% + 25 का 20% = 2.5 + 5 = 7.5 L, कुल 50 L में से, यानी 15%। पेट्रोल : एथेनॉल = 85 : 15 = 17 : 3।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-103","question":"A jeweller mixes 24-carat gold with 18-carat gold to make 22-carat gold. How many grams of 18-carat gold should he add to 30 g of 24-carat gold?","options":["15 g","10 g","20 g","60 g"],"answer":0,"explanation":"Alligation on carats: 24k : 18k = (22 − 18) : (24 − 22) = 4 : 2 = 2 : 1. With 30 g of 24k, add 15 g of 18k.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक जौहरी 24 कैरेट सोने को 18 कैरेट सोने में मिलाकर 22 कैरेट सोना बनाता है। 30 g 24 कैरेट सोने में उसे 18 कैरेट का कितने ग्राम सोना मिलाना चाहिए?","optionsHi":["15 g","10 g","20 g","60 g"],"explanationHi":"कैरेट पर एलिगेशन विधि: 24k : 18k = (22 − 18) : (24 − 22) = 4 : 2 = 2 : 1। 30 g 24k के साथ 15 g 18k मिलाना होगा।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-104","question":"The ages of A, B and C add up to 90 years. Ten years ago their ages were in the ratio 1 : 2 : 3. What is C's present age?","options":["45 years","30 years","50 years","40 years"],"answer":3,"explanation":"Ten years ago the total was 90 − 30 = 60, split 1 : 2 : 3 as 10, 20, 30. C is now 30 + 10 = 40. Splitting 90 directly (45) forgets the ten years.","difficulty":"hard","source":"SSC CHSL · SSC CGL","questionHi":"A, B और C की आयु का योग 90 वर्ष है। दस वर्ष पहले उनकी आयु का अनुपात 1 : 2 : 3 था। C की वर्तमान आयु क्या है?","optionsHi":["45 वर्ष","30 वर्ष","50 वर्ष","40 वर्ष"],"explanationHi":"दस वर्ष पहले कुल योग 90 − 30 = 60 था, जो 1 : 2 : 3 में 10, 20, 30 बँटता है। C अब 30 + 10 = 40 वर्ष का है। 90 को सीधे बाँटने (45) में दस वर्ष भूल गए हैं।","subtopic":"ages"},
  {"id":"quant-ratio-105","question":"A trader sells part of 50 kg of sugar at 8% profit and the rest at 18% profit, making 14% profit overall. How much did he sell at 18% profit?","options":["20 kg","25 kg","30 kg","35 kg"],"answer":2,"explanation":"Alligation: 8% part : 18% part = (18 − 14) : (14 − 8) = 4 : 6 = 2 : 3. The 18% part = 3/5 × 50 = 30 kg.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"एक व्यापारी 50 किग्रा चीनी का कुछ भाग 8% लाभ पर और शेष 18% लाभ पर बेचता है, और कुल मिलाकर 14% लाभ कमाता है। उसने कितनी चीनी 18% लाभ पर बेची?","optionsHi":["20 किग्रा","25 किग्रा","30 किग्रा","35 किग्रा"],"explanationHi":"एलिगेशन विधि से: 8% वाला भाग : 18% वाला भाग = (18 − 14) : (14 − 8) = 4 : 6 = 2 : 3। 18% वाला भाग = 3/5 × 50 = 30 किग्रा।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-106","question":"A 40 g alloy contains gold, silver and copper in the ratio 5 : 3 : 2. How much silver must be added so that silver makes up half the alloy?","options":["8 g","16 g","12 g","20 g"],"answer":1,"explanation":"Silver = 12 g, the rest = 28 g, which stays fixed. For silver to be half, silver must also be 28 g: add 16 g.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"40 g की एक मिश्रधातु में सोना, चाँदी और ताँबा 5 : 3 : 2 के अनुपात में हैं। चाँदी को मिश्रधातु का आधा बनाने के लिए कितनी चाँदी मिलानी होगी?","optionsHi":["8 g","16 g","12 g","20 g"],"explanationHi":"चाँदी = 12 g, शेष = 28 g, जो स्थिर रहता है। चाँदी के आधा होने के लिए चाँदी भी 28 g होनी चाहिए: 16 g मिलाना होगा।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-107","question":"A concrete mix uses cement, sand and stone chips in the ratio 1 : 1.5 : 3 by volume. How many 0.04 m³ bags of cement are needed for 11 m³ of dry mix?","options":["55","50","40","44"],"answer":1,"explanation":"Total parts = 1 + 1.5 + 3 = 5.5, so cement = 11/5.5 = 2 m³ and bags = 2 ÷ 0.04 = 50. 44 uses 6.25 parts by miscounting, and 55 divides 11 by 5 parts.","difficulty":"hard","source":"RRB JE · SSC JE","questionHi":"एक कंक्रीट मिश्रण में सीमेंट, रेत और पत्थर की गिट्टी आयतन के अनुसार 1 : 1.5 : 3 के अनुपात में लगते हैं। 11 m³ सूखे मिश्रण के लिए 0.04 m³ वाले सीमेंट के कितने बोरे चाहिए?","optionsHi":["55","50","40","44"],"explanationHi":"कुल भाग = 1 + 1.5 + 3 = 5.5, अतः सीमेंट = 11/5.5 = 2 m³ और बोरे = 2 ÷ 0.04 = 50। 44 में गलत गिनती से 6.25 भाग लिए गए हैं, और 55 में 11 को 5 भागों से भाग दिया गया है।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-108","question":"A starts a business with ₹50,000. B joins x months later with ₹75,000. At the end of the year they share the profit equally. What is x?","options":["4","6","3","8"],"answer":0,"explanation":"Equal shares need equal capital × time: 50,000 × 12 = 75,000 × (12 − x), so 12 − x = 8 and x = 4. 8 is B's months in the business, not the delay.","difficulty":"hard","source":"SSC CGL · IBPS Clerk","questionHi":"A ₹50,000 से व्यापार शुरू करता है। B x महीने बाद ₹75,000 लेकर जुड़ता है। वर्ष के अंत में वे लाभ बराबर बाँटते हैं। x क्या है?","optionsHi":["4","6","3","8"],"explanationHi":"बराबर हिस्सों के लिए पूँजी × समय बराबर होना चाहिए: 50,000 × 12 = 75,000 × (12 − x), अतः 12 − x = 8 और x = 4। 8 व्यापार में B के रहने के महीने हैं, देरी नहीं।","subtopic":"partnership"},
  {"id":"quant-ratio-109","question":"A 50-litre mixture has milk and water in the ratio 4 : 1. 10 litres of it are removed and replaced with a mixture of milk and water in equal parts. What is the new ratio?","options":["4 : 1","32 : 13","9 : 4","37 : 13"],"answer":3,"explanation":"After removal: 32 L milk, 8 L water. Adding 5 L of each: 37 : 13.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"50 लीटर के एक मिश्रण में दूध और पानी का अनुपात 4 : 1 है। इसमें से 10 लीटर निकालकर उसकी जगह दूध और पानी का बराबर भागों वाला मिश्रण डाल दिया जाता है। नया अनुपात क्या है?","optionsHi":["4 : 1","32 : 13","9 : 4","37 : 13"],"explanationHi":"निकालने के बाद: 32 L दूध, 8 L पानी। दोनों के 5 L-5 L मिलाने पर: 37 : 13।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-110","question":"A and B invest ₹60,000 and ₹40,000. B manages the business and draws ₹1,000 a month as salary; the rest of the profit is shared in the ratio of capitals. If the yearly profit is ₹72,000, how much does B get in all?","options":["₹28,800","₹24,000","₹36,000","₹40,800"],"answer":2,"explanation":"Salary = ₹12,000. The remaining ₹60,000 is shared 3 : 2, so B gets ₹24,000. Total = ₹36,000.","difficulty":"hard","source":"IBPS PO · SBI PO","questionHi":"A और B क्रमशः ₹60,000 और ₹40,000 लगाते हैं। B व्यापार चलाता है और वेतन के रूप में ₹1,000 प्रति माह लेता है; शेष लाभ पूँजी के अनुपात में बँटता है। यदि वार्षिक लाभ ₹72,000 है, तो B को कुल कितना मिलेगा?","optionsHi":["₹28,800","₹24,000","₹36,000","₹40,800"],"explanationHi":"वेतन = ₹12,000। शेष ₹60,000 को 3 : 2 में बाँटने पर B को ₹24,000 मिलते हैं। कुल = ₹36,000।","subtopic":"partnership"},
  {"id":"quant-ratio-111","question":"Three farmers rent a pasture for ₹6,200. A grazes 8 buffaloes for 6 months, B 10 buffaloes for 4 months and C 12 buffaloes for 3 months. How much rent should C pay?","options":["₹2,000","₹2,480","₹1,800","₹2,067"],"answer":2,"explanation":"Buffalo-months: 48, 40 and 36, i.e. 12 : 10 : 9 (31 parts). C pays 9/31 × 6,200 = ₹1,800.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"तीन किसान ₹6,200 में एक चरागाह किराये पर लेते हैं। A 8 भैंसों को 6 महीने, B 10 भैंसों को 4 महीने और C 12 भैंसों को 3 महीने चराता है। C को कितना किराया देना चाहिए?","optionsHi":["₹2,000","₹2,480","₹1,800","₹2,067"],"explanationHi":"भैंस-महीने: 48, 40 और 36, यानी 12 : 10 : 9 (कुल 31 भाग)। C देगा 9/31 × 6,200 = ₹1,800।","subtopic":"partnership"},
  {"id":"quant-ratio-112","question":"Three numbers are in the ratio 3 : 4 : 7 and their product is 18,144. What is the largest number?","options":["35","42","49","28"],"answer":1,"explanation":"3k × 4k × 7k = 84k³ = 18,144, so k³ = 216 and k = 6. Largest = 42.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"तीन संख्याएँ 3 : 4 : 7 के अनुपात में हैं और उनका गुणनफल 18,144 है। सबसे बड़ी संख्या क्या है?","optionsHi":["35","42","49","28"],"explanationHi":"3k × 4k × 7k = 84k³ = 18,144, अतः k³ = 216 और k = 6। सबसे बड़ी = 42।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-113","question":"The daily wages of a man, a woman and a child are in the ratio 5 : 3 : 2. A contractor pays ₹9,900 a day to 20 men, 15 women and 10 children. What is a child's daily wage?","options":["₹120","₹100","₹180","₹60"],"answer":0,"explanation":"Total parts = 20 × 5 + 15 × 3 + 10 × 2 = 165, so one part = ₹60. A child gets 2 parts = ₹120.","difficulty":"hard","source":"SSC CHSL · RRB NTPC","questionHi":"एक पुरुष, एक महिला और एक बच्चे की दैनिक मजदूरी का अनुपात 5 : 3 : 2 है। एक ठेकेदार 20 पुरुषों, 15 महिलाओं और 10 बच्चों को प्रतिदिन ₹9,900 देता है। एक बच्चे की दैनिक मजदूरी क्या है?","optionsHi":["₹120","₹100","₹180","₹60"],"explanationHi":"कुल भाग = 20 × 5 + 15 × 3 + 10 × 2 = 165, अतः एक भाग = ₹60। बच्चे को 2 भाग = ₹120 मिलते हैं।","subtopic":"income-expenses"},
  {"id":"quant-ratio-114","question":"A salt solution is 15% salt. After 30 litres of water evaporate, it is 20% salt. How much solution was there at first?","options":["90 litres","150 litres","100 litres","120 litres"],"answer":3,"explanation":"Salt is fixed: 0.15V = 0.2(V − 30) gives 0.05V = 6, so V = 120 L.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"एक नमक के घोल में 15% नमक है। 30 लीटर पानी वाष्पित होने के बाद उसमें 20% नमक हो जाता है। शुरुआत में घोल कितना था?","optionsHi":["90 लीटर","150 लीटर","100 लीटर","120 लीटर"],"explanationHi":"नमक स्थिर रहता है: 0.15V = 0.2(V − 30) से 0.05V = 6, अतः V = 120 L।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-115","question":"A starts with ₹2 lakh and adds ₹50,000 after every 3 months. B invests ₹3.5 lakh for the whole year. In what ratio should they share the profit?","options":["4 : 7","1 : 1","14 : 11","11 : 14"],"answer":3,"explanation":"A (in lakh-months): 2 × 3 + 2.5 × 3 + 3 × 3 + 3.5 × 3 = 33. B: 3.5 × 12 = 42. Ratio 33 : 42 = 11 : 14.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"A ₹2 लाख से शुरू करता है और हर 3 महीने बाद ₹50,000 जोड़ता है। B पूरे वर्ष के लिए ₹3.5 लाख लगाता है। उन्हें लाभ किस अनुपात में बाँटना चाहिए?","optionsHi":["4 : 7","1 : 1","14 : 11","11 : 14"],"explanationHi":"A (लाख-महीनों में): 2 × 3 + 2.5 × 3 + 3 × 3 + 3.5 × 3 = 33। B: 3.5 × 12 = 42। अनुपात 33 : 42 = 11 : 14।","subtopic":"partnership"},
  {"id":"quant-ratio-116","question":"If x/(y + z) = y/(z + x) = z/(x + y) = k, what are the possible values of k?","options":["1/2 only","−1 only","1/2 or −1","2 or −1"],"answer":2,"explanation":"Adding numerators and denominators: k = (x + y + z)/(2(x + y + z)) = 1/2 when x + y + z ≠ 0. If x + y + z = 0, then y + z = −x and k = −1.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"यदि x/(y + z) = y/(z + x) = z/(x + y) = k है, तो k के संभावित मान क्या हैं?","optionsHi":["केवल 1/2","केवल −1","1/2 या −1","2 या −1"],"explanationHi":"अंशों और हरों को जोड़ने पर: जब x + y + z ≠ 0 हो, k = (x + y + z)/(2(x + y + z)) = 1/2। यदि x + y + z = 0 हो, तो y + z = −x और k = −1।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-117","question":"Three vessels contain milk and water in the ratios 3 : 1, 5 : 3 and 9 : 7. Mixtures are taken from them in the volume ratio 1 : 2 : 4 and combined. What is the ratio of milk to water in the result?","options":["17 : 7","17 : 11","3 : 2","11 : 17"],"answer":1,"explanation":"Milk = 1 × 3/4 + 2 × 5/8 + 4 × 9/16 = 0.75 + 1.25 + 2.25 = 4.25 out of 7. Water = 2.75. Ratio 4.25 : 2.75 = 17 : 11.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"तीन बर्तनों में दूध और पानी क्रमशः 3 : 1, 5 : 3 और 9 : 7 के अनुपात में हैं। उनसे मिश्रण आयतन के अनुपात 1 : 2 : 4 में लेकर मिला दिया जाता है। परिणामी मिश्रण में दूध और पानी का अनुपात क्या है?","optionsHi":["17 : 7","17 : 11","3 : 2","11 : 17"],"explanationHi":"दूध = 1 × 3/4 + 2 × 5/8 + 4 × 9/16 = 0.75 + 1.25 + 2.25 = 4.25, कुल 7 में से। पानी = 2.75। अनुपात 4.25 : 2.75 = 17 : 11।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-118","question":"Milk costs a vendor ₹60 per litre. He mixes it with water and sells the mixture at ₹54 per litre, making a 25% profit. What is the ratio of water to milk?","options":["7 : 18","1 : 9","2 : 9","5 : 18"],"answer":0,"explanation":"Cost of the mixture = 54 ÷ 1.25 = ₹43.20 per litre. Alligation (water costs 0): water : milk = (60 − 43.2) : 43.2 = 16.8 : 43.2 = 7 : 18.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk","questionHi":"एक विक्रेता को दूध ₹60 प्रति लीटर पड़ता है। वह उसमें पानी मिलाकर मिश्रण को ₹54 प्रति लीटर पर बेचता है और 25% लाभ कमाता है। पानी और दूध का अनुपात क्या है?","optionsHi":["7 : 18","1 : 9","2 : 9","5 : 18"],"explanationHi":"मिश्रण का क्रय मूल्य = 54 ÷ 1.25 = ₹43.20 प्रति लीटर। एलिगेशन विधि से (पानी की कीमत 0): पानी : दूध = (60 − 43.2) : 43.2 = 16.8 : 43.2 = 7 : 18।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-119","question":"The present ages of a father and his son are in the ratio 8 : 3. Five years ago the product of their ages was 350. What is the father's present age?","options":["40 years","48 years","32 years","35 years"],"answer":0,"explanation":"(8x − 5)(3x − 5) = 350. Trying x = 5: 35 × 10 = 350 ✓. Father = 40 years.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक पिता और उसके पुत्र की वर्तमान आयु का अनुपात 8 : 3 है। पाँच वर्ष पहले उनकी आयु का गुणनफल 350 था। पिता की वर्तमान आयु क्या है?","optionsHi":["40 वर्ष","48 वर्ष","32 वर्ष","35 वर्ष"],"explanationHi":"(8x − 5)(3x − 5) = 350। x = 5 लेने पर: 35 × 10 = 350 ✓। पिता = 40 वर्ष।","subtopic":"ages"},
  {"id":"quant-ratio-120","question":"From a can of pure milk, one-fourth is taken out and replaced with water. Then one-third of the mixture is replaced with water, and then half of the new mixture is replaced with water. What is the final ratio of milk to water?","options":["1 : 2","1 : 4","3 : 5","1 : 3"],"answer":3,"explanation":"Milk left = 3/4 × 2/3 × 1/2 = 1/4 of the can. Milk : water = 1/4 : 3/4 = 1 : 3.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"शुद्ध दूध से भरे एक कैन में से एक-चौथाई निकालकर उसकी जगह पानी डाला जाता है। फिर मिश्रण का एक-तिहाई निकालकर पानी डाला जाता है, और फिर नए मिश्रण का आधा निकालकर पानी डाला जाता है। अंत में दूध और पानी का अनुपात क्या है?","optionsHi":["1 : 2","1 : 4","3 : 5","1 : 3"],"explanationHi":"बचा दूध = 3/4 × 2/3 × 1/2 = कैन का 1/4। दूध : पानी = 1/4 : 3/4 = 1 : 3।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-121","question":"A's capital is three-fourths of B's. After 4 months A withdraws half his capital, and after 6 months B withdraws one-third of his. Out of a year-end profit of ₹39,000, what is A's share?","options":["₹16,714","₹19,500","₹14,625","₹13,000"],"answer":2,"explanation":"Take A = 3, B = 4. A: 3 × 4 + 1.5 × 8 = 24. B: 4 × 6 + (8/3) × 6 = 40. Ratio 3 : 5, so A = 3/8 × 39,000 = ₹14,625.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"A की पूँजी B की पूँजी की तीन-चौथाई है। 4 महीने बाद A अपनी आधी पूँजी निकाल लेता है, और 6 महीने बाद B अपनी एक-तिहाई पूँजी निकाल लेता है। वर्ष के अंत में ₹39,000 के लाभ में से A का हिस्सा क्या है?","optionsHi":["₹16,714","₹19,500","₹14,625","₹13,000"],"explanationHi":"A = 3, B = 4 लें। A: 3 × 4 + 1.5 × 8 = 24। B: 4 × 6 + (8/3) × 6 = 40। अनुपात 3 : 5, अतः A = 3/8 × 39,000 = ₹14,625।","subtopic":"partnership"},
  {"id":"quant-ratio-122","question":"x : y : z = 2 : 3 : 5 and (x + y)(y + z)(z + x) = 7,560. What is x?","options":["4","6","9","3"],"answer":1,"explanation":"(5k)(8k)(7k) = 280k³ = 7,560, so k³ = 27 and k = 3. x = 2k = 6.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"x : y : z = 2 : 3 : 5 है और (x + y)(y + z)(z + x) = 7,560 है। x क्या है?","optionsHi":["4","6","9","3"],"explanationHi":"(5k)(8k)(7k) = 280k³ = 7,560, अतः k³ = 27 और k = 3। x = 2k = 6।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-123","question":"A sum is to be divided among A, B and C in the ratio 3 : 4 : 5. If it were divided in the ratio 4 : 5 : 6 instead, A would get ₹120 more. What is the sum?","options":["₹1,440","₹7,200","₹6,000","₹9,000"],"answer":1,"explanation":"A's share changes from 3/12 = 1/4 to 4/15, a rise of 1/60 of the sum. So the sum = 120 × 60 = ₹7,200 (B's share, 1/3, does not change at all).","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"एक राशि को A, B और C में 3 : 4 : 5 के अनुपात में बाँटा जाना है। यदि इसे 4 : 5 : 6 के अनुपात में बाँटा जाता, तो A को ₹120 अधिक मिलते। राशि क्या है?","optionsHi":["₹1,440","₹7,200","₹6,000","₹9,000"],"explanationHi":"A का हिस्सा 3/12 = 1/4 से बदलकर 4/15 हो जाता है, यानी राशि का 1/60 बढ़ जाता है। अतः राशि = 120 × 60 = ₹7,200 (B का हिस्सा, 1/3, बिल्कुल नहीं बदलता)।","subtopic":"dividing-amounts"},
  {"id":"quant-ratio-124","question":"Jar A has 40 litres of pure milk and jar B has 40 litres of pure water. 10 litres are poured from A into B, and then 10 litres of the mixture are poured from B back into A. What is the ratio of milk to water in A now?","options":["4 : 1","3 : 1","5 : 1","8 : 1"],"answer":0,"explanation":"A keeps 30 L milk. B has 10 milk + 40 water (1 : 4). The 10 L returned has 2 L milk and 8 L water, so A has 32 : 8 = 4 : 1.","difficulty":"very-hard","source":"SSC CGL · CAT-style","questionHi":"जार A में 40 लीटर शुद्ध दूध है और जार B में 40 लीटर शुद्ध पानी है। A से 10 लीटर B में डाला जाता है, और फिर B से 10 लीटर मिश्रण वापस A में डाला जाता है। अब A में दूध और पानी का अनुपात क्या है?","optionsHi":["4 : 1","3 : 1","5 : 1","8 : 1"],"explanationHi":"A में 30 L दूध बचता है। B में 10 दूध + 40 पानी (1 : 4) है। लौटाए गए 10 L में 2 L दूध और 8 L पानी है, इसलिए A में 32 : 8 = 4 : 1।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-125","question":"A is twice as old as B was when A was as old as B is now. If their ages add up to 63 years, how old is A?","options":["42 years","27 years","32 years","36 years"],"answer":3,"explanation":"Let the age gap be d = A − B. When A was B's present age, B was B − d. So A = 2(B − d) = 2(2B − A), giving 3A = 4B. With A + B = 63: A = 36, B = 27.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"A की आयु, B की उस समय की आयु से दोगुनी है जब A की आयु वही थी जो B की अब है। यदि उनकी आयु का योग 63 वर्ष है, तो A की आयु कितनी है?","optionsHi":["42 वर्ष","27 वर्ष","32 वर्ष","36 वर्ष"],"explanationHi":"आयु का अंतर d = A − B मानें। जब A की आयु B की वर्तमान आयु के बराबर थी, तब B की आयु B − d थी। अतः A = 2(B − d) = 2(2B − A), जिससे 3A = 4B। A + B = 63 के साथ: A = 36, B = 27।","subtopic":"ages"},
  {"id":"quant-ratio-126","question":"If a : b = 3 : 2 and b : c = 4 : 5, what is (a² + b² + c²) : (ab + bc + ca)?","options":["74 : 77","11 : 10","77 : 74","25 : 24"],"answer":2,"explanation":"a : b : c = 6 : 4 : 5. Then a² + b² + c² = 36 + 16 + 25 = 77 and ab + bc + ca = 24 + 20 + 30 = 74.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"यदि a : b = 3 : 2 और b : c = 4 : 5 है, तो (a² + b² + c²) : (ab + bc + ca) क्या है?","optionsHi":["74 : 77","11 : 10","77 : 74","25 : 24"],"explanationHi":"a : b : c = 6 : 4 : 5। तब a² + b² + c² = 36 + 16 + 25 = 77 और ab + bc + ca = 24 + 20 + 30 = 74।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-127","question":"Vessel P has milk and water in the ratio 3 : 1 and vessel Q in the ratio 1 : 1. In what ratio should they be mixed to get milk and water in the ratio 2 : 1?","options":["1 : 2","3 : 1","2 : 1","1 : 1"],"answer":2,"explanation":"Milk fractions: P = 3/4, Q = 1/2, target = 2/3. Alligation: P : Q = (2/3 − 1/2) : (3/4 − 2/3) = 1/6 : 1/12 = 2 : 1.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk","questionHi":"बर्तन P में दूध और पानी का अनुपात 3 : 1 है और बर्तन Q में 1 : 1। दूध और पानी का अनुपात 2 : 1 पाने के लिए उन्हें किस अनुपात में मिलाना चाहिए?","optionsHi":["1 : 2","3 : 1","2 : 1","1 : 1"],"explanationHi":"दूध के भिन्न: P = 3/4, Q = 1/2, अभीष्ट = 2/3। एलिगेशन विधि से: P : Q = (2/3 − 1/2) : (3/4 − 2/3) = 1/6 : 1/12 = 2 : 1।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-128","question":"A sum is divided among A, B and C so that A gets one-third of what B and C together get, and B gets two-sevenths of what A and C together get. If A gets ₹1,500, what is the total?","options":["₹4,500","₹6,000","₹5,250","₹7,500"],"answer":1,"explanation":"A = (S − A)/3 gives A = S/4; B = 2(S − B)/7 gives B = 2S/9. With A = 1,500, S = ₹6,000 (B = ₹1,333.33, C the rest).","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"एक राशि को A, B और C में इस प्रकार बाँटा गया कि A को B और C के कुल का एक-तिहाई मिलता है, और B को A और C के कुल का दो-सातवाँ भाग मिलता है। यदि A को ₹1,500 मिलते हैं, तो कुल राशि क्या है?","optionsHi":["₹4,500","₹6,000","₹5,250","₹7,500"],"explanationHi":"A = (S − A)/3 से A = S/4; B = 2(S − B)/7 से B = 2S/9। A = 1,500 होने पर S = ₹6,000 (B = ₹1,333.33, शेष C का)।","subtopic":"dividing-amounts"},
  {"id":"quant-ratio-129","question":"If (a + b) : (b + c) : (c + a) = 6 : 7 : 8 and a + b + c = 21, what is c?","options":["9","7","5","8"],"answer":0,"explanation":"Adding: 2(a + b + c) = 21k = 42, so k = 2. Then a + b = 12, so c = 21 − 12 = 9.","difficulty":"very-hard","source":"SSC CGL · CDS","questionHi":"यदि (a + b) : (b + c) : (c + a) = 6 : 7 : 8 और a + b + c = 21 है, तो c क्या है?","optionsHi":["9","7","5","8"],"explanationHi":"जोड़ने पर: 2(a + b + c) = 21k = 42, अतः k = 2। तब a + b = 12, इसलिए c = 21 − 12 = 9।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-130","question":"A 60-litre vessel holds liquids P, Q and R in the ratio 3 : 4 : 5. 12 litres of the mixture are removed and replaced with liquid P. What is the new ratio of P : Q : R?","options":["3 : 4 : 5","5 : 4 : 5","9 : 8 : 10","6 : 4 : 5"],"answer":3,"explanation":"48 L remain: P 12, Q 16, R 20. Adding 12 L of P gives 24 : 16 : 20 = 6 : 4 : 5.","difficulty":"very-hard","source":"SSC CGL · IBPS PO","questionHi":"60 लीटर के एक बर्तन में तरल P, Q और R 3 : 4 : 5 के अनुपात में हैं। 12 लीटर मिश्रण निकालकर उसकी जगह तरल P डाल दिया जाता है। P : Q : R का नया अनुपात क्या है?","optionsHi":["3 : 4 : 5","5 : 4 : 5","9 : 8 : 10","6 : 4 : 5"],"explanationHi":"48 L बचता है: P 12, Q 16, R 20। 12 L P मिलाने पर 24 : 16 : 20 = 6 : 4 : 5।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-131","question":"Two schools have students in the ratio 5 : 7. If 30 students move from the second school to the first, the ratio becomes 4 : 5. How many students are there in all?","options":["1,200","960","1,350","1,080"],"answer":3,"explanation":"5(5x + 30) = 4(7x − 30) gives 25x + 150 = 28x − 120, so x = 90. Total = 12 × 90 = 1,080.","difficulty":"very-hard","source":"SSC CGL · SSC CHSL","questionHi":"दो विद्यालयों में विद्यार्थियों का अनुपात 5 : 7 है। यदि दूसरे विद्यालय से 30 विद्यार्थी पहले विद्यालय में चले जाएँ, तो अनुपात 4 : 5 हो जाता है। कुल कितने विद्यार्थी हैं?","optionsHi":["1,200","960","1,350","1,080"],"explanationHi":"5(5x + 30) = 4(7x − 30) से 25x + 150 = 28x − 120, अतः x = 90। कुल = 12 × 90 = 1,080।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-132","question":"A invests ₹20,000 for the whole year. B invests ₹30,000 but withdraws ₹10,000 after 6 months. C joins after 4 months with ₹25,000. Out of a profit of ₹37,000, what is C's share?","options":["₹10,000","₹12,500","₹11,250","₹9,250"],"answer":0,"explanation":"In thousand-months: A 240, B 180 + 120 = 300, C 25 × 8 = 200. Total 740, so C = 200/740 × 37,000 = ₹10,000.","difficulty":"very-hard","source":"IBPS PO · SBI PO","questionHi":"A पूरे वर्ष के लिए ₹20,000 लगाता है। B ₹30,000 लगाता है लेकिन 6 महीने बाद ₹10,000 निकाल लेता है। C 4 महीने बाद ₹25,000 लेकर जुड़ता है। ₹37,000 के लाभ में से C का हिस्सा क्या है?","optionsHi":["₹10,000","₹12,500","₹11,250","₹9,250"],"explanationHi":"हज़ार-महीनों में: A = 240, B = 180 + 120 = 300, C = 25 × 8 = 200। कुल 740, अतः C = 200/740 × 37,000 = ₹10,000।","subtopic":"partnership"},
  {"id":"quant-ratio-133","question":"The present ages of A and B are in the ratio 5 : 4. A's age 6 years ago equals B's age 2 years from now. How old is A?","options":["32 years","45 years","35 years","40 years"],"answer":3,"explanation":"5x − 6 = 4x + 2 gives x = 8, so A is 40 and B is 32. 32 is B's age, the usual slip, and 35 or 45 do not keep the 5 : 4 ratio with the 8-year gap.","difficulty":"hard","source":"SSC CHSL · SSC CGL","questionHi":"A और B की वर्तमान आयु का अनुपात 5 : 4 है। 6 वर्ष पहले A की आयु, अब से 2 वर्ष बाद B की आयु के बराबर है। A की आयु कितनी है?","optionsHi":["32 वर्ष","45 वर्ष","35 वर्ष","40 वर्ष"],"explanationHi":"5x − 6 = 4x + 2 से x = 8, इसलिए A 40 वर्ष का और B 32 वर्ष का है। 32 B की आयु है, जो आम भूल है, और 35 या 45 में 8 वर्ष के अंतर के साथ 5 : 4 का अनुपात नहीं बनता।","subtopic":"ages"},
  {"id":"quant-ratio-134","question":"If x : y = 2 : 3 and y : z = 4 : 5, what is (x + y + z) : (x − y + z)?","options":["35 : 19","11 : 35","35 : 11","7 : 3"],"answer":2,"explanation":"x : y : z = 8 : 12 : 15. Then (8 + 12 + 15) : (8 − 12 + 15) = 35 : 11.","difficulty":"very-hard","source":"SSC CGL · SSC CPO","questionHi":"यदि x : y = 2 : 3 और y : z = 4 : 5 है, तो (x + y + z) : (x − y + z) क्या है?","optionsHi":["35 : 19","11 : 35","35 : 11","7 : 3"],"explanationHi":"x : y : z = 8 : 12 : 15। तब (8 + 12 + 15) : (8 − 12 + 15) = 35 : 11।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-135","question":"Vessel A has milk and water in the ratio 3 : 2 and vessel B in the ratio 7 : 3. In what ratio must they be mixed to get milk and water in the ratio 2 : 1?","options":["2 : 1","1 : 2","3 : 7","1 : 1"],"answer":1,"explanation":"Milk fractions: A = 3/5, B = 7/10, target = 2/3. Alligation: A : B = (7/10 − 2/3) : (2/3 − 3/5) = 1/30 : 2/30 = 1 : 2.","difficulty":"very-hard","source":"SSC CGL · IBPS Clerk","questionHi":"बर्तन A में दूध और पानी का अनुपात 3 : 2 है और बर्तन B में 7 : 3। दूध और पानी का अनुपात 2 : 1 पाने के लिए उन्हें किस अनुपात में मिलाना होगा?","optionsHi":["2 : 1","1 : 2","3 : 7","1 : 1"],"explanationHi":"दूध के भिन्न: A = 3/5, B = 7/10, अभीष्ट = 2/3। एलिगेशन विधि से: A : B = (7/10 − 2/3) : (2/3 − 3/5) = 1/30 : 2/30 = 1 : 2।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-136","question":"₹3,450 is divided in the ratio 1/2 : 2/3 : 3/4. What is the largest share?","options":["₹1,200","₹1,350","₹900","₹1,150"],"answer":1,"explanation":"Multiply by 12: 6 : 8 : 9 (23 parts). One part = ₹150, so the largest = 9 × 150 = ₹1,350.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"₹3,450 को 1/2 : 2/3 : 3/4 के अनुपात में बाँटा गया है। सबसे बड़ा हिस्सा क्या है?","optionsHi":["₹1,200","₹1,350","₹900","₹1,150"],"explanationHi":"12 से गुणा करने पर: 6 : 8 : 9 (कुल 23 भाग)। एक भाग = ₹150, अतः सबसे बड़ा = 9 × 150 = ₹1,350।","subtopic":"dividing-amounts"},
  {"id":"quant-ratio-137","question":"If 30% of x equals 0.5y and y : z = 3 : 4, what is x : z?","options":["5 : 4","3 : 4","5 : 3","4 : 5"],"answer":0,"explanation":"x = 0.5y/0.3 = 5y/3, so x : y = 5 : 3. With y : z = 3 : 4, x : z = 5 : 4.","difficulty":"moderate","source":"SSC CHSL · SSC CGL","questionHi":"यदि x का 30%, 0.5y के बराबर है और y : z = 3 : 4 है, तो x : z क्या है?","optionsHi":["5 : 4","3 : 4","5 : 3","4 : 5"],"explanationHi":"x = 0.5y/0.3 = 5y/3, अतः x : y = 5 : 3। y : z = 3 : 4 के साथ, x : z = 5 : 4।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-138","question":"10 kg of a brass alloy with copper and zinc in the ratio 3 : 2 is melted with 14 kg of another with the ratio 4 : 3. What is the ratio of copper to zinc in the new alloy?","options":["7 : 6","3 : 2","4 : 3","7 : 5"],"answer":3,"explanation":"Copper = 6 + 8 = 14 kg; zinc = 4 + 6 = 10 kg. Ratio 14 : 10 = 7 : 5.","difficulty":"hard","source":"SSC CGL · SSC CHSL","questionHi":"ताँबा और जस्ता 3 : 2 के अनुपात वाली पीतल की 10 kg मिश्रधातु को 4 : 3 के अनुपात वाली 14 kg दूसरी मिश्रधातु के साथ पिघलाया जाता है। नई मिश्रधातु में ताँबे और जस्ते का अनुपात क्या है?","optionsHi":["7 : 6","3 : 2","4 : 3","7 : 5"],"explanationHi":"ताँबा = 6 + 8 = 14 kg; जस्ता = 4 + 6 = 10 kg। अनुपात 14 : 10 = 7 : 5।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-139","question":"What is the mean proportional between (3 + √2) and (12 − √32)?","options":["√28 + 2","4√2","2√7","6"],"answer":2,"explanation":"√32 = 4√2, so the product = (3 + √2)(12 − 4√2) = 36 − 12√2 + 12√2 − 8 = 28. Mean proportional = √28 = 2√7.","difficulty":"very-hard","source":"SSC CGL Tier 2 · CDS","questionHi":"(3 + √2) और (12 − √32) के बीच मध्यानुपाती क्या है?","optionsHi":["√28 + 2","4√2","2√7","6"],"explanationHi":"√32 = 4√2, इसलिए गुणनफल = (3 + √2)(12 − 4√2) = 36 − 12√2 + 12√2 − 8 = 28। मध्यानुपाती = √28 = 2√7।","subtopic":"proportion-variation"},
  {"id":"quant-ratio-140","question":"The incomes of A and B are in the ratio 5 : 4 and their expenses in the ratio 3 : 2. A saves ₹6,000 and B saves ₹7,000. What are B's expenses?","options":["₹11,000","₹16,500","₹18,000","₹22,500"],"answer":0,"explanation":"5x − 3y = 6,000 and 4x − 2y = 7,000 give x = 4,500 and y = 5,500, so B spends 2 × 5,500 = ₹11,000. ₹16,500 is A's spending; ₹18,000 is B's income.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A और B की आय का अनुपात 5 : 4 है और उनके व्यय का अनुपात 3 : 2 है। A ₹6,000 और B ₹7,000 बचाता है। B का व्यय कितना है?","optionsHi":["₹11,000","₹16,500","₹18,000","₹22,500"],"explanationHi":"5x − 3y = 6,000 और 4x − 2y = 7,000 से x = 4,500 और y = 5,500, अतः B का व्यय 2 × 5,500 = ₹11,000। ₹16,500 A का व्यय है; ₹18,000 B की आय है।","subtopic":"income-expenses"},
  {"id":"quant-ratio-141","question":"A starts a business with ₹45,000. B joins after 3 months with ₹60,000 and C after 6 months with ₹90,000. A withdraws ₹15,000 at the end of the 8th month. Out of a year-end profit of ₹1,30,000, what is C's share?","options":["₹40,000","₹45,000","₹43,333.33","₹60,000"],"answer":1,"explanation":"Capital × months: A = 45,000×8 + 30,000×4 = 4,80,000; B = 60,000×9 = 5,40,000; C = 90,000×6 = 5,40,000; ratio 8 : 9 : 9, so C gets 1,30,000 × 9/26 = ₹45,000. Splitting by capital alone gives ₹60,000.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"A ₹45,000 से व्यापार शुरू करता है। B 3 महीने बाद ₹60,000 लेकर और C 6 महीने बाद ₹90,000 लेकर जुड़ता है। A 8वें महीने के अंत में ₹15,000 निकाल लेता है। वर्ष के अंत में ₹1,30,000 के लाभ में से C का हिस्सा क्या है?","optionsHi":["₹40,000","₹45,000","₹43,333.33","₹60,000"],"explanationHi":"पूँजी × महीने: A = 45,000×8 + 30,000×4 = 4,80,000; B = 60,000×9 = 5,40,000; C = 90,000×6 = 5,40,000; अनुपात 8 : 9 : 9, अतः C को 1,30,000 × 9/26 = ₹45,000 मिलेंगे। केवल पूँजी के आधार पर बाँटने से ₹60,000 आता है।","subtopic":"partnership"},
  {"id":"quant-ratio-142","question":"A vessel full of milk and water in the ratio 7 : 3 has 20 litres of the mixture drawn off and replaced with water. The ratio becomes 7 : 5. What is the capacity of the vessel?","options":["100 L","120 L","150 L","140 L"],"answer":1,"explanation":"After the draw, milk = 0.7(V − 20) and water = 0.3(V − 20) + 20. Setting their ratio to 7 : 5 gives 3.5(V − 20) = 2.1(V − 20) + 140, so V − 20 = 100 and V = 120 L. Forgetting that milk also leaves with the mixture gives 100 L; forgetting that water leaves gives 150 L.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"दूध और पानी के 7 : 3 के अनुपात वाले मिश्रण से भरे एक बर्तन में से 20 लीटर मिश्रण निकालकर उसकी जगह पानी डाल दिया जाता है। अनुपात 7 : 5 हो जाता है। बर्तन की धारिता क्या है?","optionsHi":["100 L","120 L","150 L","140 L"],"explanationHi":"निकालने के बाद, दूध = 0.7(V − 20) और पानी = 0.3(V − 20) + 20। उनका अनुपात 7 : 5 रखने पर 3.5(V − 20) = 2.1(V − 20) + 140, अतः V − 20 = 100 और V = 120 L। यह भूल जाने पर कि दूध भी मिश्रण के साथ निकलता है, 100 L आता है; यह भूलने पर कि पानी भी निकलता है, 150 L आता है।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-143","question":"From a can holding 80 litres of pure milk, 8 litres are drawn and replaced with water. This is done three times in all. What is the final ratio of milk to water?","options":["7 : 3","81 : 19","729 : 1000","729 : 271"],"answer":3,"explanation":"Each operation keeps 9/10 of the milk: 80 × (0.9)³ = 58.32 L milk and 21.68 L water, i.e. 729 : 271. Removing a flat 8 L of milk each time gives 7 : 3; 729 : 1000 is milk to the whole.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"80 लीटर शुद्ध दूध वाले एक कैन में से 8 लीटर निकालकर उसकी जगह पानी डाला जाता है। यह क्रिया कुल तीन बार की जाती है। अंत में दूध और पानी का अनुपात क्या है?","optionsHi":["7 : 3","81 : 19","729 : 1000","729 : 271"],"explanationHi":"हर क्रिया में दूध का 9/10 भाग बचता है: 80 × (0.9)³ = 58.32 L दूध और 21.68 L पानी, यानी 729 : 271। हर बार केवल 8 L दूध घटाने पर 7 : 3 आता है; 729 : 1000 दूध और कुल मात्रा का अनुपात है।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-144","question":"A bag contains ₹1, 50-paise and 25-paise coins in the ratio 5 : 6 : 8, worth ₹210 in all. How many 50-paise coins are there?","options":["105","168","126","63"],"answer":2,"explanation":"One 'set' of 5 + 6 + 8 coins is worth 5 + 3 + 2 = ₹10, so there are 21 sets and 6 × 21 = 126 fifty-paise coins. ₹63 is their value, not their number.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक थैले में ₹1, 50 पैसे और 25 पैसे के सिक्के 5 : 6 : 8 के अनुपात में हैं, जिनका कुल मूल्य ₹210 है। 50 पैसे के कितने सिक्के हैं?","optionsHi":["105","168","126","63"],"explanationHi":"5 + 6 + 8 सिक्कों के एक 'समूह' का मूल्य 5 + 3 + 2 = ₹10 है, इसलिए 21 समूह हैं और 50 पैसे के सिक्के 6 × 21 = 126 हैं। ₹63 उनका मूल्य है, संख्या नहीं।","subtopic":"coins"},
  {"id":"quant-ratio-145","question":"x is the mean proportional between 8 and 18, and y is the third proportional to 8 and 12. What is x : y?","options":["3 : 2","2 : 3","1 : 1","4 : 9"],"answer":1,"explanation":"x = √(8×18) = 12, and y = 12²/8 = 18, so x : y = 2 : 3. Swapping the two gives 3 : 2.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"x, 8 और 18 का मध्यानुपाती है, और y, 8 और 12 का तृतीयानुपाती है। x : y क्या है?","optionsHi":["3 : 2","2 : 3","1 : 1","4 : 9"],"explanationHi":"x = √(8×18) = 12, और y = 12²/8 = 18, अतः x : y = 2 : 3। दोनों को आपस में बदल देने पर 3 : 2 आता है।","subtopic":"proportion-variation"},
  {"id":"quant-ratio-146","question":"The sum of the present ages of A, B and C is 96 years. Four years ago their ages were in the ratio 3 : 4 : 5. What will be the ratio of their ages 8 years from now?","options":["33 : 40 : 47","3 : 4 : 5","25 : 32 : 39","29 : 36 : 43"],"answer":0,"explanation":"Four years ago the sum was 84, so the ages were 21, 28, 35; now 25, 32, 39; in 8 years 33, 40, 47. 25 : 32 : 39 is the present ratio.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A, B और C की वर्तमान आयु का योग 96 वर्ष है। चार वर्ष पहले उनकी आयु का अनुपात 3 : 4 : 5 था। 8 वर्ष बाद उनकी आयु का अनुपात क्या होगा?","optionsHi":["33 : 40 : 47","3 : 4 : 5","25 : 32 : 39","29 : 36 : 43"],"explanationHi":"चार वर्ष पहले योग 84 था, इसलिए आयु 21, 28, 35 थी; अब 25, 32, 39; 8 वर्ष बाद 33, 40, 47। 25 : 32 : 39 वर्तमान अनुपात है।","subtopic":"ages"},
  {"id":"quant-ratio-147","question":"x varies directly as the square of y and inversely as z. When y = 4 and z = 8, x = 6. What is x when y = 6 and z = 3?","options":["24","1","13.5","36"],"answer":3,"explanation":"x = ky²/z: 6 = 16k/8 gives k = 3, so x = 3 × 36/3 = 36. Using y instead of y² gives 24; ignoring the change in z gives 13.5.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"x, y के वर्ग के सीधे समानुपाती और z के व्युत्क्रमानुपाती है। जब y = 4 और z = 8 है, तब x = 6 है। y = 6 और z = 3 होने पर x क्या होगा?","optionsHi":["24","1","13.5","36"],"explanationHi":"x = ky²/z: 6 = 16k/8 से k = 3, अतः x = 3 × 36/3 = 36। y² की जगह y लेने पर 24 आता है; z में बदलाव को नज़रअंदाज़ करने पर 13.5 आता है।","subtopic":"proportion-variation"},
  {"id":"quant-ratio-148","question":"The salaries of A and B are in the ratio 3 : 5. A gets a 40% raise and B a raise of ₹3,600, after which the ratio is 3 : 4. What is A's new salary?","options":["₹18,000","₹30,000","₹25,200","₹33,600"],"answer":2,"explanation":"4.2x/(5x + 3,600) = 3/4 gives 16.8x = 15x + 10,800, x = 6,000. A's old salary was ₹18,000 and the new one ₹25,200; ₹33,600 is B's new salary.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A और B के वेतन का अनुपात 3 : 5 है। A के वेतन में 40% की वृद्धि होती है और B को ₹3,600 की वृद्धि मिलती है, जिसके बाद अनुपात 3 : 4 हो जाता है। A का नया वेतन क्या है?","optionsHi":["₹18,000","₹30,000","₹25,200","₹33,600"],"explanationHi":"4.2x/(5x + 3,600) = 3/4 से 16.8x = 15x + 10,800, x = 6,000। A का पुराना वेतन ₹18,000 था और नया ₹25,200; ₹33,600 B का नया वेतन है।","subtopic":"income-expenses"},
  {"id":"quant-ratio-149","question":"₹2,460 is divided among A, B and C so that if ₹20, ₹30 and ₹10 are taken from their respective shares, the remainders are in the ratio 3 : 4 : 5. What is B's share?","options":["₹800","₹830","₹820","₹1,010"],"answer":1,"explanation":"The remainders total 2,460 − 60 = 2,400, so one part is 200; B's remainder is 800 and his share 800 + 30 = ₹830. Dividing 2,460 directly in 3 : 4 : 5 gives ₹820.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"₹2,460 को A, B और C में इस प्रकार बाँटा गया कि उनके हिस्सों में से क्रमशः ₹20, ₹30 और ₹10 घटाने पर शेष राशियाँ 3 : 4 : 5 के अनुपात में हैं। B का हिस्सा क्या है?","optionsHi":["₹800","₹830","₹820","₹1,010"],"explanationHi":"शेष राशियों का योग 2,460 − 60 = 2,400 है, इसलिए एक भाग 200 है; B की शेष राशि 800 है और उसका हिस्सा 800 + 30 = ₹830। 2,460 को सीधे 3 : 4 : 5 में बाँटने पर ₹820 आता है।","subtopic":"dividing-amounts"},
  {"id":"quant-ratio-150","question":"If (x + y) : (x − y) = 7 : 3, what is (x² + y²) : (x² − y²)?","options":["49 : 9","29 : 21","7 : 3","21 : 29"],"answer":1,"explanation":"Componendo-dividendo gives x : y = (7 + 3) : (7 − 3) = 5 : 2, so the ratio is (25 + 4) : (25 − 4) = 29 : 21. Squaring 7 : 3 to 49 : 9 is the trap.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि (x + y) : (x − y) = 7 : 3 है, तो (x² + y²) : (x² − y²) क्या है?","optionsHi":["49 : 9","29 : 21","7 : 3","21 : 29"],"explanationHi":"योगांतरानुपात (componendo-dividendo) से x : y = (7 + 3) : (7 − 3) = 5 : 2, अतः अनुपात (25 + 4) : (25 − 4) = 29 : 21। 7 : 3 का वर्ग करके 49 : 9 लेना जाल है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-151","question":"A and B invest ₹50,000 and ₹30,000. A, the working partner, first takes 20% of the profit as salary, and the rest is shared in the ratio of capitals. If A receives ₹18,000 more than B in all, what is the total profit?","options":["₹45,000","₹72,000","₹90,000","₹36,000"],"answer":0,"explanation":"A − B = 0.2P + 0.8P × (5 − 3)/8 = 0.4P = 18,000, so P = ₹45,000. Ignoring the salary gives 18,000 × 8/2 = ₹72,000.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A और B क्रमशः ₹50,000 और ₹30,000 लगाते हैं। कार्यकारी साझेदार A पहले लाभ का 20% वेतन के रूप में लेता है, और शेष लाभ पूँजी के अनुपात में बँटता है। यदि A को कुल मिलाकर B से ₹18,000 अधिक मिलते हैं, तो कुल लाभ क्या है?","optionsHi":["₹45,000","₹72,000","₹90,000","₹36,000"],"explanationHi":"A − B = 0.2P + 0.8P × (5 − 3)/8 = 0.4P = 18,000, अतः P = ₹45,000। वेतन को नज़रअंदाज़ करने पर 18,000 × 8/2 = ₹72,000 आता है।","subtopic":"partnership"},
  {"id":"quant-ratio-152","question":"Two numbers are in the ratio 3 : 5. If 9 is subtracted from each, the ratio becomes 12 : 23. What is the smaller number?","options":["55","24","46","33"],"answer":3,"explanation":"(3x − 9)/(5x − 9) = 12/23 gives 69x − 207 = 60x − 108, so x = 11 and the numbers are 33 and 55. 24 and 46 are the numbers after subtracting 9.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"दो संख्याओं का अनुपात 3 : 5 है। यदि प्रत्येक में से 9 घटा दिया जाए, तो अनुपात 12 : 23 हो जाता है। छोटी संख्या क्या है?","optionsHi":["55","24","46","33"],"explanationHi":"(3x − 9)/(5x − 9) = 12/23 से 69x − 207 = 60x − 108, अतः x = 11 और संख्याएँ 33 और 55 हैं। 24 और 46 वे संख्याएँ हैं जो 9 घटाने के बाद बचती हैं।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-153","question":"Three vessels of equal size are full of milk and water in the ratios 2 : 1, 3 : 2 and 4 : 3. Their contents are poured into one large vessel. What is the ratio of milk to water in it?","options":["3 : 2","193 : 315","122 : 193","193 : 122"],"answer":3,"explanation":"Milk = 2/3 + 3/5 + 4/7 = 193/105 and water = 1/3 + 2/5 + 3/7 = 122/105 of a vessel, so 193 : 122. Adding the ratio terms (9 : 6 = 3 : 2) wrongly treats the vessels as different sizes.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"समान आकार के तीन बर्तन दूध और पानी के क्रमशः 2 : 1, 3 : 2 और 4 : 3 के अनुपात वाले मिश्रण से भरे हैं। उनकी सामग्री को एक बड़े बर्तन में उँडेल दिया जाता है। उसमें दूध और पानी का अनुपात क्या है?","optionsHi":["3 : 2","193 : 315","122 : 193","193 : 122"],"explanationHi":"दूध = 2/3 + 3/5 + 4/7 = 193/105 और पानी = 1/3 + 2/5 + 3/7 = 122/105 बर्तन, अतः 193 : 122। अनुपात के पदों को जोड़ना (9 : 6 = 3 : 2) गलत है, क्योंकि इसमें बर्तनों को अलग-अलग आकार का मान लिया जाता है।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-154","question":"In a class the ratio of boys to girls is 7 : 5. When 8 more girls join, the ratio becomes 7 : 6. How many students were there originally?","options":["104","96","56","40"],"answer":1,"explanation":"7x : (5x + 8) = 7 : 6 gives 42x = 35x + 56, x = 8, so there were 56 boys and 40 girls: 96 students. 104 includes the girls who joined.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक कक्षा में लड़कों और लड़कियों का अनुपात 7 : 5 है। जब 8 लड़कियाँ और जुड़ जाती हैं, तो अनुपात 7 : 6 हो जाता है। मूल रूप से कितने विद्यार्थी थे?","optionsHi":["104","96","56","40"],"explanationHi":"7x : (5x + 8) = 7 : 6 से 42x = 35x + 56, x = 8, इसलिए 56 लड़के और 40 लड़कियाँ थीं: कुल 96 विद्यार्थी। 104 में जुड़ने वाली लड़कियाँ भी शामिल हैं।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-155","question":"The sum, the difference and the product of two positive numbers are in the ratio 7 : 1 : 60. What is the larger number?","options":["15","28","20","35"],"answer":2,"explanation":"Let sum = 7k and difference = k, so the numbers are 4k and 3k; their product 12k² = 60k gives k = 5, and the numbers are 20 and 15. 35 is their sum.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"दो धनात्मक संख्याओं का योग, अंतर और गुणनफल 7 : 1 : 60 के अनुपात में हैं। बड़ी संख्या क्या है?","optionsHi":["15","28","20","35"],"explanationHi":"माना योग = 7k और अंतर = k, तो संख्याएँ 4k और 3k हैं; उनका गुणनफल 12k² = 60k से k = 5, और संख्याएँ 20 और 15 हैं। 35 उनका योग है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-156","question":"On a train route the first-class and second-class fares are in the ratio 4 : 1, and the numbers of passengers in the ratio 1 : 30. If ₹2,380 was collected in all, how much came from first class?","options":["₹2,100","₹1,904","₹280","₹76.77"],"answer":2,"explanation":"Revenue ratio = (4 × 1) : (1 × 30) = 4 : 30, so first class gives 2,380 × 4/34 = ₹280. Using only the fare ratio gives ₹1,904; ₹2,100 is second class.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक रेल मार्ग पर प्रथम श्रेणी और द्वितीय श्रेणी के किराए का अनुपात 4 : 1 है, और यात्रियों की संख्या का अनुपात 1 : 30 है। यदि कुल ₹2,380 एकत्र हुए, तो प्रथम श्रेणी से कितना आया?","optionsHi":["₹2,100","₹1,904","₹280","₹76.77"],"explanationHi":"आय का अनुपात = (4 × 1) : (1 × 30) = 4 : 30, अतः प्रथम श्रेणी से 2,380 × 4/34 = ₹280 आया। केवल किराए के अनुपात से ₹1,904 आता है; ₹2,100 द्वितीय श्रेणी की आय है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-157","question":"If a/(b + c) = b/(c + a) = c/(a + b) = k, where a, b, c are non-zero real numbers, what are the possible values of k?","options":["1/2 only","−1 only","1/2 or −1","2 or −1"],"answer":2,"explanation":"Adding numerators and denominators gives k = (a + b + c)/2(a + b + c) = 1/2 when a + b + c ≠ 0. If a + b + c = 0, then b + c = −a and k = −1. Forgetting the second case gives '1/2 only'.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"यदि a/(b + c) = b/(c + a) = c/(a + b) = k है, जहाँ a, b, c शून्येतर वास्तविक संख्याएँ हैं, तो k के संभावित मान क्या हैं?","optionsHi":["केवल 1/2","केवल −1","1/2 या −1","2 या −1"],"explanationHi":"अंशों और हरों को जोड़ने पर, जब a + b + c ≠ 0 हो, k = (a + b + c)/2(a + b + c) = 1/2। यदि a + b + c = 0 हो, तो b + c = −a और k = −1। दूसरी स्थिति भूल जाने पर 'केवल 1/2' आता है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-158","question":"60 litres of a mixture contain acid and water in the ratio 2 : 1. How much of the mixture must be drawn off and replaced with water so that the mixture becomes half acid and half water?","options":["20 L","10 L","15 L","30 L"],"answer":2,"explanation":"Acid must fall from 40 L to 30 L; each litre drawn removes 2/3 L of acid, so x = 10 ÷ (2/3) = 15 L. 20 L is the water you would add without drawing anything off; 10 L confuses acid removed with mixture removed.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"60 लीटर के एक मिश्रण में अम्ल और पानी 2 : 1 के अनुपात में हैं। मिश्रण में से कितना निकालकर उसकी जगह पानी डालना होगा ताकि मिश्रण आधा अम्ल और आधा पानी हो जाए?","optionsHi":["20 L","10 L","15 L","30 L"],"explanationHi":"अम्ल 40 L से घटकर 30 L होना चाहिए; निकाले गए प्रत्येक लीटर में 2/3 L अम्ल होता है, अतः x = 10 ÷ (2/3) = 15 L। 20 L वह पानी है जो बिना कुछ निकाले मिलाना पड़ता; 10 L में निकाले गए अम्ल को निकाले गए मिश्रण के बराबर मान लिया गया है।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-159","question":"What is the ratio compounded of 2 : 3, the duplicate ratio of 3 : 4 and the sub-duplicate ratio of 64 : 9?","options":["2 : 1","1 : 1","3 : 4","4 : 3"],"answer":1,"explanation":"Duplicate of 3 : 4 is 9 : 16; sub-duplicate of 64 : 9 is 8 : 3. (2/3)(9/16)(8/3) = 144/144 = 1, so the ratio is 1 : 1.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"2 : 3, 3 : 4 के द्विकृत अनुपात और 64 : 9 के उपद्विकृत अनुपात का संयुक्त अनुपात क्या है?","optionsHi":["2 : 1","1 : 1","3 : 4","4 : 3"],"explanationHi":"3 : 4 का द्विकृत अनुपात 9 : 16 है; 64 : 9 का उपद्विकृत अनुपात 8 : 3 है। (2/3)(9/16)(8/3) = 144/144 = 1, अतः अनुपात 1 : 1।","subtopic":"proportion-variation"},
  {"id":"quant-ratio-160","question":"In a school the ratio of boys to girls is 9 : 7. 20% of the boys and 25% of the girls hold scholarships. What percentage of the students do not hold a scholarship?","options":["77.81%","77.5%","22.19%","77.19%"],"answer":0,"explanation":"Non-holders: 9 × 0.8 + 7 × 0.75 = 12.45 out of 16, i.e. 77.81%. A plain average of 80% and 75% gives 77.5%, and swapping the weights gives 77.19%.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक विद्यालय में लड़कों और लड़कियों का अनुपात 9 : 7 है। 20% लड़कों और 25% लड़कियों को छात्रवृत्ति मिली है। कितने प्रतिशत विद्यार्थियों को छात्रवृत्ति नहीं मिली?","optionsHi":["77.81%","77.5%","22.19%","77.19%"],"explanationHi":"छात्रवृत्ति न पाने वाले: 9 × 0.8 + 7 × 0.75 = 12.45, कुल 16 में से, यानी 77.81%। 80% और 75% का साधारण औसत लेने पर 77.5% आता है, और भार आपस में बदलने पर 77.19%।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-161","question":"Vessel A holds milk and water in the ratio 4 : 1 and vessel B in the ratio 1 : 2. How many litres must be taken from B, along with some from A, to fill a 14-litre can with milk and water in equal amounts?","options":["5 L","7 L","9 L","12 L"],"answer":2,"explanation":"Milk fractions are 4/5 and 1/3, target 1/2: A : B = (1/2 − 1/3) : (4/5 − 1/2) = 1/6 : 3/10 = 5 : 9, so 9 L from B. 5 L is the amount from A; applying alligation to the ratios 4 and 1/2 instead of fractions gives 12 L.","difficulty":"very-hard","source":"CAT · SBI PO Mains","questionHi":"बर्तन A में दूध और पानी का अनुपात 4 : 1 है और बर्तन B में 1 : 2। 14 लीटर के एक कैन को बराबर मात्रा में दूध और पानी से भरने के लिए, A से कुछ मात्रा के साथ B से कितने लीटर लेने होंगे?","optionsHi":["5 L","7 L","9 L","12 L"],"explanationHi":"दूध के भिन्न 4/5 और 1/3 हैं, अभीष्ट 1/2: A : B = (1/2 − 1/3) : (4/5 − 1/2) = 1/6 : 3/10 = 5 : 9, अतः B से 9 L। 5 L A से ली जाने वाली मात्रा है; भिन्नों की जगह अनुपात 4 और 1/2 पर एलिगेशन लगाने से 12 L आता है।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-162","question":"A and B invest capitals in the ratio 3 : 5 and share profits in the ratio 9 : 10. If B's money was invested for 6 months, for how long was A's money invested?","options":["9 months","4 months","10.8 months","6 months"],"answer":0,"explanation":"3t : (5 × 6) = 9 : 10 gives 30t = 270, t = 9 months. Attaching the 6 months to A's capital instead gives 4 months.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"A और B की पूँजी का अनुपात 3 : 5 है और वे लाभ 9 : 10 के अनुपात में बाँटते हैं। यदि B का धन 6 महीने के लिए लगाया गया था, तो A का धन कितने महीने के लिए लगाया गया था?","optionsHi":["9 महीने","4 महीने","10.8 महीने","6 महीने"],"explanationHi":"3t : (5 × 6) = 9 : 10 से 30t = 270, t = 9 महीने। 6 महीने को A की पूँजी के साथ जोड़ देने पर 4 महीने आता है।","subtopic":"partnership"},
  {"id":"quant-ratio-163","question":"A box holds ₹5, ₹10 and ₹20 notes in the ratio 1/2 : 1/3 : 1/4, worth ₹3,900 in all. How many notes are there?","options":["180","120","90","390"],"answer":3,"explanation":"1/2 : 1/3 : 1/4 = 6 : 4 : 3, and one such set is worth 30 + 40 + 60 = ₹130, so there are 30 sets and 13 × 30 = 390 notes. 180, 120 and 90 are the counts of single denominations.","difficulty":"very-hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक बक्से में ₹5, ₹10 और ₹20 के नोट 1/2 : 1/3 : 1/4 के अनुपात में हैं, जिनका कुल मूल्य ₹3,900 है। कुल कितने नोट हैं?","optionsHi":["180","120","90","390"],"explanationHi":"1/2 : 1/3 : 1/4 = 6 : 4 : 3, और ऐसे एक समूह का मूल्य 30 + 40 + 60 = ₹130 है, इसलिए 30 समूह हैं और नोट 13 × 30 = 390 हैं। 180, 120 और 90 अलग-अलग मूल्यवर्ग के नोटों की संख्याएँ हैं।","subtopic":"coins"},
  {"id":"quant-ratio-164","question":"A sum is divided among A, B and C in the ratio 1/3 : 1/4 : 1/6. If C receives ₹1,800, what is the total sum?","options":["₹8,100","₹3,900","₹10,800","₹4,050"],"answer":0,"explanation":"Multiplying by 12, the ratio is 4 : 3 : 2, so C's 2 parts = 1,800, one part = 900 and the total = 9 × 900 = ₹8,100. Inverting the fractions to 3 : 4 : 6 gives ₹3,900; treating C's ₹1,800 as one-sixth of the total gives ₹10,800.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"एक राशि को A, B और C में 1/3 : 1/4 : 1/6 के अनुपात में बाँटा गया है। यदि C को ₹1,800 मिलते हैं, तो कुल राशि क्या है?","optionsHi":["₹8,100","₹3,900","₹10,800","₹4,050"],"explanationHi":"12 से गुणा करने पर अनुपात 4 : 3 : 2 है, इसलिए C के 2 भाग = 1,800, एक भाग = 900 और कुल = 9 × 900 = ₹8,100। भिन्नों को उलटकर 3 : 4 : 6 लेने पर ₹3,900 आता है; C के ₹1,800 को कुल का छठा भाग मानने पर ₹10,800 आता है।","subtopic":"dividing-amounts"},
  {"id":"quant-ratio-165","question":"Alloy X contains copper, zinc and tin in the ratio 5 : 3 : 2, and alloy Y contains them in the ratio 2 : 5 : 3. If 10 kg of X is melted with 15 kg of Y, what is the ratio of copper, zinc and tin in the new alloy?","options":["7 : 8 : 5","16 : 21 : 13","5 : 3 : 2","13 : 21 : 16"],"answer":1,"explanation":"X gives 5, 3, 2 kg and Y gives 3, 7.5, 4.5 kg, so the new alloy has 8 : 10.5 : 6.5 = 16 : 21 : 13. Adding the ratio terms (7 : 8 : 5) ignores that the two alloys are used in different amounts.","difficulty":"hard","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"मिश्रधातु X में ताँबा, जस्ता और राँगा 5 : 3 : 2 के अनुपात में हैं, और मिश्रधातु Y में 2 : 5 : 3 के अनुपात में। यदि X के 10 kg को Y के 15 kg के साथ पिघलाया जाए, तो नई मिश्रधातु में ताँबे, जस्ते और राँगे का अनुपात क्या होगा?","optionsHi":["7 : 8 : 5","16 : 21 : 13","5 : 3 : 2","13 : 21 : 16"],"explanationHi":"X से 5, 3, 2 kg मिलते हैं और Y से 3, 7.5, 4.5 kg, इसलिए नई मिश्रधातु में 8 : 10.5 : 6.5 = 16 : 21 : 13। अनुपात के पदों को जोड़ना (7 : 8 : 5) इस बात को नज़रअंदाज़ करता है कि दोनों मिश्रधातुएँ अलग-अलग मात्रा में ली गई हैं।","subtopic":"mixtures-alligation"},
  {"id":"quant-ratio-166","question":"If A : B = 3 : 4, B : C = 6 : 5 and C : D = 10 : 9, what is A : B : C : D?","options":["9 : 12 : 10 : 9","3 : 4 : 5 : 9","18 : 24 : 20 : 9","9 : 12 : 10 : 18"],"answer":0,"explanation":"Make B equal (12) and then C equal (10): A : B : C = 9 : 12 : 10, and C : D = 10 : 9, so A : B : C : D = 9 : 12 : 10 : 9. Writing the given numbers side by side (3 : 4 : 5 : 9) skips the linking.","difficulty":"moderate","source":"SSC CGL Tier 2 · IBPS PO Mains","questionHi":"यदि A : B = 3 : 4, B : C = 6 : 5 और C : D = 10 : 9 है, तो A : B : C : D क्या है?","optionsHi":["9 : 12 : 10 : 9","3 : 4 : 5 : 9","18 : 24 : 20 : 9","9 : 12 : 10 : 18"],"explanationHi":"पहले B को बराबर करें (12) और फिर C को (10): A : B : C = 9 : 12 : 10, और C : D = 10 : 9, अतः A : B : C : D = 9 : 12 : 10 : 9। दिए गए अंकों को बस साथ-साथ लिख देना (3 : 4 : 5 : 9) कड़ियाँ जोड़ना छोड़ देता है।","subtopic":"ratio-basics"},
  {"id":"quant-ratio-167","question":"A purse holds only ₹2 and ₹5 coins whose numbers are in the ratio 7 : 3. The total amount is ₹1,160. How many ₹5 coins are there?","options":["348","280","120","232"],"answer":2,"explanation":"Coins 7k and 3k are worth 14k + 15k = 29k = 1,160, so k = 40 and the ₹5 coins number 3k = 120. 280 is the count of ₹2 coins.","difficulty":"hard","questionHi":"एक पर्स में केवल ₹2 और ₹5 के सिक्के हैं, जिनकी संख्याओं का अनुपात 7 : 3 है। कुल राशि ₹1,160 है। ₹5 के सिक्कों की संख्या कितनी है?","optionsHi":["348","280","120","232"],"explanationHi":"7k और 3k सिक्कों का मूल्य 14k + 15k = 29k = 1,160, अतः k = 40 और ₹5 के सिक्के 3k = 120 हैं। 280 ₹2 के सिक्कों की संख्या है।","subtopic":"coins","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-168","question":"A box has ₹5 and ₹10 coins in the ratio 3 : 2 by number, worth ₹2,100 in all. Twenty ₹10 coins are taken out and replaced by ₹5 coins of the same total value. What is the new ratio of the number of ₹5 coins to ₹10 coins?","options":["11 : 5","2 : 1","9 : 5","11 : 6"],"answer":0,"explanation":"15k + 20k = 2,100 gives k = 60: 180 fives and 120 tens. Twenty tens (₹200) become 40 fives, so the coins are 220 fives and 100 tens = 11 : 5. Swapping coin for coin would give 2 : 1.","difficulty":"very-hard","questionHi":"एक डिब्बे में ₹5 और ₹10 के सिक्के संख्या में 3 : 2 के अनुपात में हैं और उनका कुल मूल्य ₹2,100 है। ₹10 के बीस सिक्के निकालकर उनके स्थान पर उतने ही कुल मूल्य के ₹5 के सिक्के रख दिए जाते हैं। ₹5 के सिक्कों और ₹10 के सिक्कों की संख्या का नया अनुपात क्या है?","optionsHi":["11 : 5","2 : 1","9 : 5","11 : 6"],"explanationHi":"15k + 20k = 2,100 से k = 60: 180 सिक्के ₹5 के और 120 सिक्के ₹10 के। बीस ₹10 के सिक्के (₹200) की जगह 40 सिक्के ₹5 के आते हैं, इसलिए 220 और 100 सिक्के = 11 : 5। सिक्के के बदले सिक्का रखने पर 2 : 1 आता, जो गलत है.","subtopic":"coins","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-169","question":"The numbers of ₹1, ₹2 and ₹5 coins in a bag are in the ratio 7 : 4 : 3. The amount in ₹5 coins exceeds the amount in ₹1 coins by ₹360. What is the total amount in the bag?","options":["₹1,170","₹630","₹1,215","₹1,350"],"answer":3,"explanation":"Amounts are 7k, 8k and 15k, so 15k − 7k = 360 gives k = 45 and the total is 30k = ₹1,350. Treating ₹2 coins as 4k gives 1,170, and 630 is just the number of coins.","difficulty":"hard","questionHi":"एक थैले में ₹1, ₹2 और ₹5 के सिक्कों की संख्याओं का अनुपात 7 : 4 : 3 है। ₹5 के सिक्कों की राशि ₹1 के सिक्कों की राशि से ₹360 अधिक है। थैले में कुल राशि कितनी है?","optionsHi":["₹1,170","₹630","₹1,215","₹1,350"],"explanationHi":"राशियाँ 7k, 8k और 15k हैं, अतः 15k − 7k = 360 से k = 45 और कुल राशि 30k = ₹1,350। ₹2 के सिक्कों को 4k लेने पर 1,170 आता है और 630 केवल सिक्कों की संख्या है.","subtopic":"coins","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-170","question":"A box has ₹2, ₹5 and ₹10 coins worth ₹2,150 in all. The ₹10 coins are 2/3 as many as the ₹5 coins, and the ₹5 coins are 3/4 as many as the ₹2 coins. How many ₹10 coins are there?","options":["150","100","200","86"],"answer":1,"explanation":"Counts of ₹2, ₹5, ₹10 coins are 4m, 3m, 2m, worth 8m + 15m + 20m = 43m = 2,150, so m = 50 and the ₹10 coins number 2m = 100.","difficulty":"very-hard","questionHi":"एक डिब्बे में ₹2, ₹5 और ₹10 के सिक्के हैं जिनका कुल मूल्य ₹2,150 है। ₹10 के सिक्के ₹5 के सिक्कों के 2/3 हैं और ₹5 के सिक्के ₹2 के सिक्कों के 3/4 हैं। ₹10 के सिक्के कितने हैं?","optionsHi":["150","100","200","86"],"explanationHi":"₹2, ₹5, ₹10 के सिक्कों की संख्याएँ 4m, 3m, 2m हैं, जिनका मूल्य 8m + 15m + 20m = 43m = 2,150 है। अतः m = 50 और ₹10 के सिक्के 2m = 100 हैं।","subtopic":"coins","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-171","question":"A bag holds ₹1, 50-paise and 25-paise coins, 560 in all, and the amount in each kind of coin is the same. What is the total amount in the bag?","options":["₹420","₹240","₹280","₹320"],"answer":1,"explanation":"Equal amounts mean the numbers are in the ratio 1 : 2 : 4, so there are 80, 160 and 320 coins, and each kind is worth ₹80, giving ₹240. Reversing the ratio to 4 : 2 : 1 gives ₹420.","difficulty":"hard","questionHi":"एक थैले में ₹1, 50 पैसे और 25 पैसे के कुल 560 सिक्के हैं और प्रत्येक प्रकार के सिक्कों की राशि समान है। थैले में कुल राशि कितनी है?","optionsHi":["₹420","₹240","₹280","₹320"],"explanationHi":"समान राशि होने पर सिक्कों की संख्याएँ 1 : 2 : 4 के अनुपात में होंगी, अर्थात 80, 160 और 320 सिक्के, और प्रत्येक प्रकार की राशि ₹80 होगी, इसलिए कुल ₹240। अनुपात को उलटकर 4 : 2 : 1 लेने पर ₹420 आता है.","subtopic":"coins","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-172","question":"A purse has ₹1 and ₹2 coins whose total values are in the ratio 5 : 6. If 15 more ₹1 coins are added and 5 ₹2 coins are removed, the two amounts become equal. How many coins were in the purse at first?","options":["160","240","120","200"],"answer":3,"explanation":"Values are 5k and 6k: 5k + 15 = 6k − 10 (five ₹2 coins are ₹10), so k = 25. Then there are 125 one-rupee and 75 two-rupee coins, 200 in all.","difficulty":"hard","questionHi":"एक पर्स में ₹1 और ₹2 के सिक्कों के कुल मूल्यों का अनुपात 5 : 6 है। यदि ₹1 के 15 सिक्के और डाल दिए जाएँ तथा ₹2 के 5 सिक्के निकाल लिए जाएँ, तो दोनों राशियाँ बराबर हो जाती हैं। पर्स में शुरू में कुल कितने सिक्के थे?","optionsHi":["160","240","120","200"],"explanationHi":"मूल्य 5k और 6k हैं: 5k + 15 = 6k − 10 (₹2 के पाँच सिक्के ₹10 के बराबर), अतः k = 25। तब ₹1 के 125 और ₹2 के 75 सिक्के हैं, कुल 200।","subtopic":"coins","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-173","question":"A family's income and expenditure are in the ratio 9 : 7. When the income rises by 20% and the expenditure by 10%, the savings go up by ₹3,300. What was the original income?","options":["₹27,000","₹21,000","₹32,400","₹23,100"],"answer":0,"explanation":"Take income 9k, expenditure 7k. New savings are 10.8k − 7.7k = 3.1k against 2k before, so 1.1k = 3,300 and k = 3,000, giving income ₹27,000. The other options are expenditure, new income and new expenditure.","difficulty":"hard","questionHi":"एक परिवार की आय और व्यय का अनुपात 9 : 7 है। आय में 20% और व्यय में 10% की वृद्धि होने पर बचत ₹3,300 बढ़ जाती है। मूल आय कितनी थी?","optionsHi":["₹27,000","₹21,000","₹32,400","₹23,100"],"explanationHi":"आय 9k और व्यय 7k लें। नई बचत 10.8k − 7.7k = 3.1k है जबकि पहले 2k थी, अतः 1.1k = 3,300 और k = 3,000, इसलिए आय ₹27,000। अन्य विकल्प क्रमशः व्यय, नई आय और नया व्यय हैं।","subtopic":"income-expenses","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-174","question":"The incomes of A and B are in the ratio 5 : 4. A saves 20% of his income and B saves 25% of his. What is the ratio of their expenditures?","options":["16 : 15","1 : 1","4 : 3","3 : 2"],"answer":2,"explanation":"Expenditure is 80% of 5 = 4 for A and 75% of 4 = 3 for B, so 4 : 3. Their savings (1 and 1) are in the ratio 1 : 1, which is a different question.","difficulty":"moderate","questionHi":"A और B की आय का अनुपात 5 : 4 है। A अपनी आय का 20% और B अपनी आय का 25% बचाता है। उनके व्यय का अनुपात क्या है?","optionsHi":["16 : 15","1 : 1","4 : 3","3 : 2"],"explanationHi":"A का व्यय 5 का 80% = 4 और B का व्यय 4 का 75% = 3 है, अतः अनुपात 4 : 3। उनकी बचत (1 और 1) का अनुपात 1 : 1 है, जो अलग प्रश्न का उत्तर है।","subtopic":"income-expenses","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-175","question":"The incomes and expenditures of a person are in the ratio 5 : 4. If both are increased by ₹2,000, the ratio becomes 11 : 9. What is the person's saving?","options":["₹2,000","₹16,000","₹4,000","₹20,000"],"answer":2,"explanation":"(5k + 2,000)/(4k + 2,000) = 11/9 gives 45k + 18,000 = 44k + 22,000, so k = 4,000. Saving = 5k − 4k = k = ₹4,000 (income is 20,000 and expenditure 16,000).","difficulty":"very-hard","questionHi":"एक व्यक्ति की आय और व्यय का अनुपात 5 : 4 है। यदि दोनों में ₹2,000 की वृद्धि कर दी जाए, तो अनुपात 11 : 9 हो जाता है। उस व्यक्ति की बचत कितनी है?","optionsHi":["₹2,000","₹16,000","₹4,000","₹20,000"],"explanationHi":"(5k + 2,000)/(4k + 2,000) = 11/9 से 45k + 18,000 = 44k + 22,000, अतः k = 4,000। बचत = 5k − 4k = k = ₹4,000 (आय 20,000 और व्यय 16,000 है)।","subtopic":"income-expenses","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-176","question":"The incomes of A, B and C are in the ratio 4 : 5 : 6 and their expenditures are in the ratio 3 : 4 : 5. If each of them saves ₹3,500, what is their total income?","options":["₹52,500","₹42,000","₹10,500","₹49,000"],"answer":0,"explanation":"With incomes 4a, 5a, 6a and expenditures 3b, 4b, 5b, equal savings force 4a − 3b = 5a − 4b, so a = b and each saving equals a = 3,500. Total income = 15a = ₹52,500.","difficulty":"hard","questionHi":"A, B और C की आय का अनुपात 4 : 5 : 6 है और उनके व्यय का अनुपात 3 : 4 : 5 है। यदि प्रत्येक ₹3,500 की बचत करता है, तो उनकी कुल आय कितनी है?","optionsHi":["₹52,500","₹42,000","₹10,500","₹49,000"],"explanationHi":"आय 4a, 5a, 6a और व्यय 3b, 4b, 5b लेने पर बराबर बचत से 4a − 3b = 5a − 4b, अतः a = b और प्रत्येक की बचत a = 3,500। कुल आय = 15a = ₹52,500।","subtopic":"income-expenses","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-177","question":"A family spends on food, rent and other items in the ratio 5 : 3 : 2. If the cost of food rises by 20%, rent by 10% and other items do not change, by what percent does the total expenditure rise?","options":["15%","11.3%","14.5%","13%"],"answer":3,"explanation":"Out of 10 units, the new spend is 6 + 3.3 + 2 = 11.3, a rise of 1.3 on 10, which is 13%. Averaging 20% and 10% gives the wrong 15%.","difficulty":"hard","questionHi":"एक परिवार भोजन, किराए और अन्य मदों पर 5 : 3 : 2 के अनुपात में खर्च करता है। यदि भोजन का खर्च 20% बढ़ जाए, किराया 10% बढ़ जाए और अन्य मदों का खर्च न बदले, तो कुल व्यय में कितने प्रतिशत की वृद्धि होगी?","optionsHi":["15%","11.3%","14.5%","13%"],"explanationHi":"10 इकाइयों में नया खर्च 6 + 3.3 + 2 = 11.3 है, यानी 10 पर 1.3 की वृद्धि = 13%। 20% और 10% का साधारण औसत लेने पर गलत 15% आता है।","subtopic":"income-expenses","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-178","question":"The salaries of A and B are in the ratio 5 : 7. A gets a 10% rise and B gets a rise of ₹1,200, after which the ratio of their salaries is 10 : 13. What was A's original salary?","options":["₹56,000","₹40,000","₹44,000","₹32,000"],"answer":1,"explanation":"5.5k / (7k + 1,200) = 10/13 gives 71.5k = 70k + 12,000, so k = 8,000 and A earned 5k = ₹40,000. B earned 56,000, and 44,000 is A's new salary.","difficulty":"very-hard","questionHi":"A और B के वेतन का अनुपात 5 : 7 है। A के वेतन में 10% की वृद्धि और B के वेतन में ₹1,200 की वृद्धि होने के बाद उनके वेतन का अनुपात 10 : 13 हो जाता है। A का मूल वेतन कितना था?","optionsHi":["₹56,000","₹40,000","₹44,000","₹32,000"],"explanationHi":"5.5k / (7k + 1,200) = 10/13 से 71.5k = 70k + 12,000, अतः k = 8,000 और A का वेतन 5k = ₹40,000। B का वेतन 56,000 था और 44,000 A का नया वेतन है।","subtopic":"income-expenses","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-179","question":"The present ages of A, B and C are in the ratio 4 : 5 : 7. Eight years ago the sum of the ages of A and C was 4 years more than twice the age of B. What is C's present age?","options":["20 years","28 years","35 years","24 years"],"answer":1,"explanation":"(4k − 8) + (7k − 8) = 2(5k − 8) + 4 gives 11k − 16 = 10k − 12, so k = 4 and C = 7k = 28 years. 20 is B's age.","difficulty":"very-hard","questionHi":"A, B और C की वर्तमान आयु का अनुपात 4 : 5 : 7 है। आठ वर्ष पहले A और C की आयु का योग B की आयु के दोगुने से 4 वर्ष अधिक था। C की वर्तमान आयु कितनी है?","optionsHi":["20 वर्ष","28 वर्ष","35 वर्ष","24 वर्ष"],"explanationHi":"(4k − 8) + (7k − 8) = 2(5k − 8) + 4 से 11k − 16 = 10k − 12, अतः k = 4 और C = 7k = 28 वर्ष। 20 B की आयु है।","subtopic":"ages","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-180","question":"The ages of two brothers are in the ratio 3 : 5. Ten years from now the ratio will be 5 : 7. What is the ratio of their ages 5 years ago?","options":["2 : 3","3 : 5","4 : 7","1 : 2"],"answer":3,"explanation":"(3k + 10)/(5k + 10) = 5/7 gives 21k + 70 = 25k + 50, so k = 5 and their ages are 15 and 25. Five years ago they were 10 and 20, i.e. 1 : 2.","difficulty":"moderate","questionHi":"दो भाइयों की आयु का अनुपात 3 : 5 है। दस वर्ष बाद यह अनुपात 5 : 7 हो जाएगा। 5 वर्ष पहले उनकी आयु का अनुपात क्या था?","optionsHi":["2 : 3","3 : 5","4 : 7","1 : 2"],"explanationHi":"(3k + 10)/(5k + 10) = 5/7 से 21k + 70 = 25k + 50, अतः k = 5 और उनकी आयु 15 और 25 वर्ष है। पाँच वर्ष पहले वे 10 और 20 वर्ष के थे, अर्थात 1 : 2।","subtopic":"ages","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-181","question":"A : B = 3 : 4 and B : C = 5 : 6 in present ages, and the sum of the ages of A and C is 57 years more than B's age. What is the ratio of A's age 9 years from now to C's age 9 years ago?","options":["6 : 7","5 : 8","9 : 11","4 : 5"],"answer":0,"explanation":"A : B : C = 15 : 20 : 24, and 15k + 24k − 20k = 19k = 57 gives k = 3, so A = 45, B = 60, C = 72. Then (45 + 9) : (72 − 9) = 54 : 63 = 6 : 7.","difficulty":"very-hard","questionHi":"वर्तमान आयु में A : B = 3 : 4 और B : C = 5 : 6 है तथा A और C की आयु का योग B की आयु से 57 वर्ष अधिक है। अब से 9 वर्ष बाद की A की आयु और 9 वर्ष पहले की C की आयु का अनुपात क्या है?","optionsHi":["6 : 7","5 : 8","9 : 11","4 : 5"],"explanationHi":"A : B : C = 15 : 20 : 24 और 15k + 24k − 20k = 19k = 57 से k = 3, अतः A = 45, B = 60, C = 72। तब (45 + 9) : (72 − 9) = 54 : 63 = 6 : 7।","subtopic":"ages","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-182","question":"The ages of a father and his son are in the ratio 4 : 1. Five years ago the product of their ages was 175. What is the father's present age?","options":["36 years","44 years","40 years","48 years"],"answer":2,"explanation":"(4k − 5)(k − 5) = 175 gives 4k² − 25k − 150 = 0, so k = 10 (the other root is negative). The father is 4k = 40 years old.","difficulty":"hard","questionHi":"एक पिता और उसके पुत्र की आयु का अनुपात 4 : 1 है। पाँच वर्ष पहले उनकी आयु का गुणनफल 175 था। पिता की वर्तमान आयु कितनी है?","optionsHi":["36 वर्ष","44 वर्ष","40 वर्ष","48 वर्ष"],"explanationHi":"(4k − 5)(k − 5) = 175 से 4k² − 25k − 150 = 0, अतः k = 10 (दूसरा मूल ऋणात्मक है)। पिता की आयु 4k = 40 वर्ष है।","subtopic":"ages","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-183","question":"The present ages of a father and his son are in the ratio 7 : 3, and the father is 28 years older than the son. What will be the ratio of their ages after 12 years?","options":["7 : 3","19 : 9","61 : 33","5 : 2"],"answer":2,"explanation":"4k = 28 gives k = 7, so the ages are 49 and 21. After 12 years they are 61 and 33, a ratio of 61 : 33, which cannot be simplified.","difficulty":"moderate","questionHi":"एक पिता और उसके पुत्र की वर्तमान आयु का अनुपात 7 : 3 है और पिता पुत्र से 28 वर्ष बड़ा है। 12 वर्ष बाद उनकी आयु का अनुपात क्या होगा?","optionsHi":["7 : 3","19 : 9","61 : 33","5 : 2"],"explanationHi":"4k = 28 से k = 7, अतः आयु 49 और 21 वर्ष है। 12 वर्ष बाद वे 61 और 33 वर्ष के होंगे, अतः अनुपात 61 : 33, जो और सरल नहीं होता।","subtopic":"ages","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-184","question":"The average of the present ages of A and B is 25 years. Five years ago the ratio of their ages was 7 : 3. What is A's present age?","options":["33 years","28 years","35 years","37 years"],"answer":0,"explanation":"A + B = 50. Let A − 5 = 7t and B − 5 = 3t, so 10t = 50 − 10 = 40, t = 4 and A = 5 + 28 = 33. The option 28 is A's age five years ago.","difficulty":"hard","questionHi":"A और B की वर्तमान आयु का औसत 25 वर्ष है। पाँच वर्ष पहले उनकी आयु का अनुपात 7 : 3 था। A की वर्तमान आयु कितनी है?","optionsHi":["33 वर्ष","28 वर्ष","35 वर्ष","37 वर्ष"],"explanationHi":"A + B = 50। A − 5 = 7t और B − 5 = 3t लेने पर 10t = 40, t = 4 और A = 33। 28 पाँच वर्ष पहले की A की आयु है।","subtopic":"ages","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-185","question":"₹7,770 is divided among A, B and C. A gets 25% more than B, and B gets 20% more than C. What is A's share?","options":["₹2,520","₹3,360","₹2,940","₹3,150"],"answer":3,"explanation":"B = 1.2C and A = 1.25B = 1.5C, so A : B : C = 15 : 12 : 10 (37 parts). One part = 7,770/37 = 210, so A gets 15 × 210 = ₹3,150.","difficulty":"hard","questionHi":"₹7,770 को A, B और C में बाँटा जाता है। A को B से 25% अधिक और B को C से 20% अधिक मिलता है। A का हिस्सा कितना है?","optionsHi":["₹2,520","₹3,360","₹2,940","₹3,150"],"explanationHi":"B = 1.2C और A = 1.25B = 1.5C, अतः A : B : C = 15 : 12 : 10 (कुल 37 भाग)। एक भाग = 7,770/37 = 210, इसलिए A को 15 × 210 = ₹3,150 मिलते हैं।","subtopic":"dividing-amounts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-186","question":"₹8,400 is divided among A, B and C in the ratio 2 : 3 : 7. Had it been divided in the ratio 3 : 4 : 5 instead, how would C's share change?","options":["Increase of ₹1,400","Decrease of ₹1,400","Decrease of ₹700","Decrease of ₹2,100"],"answer":1,"explanation":"First split: C gets 7 × 700 = ₹4,900. Second split: C gets 5 × 700 = ₹3,500. So C's share falls by ₹1,400.","difficulty":"moderate","questionHi":"₹8,400 को A, B और C में 2 : 3 : 7 के अनुपात में बाँटा गया। यदि इसे 3 : 4 : 5 के अनुपात में बाँटा जाता, तो C के हिस्से में क्या परिवर्तन होता?","optionsHi":["₹1,400 की वृद्धि","₹1,400 की कमी","₹700 की कमी","₹2,100 की कमी"],"explanationHi":"पहले बँटवारे में C को 7 × 700 = ₹4,900 मिलते हैं। दूसरे में 5 × 700 = ₹3,500। अतः C का हिस्सा ₹1,400 कम हो जाता है।","subtopic":"dividing-amounts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-187","question":"A sum is divided among A, B and C. A takes 2/5 of it, B takes 2/7 of what remains, and C gets the rest, which is ₹1,500. What is B's share?","options":["₹1,000","₹600","₹1,400","₹800"],"answer":1,"explanation":"After A, 3/5 remains; B takes 2/7 of it = 6/35, so C has 1 − 14/35 − 6/35 = 15/35 = 3/7 of the total. 3/7 of T = 1,500 gives T = 3,500, and B gets 6/35 × 3,500 = ₹600.","difficulty":"hard","questionHi":"एक राशि A, B और C में बाँटी जाती है। A उसका 2/5 लेता है, B शेष का 2/7 लेता है और C को शेष ₹1,500 मिलते हैं। B का हिस्सा कितना है?","optionsHi":["₹1,000","₹600","₹1,400","₹800"],"explanationHi":"A के बाद 3/5 बचता है; B उसका 2/7 = 6/35 लेता है, अतः C के पास कुल का 1 − 14/35 − 6/35 = 15/35 = 3/7 है। T का 3/7 = 1,500 से T = 3,500 और B का हिस्सा 6/35 × 3,500 = ₹600।","subtopic":"dividing-amounts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-188","question":"₹3,720 is divided among A, B and C in a ratio inversely proportional to their ages, which are 12, 15 and 20 years. What is B's share?","options":["₹1,550","₹930","₹1,116","₹1,240"],"answer":3,"explanation":"Shares are proportional to 1/12 : 1/15 : 1/20 = 5 : 4 : 3 (12 parts). One part = 3,720/12 = 310, so B gets 4 × 310 = ₹1,240. ₹1,550 is A's share and ₹930 is C's.","difficulty":"very-hard","questionHi":"₹3,720 को A, B और C में उनकी आयु 12, 15 और 20 वर्ष के व्युत्क्रमानुपात में बाँटा जाता है। B का हिस्सा कितना है?","optionsHi":["₹1,550","₹930","₹1,116","₹1,240"],"explanationHi":"हिस्से 1/12 : 1/15 : 1/20 = 5 : 4 : 3 (कुल 12 भाग) के अनुपात में होंगे। एक भाग = 3,720/12 = 310, इसलिए B को 4 × 310 = ₹1,240 मिलते हैं। ₹1,550 A का और ₹930 C का हिस्सा है।","subtopic":"dividing-amounts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-189","question":"₹7,200 is divided among three brothers. The eldest gets twice as much as the youngest, and the middle one gets 3/4 of the eldest's share. What does the middle brother get?","options":["₹2,400","₹3,200","₹1,600","₹2,700"],"answer":0,"explanation":"Let the youngest get y; the eldest gets 2y and the middle 1.5y, so 4.5y = 7,200 and y = 1,600. The middle brother gets 1.5 × 1,600 = ₹2,400.","difficulty":"moderate","questionHi":"₹7,200 को तीन भाइयों में बाँटा जाता है। सबसे बड़े को सबसे छोटे से दोगुना मिलता है और बीच वाले को सबसे बड़े के हिस्से का 3/4 मिलता है। बीच वाले भाई को कितना मिलता है?","optionsHi":["₹2,400","₹3,200","₹1,600","₹2,700"],"explanationHi":"सबसे छोटे को y मिले तो सबसे बड़े को 2y और बीच वाले को 1.5y मिलेंगे, अतः 4.5y = 7,200 और y = 1,600। बीच वाले भाई को 1.5 × 1,600 = ₹2,400 मिलते हैं।","subtopic":"dividing-amounts","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-190","question":"x varies directly as y and inversely as the square of z. If x = 6 when y = 8 and z = 2, what is x when y = 27 and z = 3?","options":["13.5","12","9","27"],"answer":2,"explanation":"x = ky/z², and 6 = k × 8/4 gives k = 3. Then x = 3 × 27/9 = 9. Using z instead of z² gives the trap value 13.5.","difficulty":"hard","questionHi":"x, y के समानुपाती और z के वर्ग के व्युत्क्रमानुपाती है। यदि y = 8 और z = 2 होने पर x = 6 है, तो y = 27 और z = 3 होने पर x क्या होगा?","optionsHi":["13.5","12","9","27"],"explanationHi":"x = ky/z² और 6 = k × 8/4 से k = 3। तब x = 3 × 27/9 = 9। z² की जगह z लेने पर गलत मान 13.5 आता है।","subtopic":"proportion-variation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-191","question":"The cost of a metal rod varies jointly as its length and the square of its diameter. A rod 5 m long with diameter 2 cm costs ₹600. What is the cost of a rod 8 m long with diameter 3 cm?","options":["₹1,440","₹960","₹2,160","₹1,800"],"answer":2,"explanation":"Cost scales by (8/5) × (3/2)² = 1.6 × 2.25 = 3.6, so the cost is 600 × 3.6 = ₹2,160. Using the diameter ratio without squaring gives ₹1,440.","difficulty":"very-hard","questionHi":"एक धातु की छड़ की कीमत उसकी लंबाई और उसके व्यास के वर्ग के संयुक्त समानुपाती है। 5 m लंबी और 2 cm व्यास की छड़ की कीमत ₹600 है। 8 m लंबी और 3 cm व्यास की छड़ की कीमत कितनी होगी?","optionsHi":["₹1,440","₹960","₹2,160","₹1,800"],"explanationHi":"कीमत (8/5) × (3/2)² = 1.6 × 2.25 = 3.6 गुना हो जाती है, अतः कीमत 600 × 3.6 = ₹2,160। व्यास का अनुपात बिना वर्ग किए लेने पर ₹1,440 आता है।","subtopic":"proportion-variation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-192","question":"A fort has food for 400 soldiers for 31 days. After 28 days, 280 soldiers leave. For how many more days will the remaining food last the soldiers who stay?","options":["10 days","3 days","12 days","8 days"],"answer":0,"explanation":"Total food is 400 × 31 man-days; 28 days use 400 × 28, leaving 400 × 3 = 1,200 man-days. For the 120 soldiers who stay, that lasts 1,200/120 = 10 days.","difficulty":"hard","questionHi":"एक किले में 400 सैनिकों के लिए 31 दिन का भोजन है। 28 दिन बाद 280 सैनिक चले जाते हैं। शेष भोजन बचे हुए सैनिकों के लिए और कितने दिन चलेगा?","optionsHi":["10 दिन","3 दिन","12 दिन","8 दिन"],"explanationHi":"कुल भोजन 400 × 31 व्यक्ति-दिन है; 28 दिन में 400 × 28 खर्च हुए, शेष 400 × 3 = 1,200 व्यक्ति-दिन। बचे हुए 120 सैनिकों के लिए यह 1,200/120 = 10 दिन चलेगा।","subtopic":"proportion-variation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-193","question":"Three positive numbers are in continued proportion. Their product is 1,728 and the sum of the first and the third is 30. What is the largest of the three numbers?","options":["18","12","27","24"],"answer":3,"explanation":"For a, b, c in continued proportion, b³ = abc = 1,728 so b = 12 and ac = 144. With a + c = 30, the numbers are the roots of t² − 30t + 144 = 0, namely 6 and 24, so the largest is 24.","difficulty":"hard","questionHi":"तीन धनात्मक संख्याएँ सतत अनुपात में हैं। उनका गुणनफल 1,728 है और पहली तथा तीसरी का योग 30 है। तीनों में सबसे बड़ी संख्या कौन-सी है?","optionsHi":["18","12","27","24"],"explanationHi":"सतत अनुपात में a, b, c के लिए b³ = abc = 1,728, अतः b = 12 और ac = 144। a + c = 30 होने पर संख्याएँ t² − 30t + 144 = 0 के मूल 6 और 24 हैं, इसलिए सबसे बड़ी 24 है।","subtopic":"proportion-variation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-194","question":"If (a + b) : (b + c) : (c + a) = 6 : 7 : 8 and a + b + c = 21, what is the largest of a, b and c?","options":["8","9","7","10"],"answer":1,"explanation":"Adding the three sums gives 2(a + b + c) = 21k = 42, so k = 2: a + b = 12, b + c = 14, c + a = 16. Then c = 21 − 12 = 9, a = 21 − 14 = 7 and b = 5, so the largest is 9.","difficulty":"very-hard","questionHi":"यदि (a + b) : (b + c) : (c + a) = 6 : 7 : 8 और a + b + c = 21 है, तो a, b और c में सबसे बड़ा मान क्या है?","optionsHi":["8","9","7","10"],"explanationHi":"तीनों योगों को जोड़ने पर 2(a + b + c) = 21k = 42, अतः k = 2: a + b = 12, b + c = 14, c + a = 16। तब c = 21 − 12 = 9, a = 21 − 14 = 7 और b = 5, इसलिए सबसे बड़ा मान 9 है।","subtopic":"proportion-variation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-195","question":"4 pens cost the same as 3 notebooks, and 5 notebooks cost the same as 2 bags. If a bag costs ₹150, what is the cost of 12 pens?","options":["₹450","₹540","₹360","₹600"],"answer":1,"explanation":"5 notebooks = 2 × 150 = ₹300, so a notebook costs ₹60. Then 4 pens = 3 × 60 = ₹180, a pen costs ₹45 and 12 pens cost ₹540.","difficulty":"very-hard","questionHi":"4 पेनों की कीमत 3 कॉपियों के बराबर है और 5 कॉपियों की कीमत 2 बैगों के बराबर है। यदि एक बैग की कीमत ₹150 है, तो 12 पेनों की कीमत कितनी होगी?","optionsHi":["₹450","₹540","₹360","₹600"],"explanationHi":"5 कॉपियाँ = 2 × 150 = ₹300, अतः एक कॉपी ₹60 की है। तब 4 पेन = 3 × 60 = ₹180, एक पेन ₹45 का है और 12 पेनों की कीमत ₹540 है।","subtopic":"proportion-variation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-196","question":"A invests ₹36,000 for the whole year. B joins 4 months later. At the end of the year the profit is shared equally. What capital did B invest?","options":["₹48,000","₹72,000","₹108,000","₹54,000"],"answer":3,"explanation":"Equal profit means equal capital × time: 36,000 × 12 = B × 8, so B = ₹54,000. B invested for only 12 − 4 = 8 months.","difficulty":"hard","questionHi":"A पूरे वर्ष के लिए ₹36,000 निवेश करता है। B 4 महीने बाद जुड़ता है। वर्ष के अंत में लाभ बराबर बाँटा जाता है। B ने कितनी पूँजी लगाई?","optionsHi":["₹48,000","₹72,000","₹108,000","₹54,000"],"explanationHi":"लाभ बराबर होने का अर्थ है पूँजी × समय बराबर: 36,000 × 12 = B × 8, अतः B = ₹54,000। B ने केवल 12 − 4 = 8 महीने निवेश किया।","subtopic":"partnership","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-197","question":"A and B start a business with ₹30,000 and ₹20,000. After 4 months A withdraws ₹10,000, and 4 months later B adds ₹15,000. At the end of the year the profit is ₹14,500. What is A's share?","options":["₹7,000","₹7,500","₹8,700","₹6,200"],"answer":0,"explanation":"A: 30,000 × 4 + 20,000 × 8 = 280,000; B: 20,000 × 8 + 35,000 × 4 = 300,000. The ratio is 14 : 15, so A gets 14/29 × 14,500 = ₹7,000. The opening ratio 3 : 2 would give ₹8,700.","difficulty":"very-hard","questionHi":"A और B ₹30,000 और ₹20,000 से व्यापार शुरू करते हैं। 4 महीने बाद A ₹10,000 निकाल लेता है और उसके 4 महीने बाद B ₹15,000 और लगाता है। वर्ष के अंत में लाभ ₹14,500 है। A का हिस्सा कितना है?","optionsHi":["₹7,000","₹7,500","₹8,700","₹6,200"],"explanationHi":"A: 30,000 × 4 + 20,000 × 8 = 280,000; B: 20,000 × 8 + 35,000 × 4 = 300,000। अनुपात 14 : 15 है, अतः A को 14/29 × 14,500 = ₹7,000 मिलते हैं। शुरुआती अनुपात 3 : 2 लेने पर ₹8,700 आता है।","subtopic":"partnership","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-198","question":"In a partnership A puts in 1/2 of the capital for 1/4 of the time, B puts in 1/3 of the capital for 1/2 of the time, and C puts in the rest of the capital for the whole time. Out of a profit of ₹6,600, what does A get?","options":["₹3,300","₹2,400","₹1,800","₹1,200"],"answer":2,"explanation":"C's capital is 1 − 1/2 − 1/3 = 1/6. Capital × time: A = 1/8, B = 1/6, C = 1/6, i.e. 3 : 4 : 4 (11 parts). A gets 3/11 × 6,600 = ₹1,800. Using capitals alone gives ₹3,300.","difficulty":"hard","questionHi":"एक साझेदारी में A कुल पूँजी का 1/2 भाग समय के 1/4 भाग के लिए, B पूँजी का 1/3 भाग समय के 1/2 भाग के लिए और C शेष पूँजी पूरे समय के लिए लगाता है। ₹6,600 के लाभ में से A को कितना मिलेगा?","optionsHi":["₹3,300","₹2,400","₹1,800","₹1,200"],"explanationHi":"C की पूँजी 1 − 1/2 − 1/3 = 1/6 है। पूँजी × समय: A = 1/8, B = 1/6, C = 1/6, अर्थात 3 : 4 : 4 (कुल 11 भाग)। A को 3/11 × 6,600 = ₹1,800 मिलते हैं। केवल पूँजी लेने पर ₹3,300 आता है।","subtopic":"partnership","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-199","question":"A and B invest ₹2 lakh and ₹3 lakh for the whole year. A manages the firm and draws ₹1,500 per month as salary. The yearly profit before salary is ₹66,000, and what remains after the salary is shared in the ratio of capitals. What is A's total income from the firm?","options":["₹26,400","₹19,200","₹37,200","₹30,000"],"answer":2,"explanation":"Salary = 1,500 × 12 = 18,000, leaving 66,000 − 18,000 = 48,000, of which A gets 2/5 = 19,200. A's total = 18,000 + 19,200 = ₹37,200; ₹19,200 leaves out the salary.","difficulty":"very-hard","questionHi":"A और B पूरे वर्ष के लिए ₹2 लाख और ₹3 लाख निवेश करते हैं। A फर्म का प्रबंधन करता है और वेतन के रूप में ₹1,500 प्रति माह लेता है। वेतन से पहले वार्षिक लाभ ₹66,000 है और वेतन के बाद जो बचता है वह पूँजी के अनुपात में बाँटा जाता है। फर्म से A की कुल आय कितनी है?","optionsHi":["₹26,400","₹19,200","₹37,200","₹30,000"],"explanationHi":"वेतन = 1,500 × 12 = 18,000, शेष 66,000 − 18,000 = 48,000, जिसमें से A को 2/5 = 19,200 मिलते हैं। A की कुल आय = 18,000 + 19,200 = ₹37,200; ₹19,200 में वेतन शामिल नहीं है।","subtopic":"partnership","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-200","question":"Two partners invest capitals in the ratio 3 : 5 and their profits are in the ratio 9 : 10. If the second partner's money was invested for 8 months, for how many months was the first partner's money invested?","options":["12 months","10 months","14 months","15 months"],"answer":0,"explanation":"Profit ratio = capital ratio × time ratio, so the time ratio is (9/3) : (10/5) = 3 : 2. If the second money stayed 8 months, the first stayed 8 × 3/2 = 12 months.","difficulty":"moderate","questionHi":"दो साझेदारों की पूँजी का अनुपात 3 : 5 है और उनके लाभ का अनुपात 9 : 10 है। यदि दूसरे साझेदार का धन 8 महीने के लिए लगा था, तो पहले साझेदार का धन कितने महीने के लिए लगा था?","optionsHi":["12 महीने","10 महीने","14 महीने","15 महीने"],"explanationHi":"लाभ का अनुपात = पूँजी का अनुपात × समय का अनुपात, अतः समय का अनुपात (9/3) : (10/5) = 3 : 2। यदि दूसरे का धन 8 महीने रहा, तो पहले का धन 8 × 3/2 = 12 महीने रहा।","subtopic":"partnership","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-201","question":"Two varieties of sugar at ₹40 and ₹55 per kg are mixed, and the mixture is sold at ₹56 per kg at a profit of 20%. In what ratio were the cheaper and the dearer sugar mixed?","options":["4 : 5","3 : 2","2 : 1","5 : 4"],"answer":3,"explanation":"Cost price of the mixture = 56/1.2 = ₹140/3 per kg. Alligation: cheaper : dearer = (55 − 140/3) : (140/3 − 40) = 25/3 : 20/3 = 5 : 4.","difficulty":"very-hard","questionHi":"₹40 और ₹55 प्रति kg वाली चीनी की दो किस्मों को मिलाया जाता है और मिश्रण को ₹56 प्रति kg पर 20% लाभ से बेचा जाता है। सस्ती और महँगी चीनी किस अनुपात में मिलाई गई?","optionsHi":["4 : 5","3 : 2","2 : 1","5 : 4"],"explanationHi":"मिश्रण का क्रय मूल्य = 56/1.2 = ₹140/3 प्रति kg। मिश्रण नियम से सस्ती : महँगी = (55 − 140/3) : (140/3 − 40) = 25/3 : 20/3 = 5 : 4।","subtopic":"mixtures-alligation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-202","question":"A 5 kg alloy of gold and silver has them in the ratio 2 : 3. How much pure gold must be added to make the alloy 60% gold?","options":["2 kg","2.5 kg","3 kg","1.5 kg"],"answer":1,"explanation":"Silver stays 3 kg and must be 40% of the new alloy, so the new total is 7.5 kg and 7.5 − 5 = 2.5 kg of gold must be added.","difficulty":"moderate","questionHi":"सोने और चाँदी के 5 kg के एक मिश्रधातु में सोना और चाँदी 2 : 3 के अनुपात में हैं। इसमें कितना शुद्ध सोना मिलाया जाए कि मिश्रधातु में सोना 60% हो जाए?","optionsHi":["2 kg","2.5 kg","3 kg","1.5 kg"],"explanationHi":"चाँदी 3 kg ही रहेगी और नई मिश्रधातु का 40% होनी चाहिए, अतः नया कुल भार 7.5 kg होगा और 7.5 − 5 = 2.5 kg सोना मिलाना होगा.","subtopic":"mixtures-alligation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-203","question":"A trader mixes two grades of rice at ₹50 and ₹70 per kg in the ratio 3 : 2. At what price per kg must he sell the mixture to earn a profit of 25%?","options":["₹77.50","₹72.50","₹75.00","₹70.50"],"answer":1,"explanation":"Cost of the mixture = (3 × 50 + 2 × 70)/5 = ₹58 per kg, so the selling price is 58 × 1.25 = ₹72.50. Swapping the weights (2 : 3) gives cost ₹62 and the wrong ₹77.50.","difficulty":"very-hard","questionHi":"एक व्यापारी ₹50 और ₹70 प्रति kg वाले चावल की दो किस्मों को 3 : 2 के अनुपात में मिलाता है। 25% लाभ कमाने के लिए उसे मिश्रण को प्रति kg किस मूल्य पर बेचना चाहिए?","optionsHi":["₹77.50","₹72.50","₹75.00","₹70.50"],"explanationHi":"मिश्रण का क्रय मूल्य = (3 × 50 + 2 × 70)/5 = ₹58 प्रति kg, अतः विक्रय मूल्य 58 × 1.25 = ₹72.50। भार उलटने (2 : 3) पर क्रय मूल्य ₹62 और गलत उत्तर ₹77.50 आता है.","subtopic":"mixtures-alligation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-204","question":"Acid solutions of strength 10% and 20% are mixed in equal volumes. This mixture is then mixed with a 40% acid solution in the ratio 2 : 1 by volume. What is the strength of the final solution?","options":["25%","22.5%","20%","23⅓%"],"answer":3,"explanation":"The first mixture is (10 + 20)/2 = 15%. Final strength = (2 × 15 + 1 × 40)/3 = 70/3 = 23⅓%. A simple average of 15% and 40% would wrongly give 27.5%, so the 2 : 1 weights must be used.","difficulty":"hard","questionHi":"10% और 20% सांद्रता वाले अम्ल के विलयनों को बराबर आयतन में मिलाया जाता है। फिर इस मिश्रण को 40% अम्ल विलयन के साथ आयतन के अनुसार 2 : 1 के अनुपात में मिलाया जाता है। अंतिम विलयन की सांद्रता क्या है?","optionsHi":["25%","22.5%","20%","23⅓%"],"explanationHi":"पहला मिश्रण (10 + 20)/2 = 15% का है। अंतिम सांद्रता = (2 × 15 + 1 × 40)/3 = 70/3 = 23⅓%। 15% और 40% का साधारण औसत लेने पर गलत 27.5% आता, इसलिए 2 : 1 के भारांक लेने होते हैं।","subtopic":"mixtures-alligation","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-205","question":"If a : b = 3 : 4 and x : y = 5 : 6, what is the ratio (3ax − 2by) : (4by − 7ax)?","options":["1 : 3","3 : 1","2 : 5","1 : 2"],"answer":0,"explanation":"Take a = 3, b = 4, x = 5, y = 6: ax = 15 and by = 24. So (45 − 48) : (96 − 105) = (−3) : (−9) = 1 : 3. Both terms are negative, so the ratio is positive.","difficulty":"hard","questionHi":"यदि a : b = 3 : 4 और x : y = 5 : 6 है, तो (3ax − 2by) : (4by − 7ax) का अनुपात क्या है?","optionsHi":["1 : 3","3 : 1","2 : 5","1 : 2"],"explanationHi":"a = 3, b = 4, x = 5, y = 6 लें: ax = 15 और by = 24। अतः (45 − 48) : (96 − 105) = (−3) : (−9) = 1 : 3। दोनों पद ऋणात्मक हैं, इसलिए अनुपात धनात्मक है।","subtopic":"ratio-basics","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-206","question":"Two numbers are in the ratio 4 : 5 and the sum of their LCM and HCF is 189. What is the sum of the two numbers?","options":["90","72","81","108"],"answer":2,"explanation":"The numbers are 4k and 5k with HCF k and LCM 20k, so 21k = 189 and k = 9. The numbers are 36 and 45, with sum 81.","difficulty":"hard","questionHi":"दो संख्याओं का अनुपात 4 : 5 है और उनके LCM तथा HCF का योग 189 है। दोनों संख्याओं का योग कितना है?","optionsHi":["90","72","81","108"],"explanationHi":"संख्याएँ 4k और 5k हैं जिनका HCF k और LCM 20k है, अतः 21k = 189 और k = 9। संख्याएँ 36 और 45 हैं, जिनका योग 81 है।","subtopic":"ratio-basics","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-207","question":"The digits of a two-digit number are in the ratio 3 : 2, and the number exceeds the number formed by reversing its digits by 18. What is the number?","options":["46","96","64","32"],"answer":2,"explanation":"Digits are 3k and 2k, so the number minus its reverse is 9(3k − 2k) = 9k = 18, giving k = 2 and the number 64. 46 is the reverse, which is smaller.","difficulty":"moderate","questionHi":"एक दो अंकीय संख्या के अंकों का अनुपात 3 : 2 है और वह संख्या अपने अंकों को उलटने से बनी संख्या से 18 अधिक है। वह संख्या क्या है?","optionsHi":["46","96","64","32"],"explanationHi":"अंक 3k और 2k हैं, अतः संख्या − उसका उलटा = 9(3k − 2k) = 9k = 18, जिससे k = 2 और संख्या 64। 46 उलटी संख्या है, जो छोटी है।","subtopic":"ratio-basics","source":"SSC CGL Tier 2 · IBPS PO Mains"},
  {"id":"quant-ratio-208","question":"A box has red, green and blue balls in the ratio 5 : 4 : 3. When 6 red balls are removed and 6 blue balls are added, the numbers of red and blue balls become equal. How many balls were in the box originally?","options":["72","60","84","48"],"answer":0,"explanation":"5k − 6 = 3k + 6 gives k = 6, so the balls are 30 red, 24 green and 18 blue, 72 in all.","difficulty":"very-hard","questionHi":"एक डिब्बे में लाल, हरी और नीली गेंदें 5 : 4 : 3 के अनुपात में हैं। 6 लाल गेंदें निकालने और 6 नीली गेंदें डालने पर लाल और नीली गेंदों की संख्या बराबर हो जाती है। डिब्बे में मूल रूप से कितनी गेंदें थीं?","optionsHi":["72","60","84","48"],"explanationHi":"5k − 6 = 3k + 6 से k = 6, अतः गेंदें 30 लाल, 24 हरी और 18 नीली हैं, कुल 72।","subtopic":"ratio-basics","source":"SSC CGL Tier 2 · IBPS PO Mains"},
];

export default questions;
